INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：做了不对的事，与“学生在教室里吃东西就是……”的判断相合，是正确答案。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是赞许好的行为，与“在教室里吃东西”的负面判断矛盾。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对好行为的回报，在教室吃东西不应得到奖励，句意不通。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”指中午睡觉，与“吃东西”无关，句意不通。"}], "explanations": {"违规": "违规：做了不对的事，与“学生在教室里吃东西就是……”的判断相合，是正确答案。", "表扬": "语义：“表扬”是赞许好的行为，与“在教室里吃东西”的负面判断矛盾。", "奖励": "语义：“奖励”是对好行为的回报，在教室吃东西不应得到奖励，句意不通。", "午睡": "语义：“午睡”指中午睡觉，与“吃东西”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他当众说错话，显得很违规。", "explanation": "这里应该用〈失礼〉。违规指违反规定，不用于形容言行不得体。"}, {"text": "我今天吃了很多蔬菜，真违规。", "explanation": "这里应该用〈健康〉。违规指违反规定，不用于形容吃蔬菜这类健康的行为。"}, {"text": "这台机器违规了，需要维修。", "explanation": "这里应该用〈故障〉。违规的主体是人或行为，机器不能违规，应说出现故障。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违规", "is_correct": true, "explanation": "违规：做了不对的事，与“他开会时睡觉，大家都说他……”的评价相合，是正确答案。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”是肯定和支持，与“大家都说他”后面的批评性评价矛盾。"}, {"text": "通报", "is_correct": false, "explanation": "语义：“通报”指告知情况，不是对行为的评价，与“大家都说他”的评价语境不合。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”指关心和帮助，与开会睡觉的负面行为无关，句意不通。"}], "explanations": {"违规": "违规：做了不对的事，与“他开会时睡觉，大家都说他……”的评价相合，是正确答案。", "鼓励": "语义：“鼓励”是肯定和支持，与“大家都说他”后面的批评性评价矛盾。", "通报": "语义：“通报”指告知情况，不是对行为的评价，与“大家都说他”的评价语境不合。", "照顾": "语义：“照顾”指关心和帮助，与开会睡觉的负面行为无关，句意不通。"}, "sentence_index": 6, "correct_answer": "违规"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试的题目很违规，大家都没做完。", "explanation": "这里应该用〈难〉。违规指违反规定，不用于形容题目难度。"}, {"text": "这个学生很违规，每天都早起读书。", "explanation": "这里应该用〈刻苦〉。违规指违反规定，不用于形容学习认真。"}, {"text": "他见到老师很违规，主动问好。", "explanation": "这里应该用〈礼貌〉。违规不用于形容言行有礼貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在课堂上睡觉，被违规了。", "corrected_sentence": "他在课堂上睡觉，违规了。", "error_description": "被字句错误：“违规”不能用于被动句，应说“他违规了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26016, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在图书馆里大声喧哗，违规了过。", "corrected_sentence": "她在图书馆里大声喧哗，违规了。", "error_description": "体标错误：“了”和“过”不能连用，应说“违规了”或“违规过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
