INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "已经有的东西或事情。", "primary_collocate": null, "pronunciation": "yǐ yǒu", "ipa": "i˨˩˦ joʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "已有的电脑用了五年，该换新的了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de diàn nǎo yòng le wǔ nián gāi huàn xīn de le", "sentence_source": "generated"}, {"text": "已有的座位都满了，请你等一下。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de zuò wèi dōu mǎn le qǐng nǐ děng yí xià", "sentence_source": "generated"}, {"text": "已有的衣服够穿，我不想再买。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没去相亲，因为他很珍惜已有的感情。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā méi qù xiàng qīn yīn wèi tā hěn zhēn xī yǐ yǒu de gǎn qíng", "sentence_source": "generated"}, {"text": "请先用完已有的牛奶，再买新的。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "已有的答案很清楚，不用再讨论了。", "target_word": "已有", "complexity_tier": "T3", "furigana": "yǐ yǒu de dá àn hěn qīng chu bú yòng zài tǎo lùn le", "sentence_source": "generated"}, {"text": "家里已有的两辆自行车足够了，不需要第三辆。", "target_word": "已有", "complexity_tier": "T3", "furigana": "jiā li yǐ yǒu de liǎng liàng zì xíng chē zú gòu le bù xū yào dì sān liàng", "sentence_source": "generated"}, {"text": "这本书是图书馆已有的，你可以去借。", "target_word": "已有", "complexity_tier": "T3", "furigana": "zhè běn shū shì tú shū guǎn yǐ yǒu de nǐ kě yǐ qù jiè", "sentence_source": "generated"}, {"text": "他对已有的工作流程很熟，做事很快。", "target_word": "已有", "complexity_tier": "T3", "furigana": "tā duì yǐ yǒu de gōng zuò liú chéng hěn shú zuò shì hěn kuài", "sentence_source": "generated"}, {"text": "已有的计划不能改，只能照做。", "target_word": "已有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已有：已经有的东西或事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“已有的电脑”指已经有的电脑，与“用了五年，该换新的了”相呼应。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是动作，不能修饰“电脑”，句意不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是动作，不能用来修饰“电脑”。"}, {"text": "搞", "is_correct": false, "explanation": "语义：“搞”指做、弄，不能修饰“电脑”表示“已经有的”，句意不通。"}], "explanations": {"已有": "正确。“已有的电脑”指已经有的电脑，与“用了五年，该换新的了”相呼应。", "吃": "语义：“吃”是动作，不能修饰“电脑”，句意不通。", "唱": "语义：“唱”是动作，不能用来修饰“电脑”。", "搞": "语义：“搞”指做、弄，不能修饰“电脑”表示“已经有的”，句意不通。"}, "sentence_index": 0, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天的会议已有很多人来了，大家都很忙。", "explanation": "这里应该用〈将有〉。“已有”指已经存在，明天的会议还没有召开，不能说很多人已经来了。"}, {"text": "下个月的活动已有我们的老师出席过了。", "explanation": "这里应该用〈将会〉。“已有”指已经存在，下个月的活动还没有举行，不能说老师已经出席过。"}, {"text": "后天的比赛已有很多选手到场了。", "explanation": "这里应该用〈将要〉。“已有”指已经存在，后天的比赛尚未开始，不能说选手已经到场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "已有", "is_correct": true, "explanation": "正确。“家里已有的两辆自行车”指家里已经有的两辆自行车，句意通顺。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”是动作，不能用来修饰“两辆自行车”。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”是动作，不能用来修饰“自行车”，句意不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”指成婚，不能用来修饰“自行车”，句意不通。"}], "explanations": {"已有": "正确。“家里已有的两辆自行车”指家里已经有的两辆自行车，句意通顺。", "写": "语义：“写”是动作，不能用来修饰“两辆自行车”。", "打": "语义：“打”是动作，不能用来修饰“自行车”，句意不通。", "结婚": "语义：“结婚”指成婚，不能用来修饰“自行车”，句意不通。"}, "sentence_index": 6, "correct_answer": "已有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明年的计划已有很多人执行过了。", "explanation": "这里应该用〈将要〉。“已有”指已经存在，明年的计划还没有开始实施，不能说很多人已经执行过。"}, {"text": "这次开会的计划已有很多人明天参加。", "explanation": "这里应该用〈会有〉。“已有”指已经存在，与“明天”矛盾，应说“明天会有很多人参加”。"}, {"text": "下周的旅行已有我们全家一起去过了。", "explanation": "这里应该用〈将要〉。“已有”指已经存在，下周的旅行尚未开始，不能说全家已经去过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家里已有得很多花。", "corrected_sentence": "我家里已有很多花。", "error_description": "助词误用：“得”不能插在“已有”和宾语之间，“已有得很多花”应改为“已有很多花”，去掉多余的“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家里已有电脑很新。", "corrected_sentence": "我家里已有的电脑很新。", "error_description": "定语标志漏“的”：“已有”修饰“电脑”时要加“的”，“已有电脑”应改为“已有的电脑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
