INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "禁令是不许做某件事的规定。", "primary_collocate": null, "pronunciation": "jìn lìng", "ipa": "tɕin⁵¹ liŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "学校有一条禁令：上课不许玩手机。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条禁令很清楚，大家都要遵守。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的禁令说，办公室里不能抽烟。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院走廊里贴着一条禁令：不许在病房里吸烟。", "target_word": "禁令", "complexity_tier": "T3", "furigana": "yī yuàn zǒu láng lǐ tiē zhe yì tiáo jìn lìng bù xǔ zài bìng fáng lǐ xī yān", "sentence_source": "generated"}, {"text": "他没看到禁令，还在草地上踢球。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这个禁令是为了大家的安全。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给家里定了一条禁令：晚上十点后不看电视。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的牌子上写着禁令：不许游泳。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个禁令已经有十年了，现在还有用。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都不喜欢家里的新禁令。", "target_word": "禁令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "项", "label": "量词"}], "register": "书面", "sense_fingerprint": "不许做某件事的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5df597c-7f63-48fe-bae5-e2a999fa4fe0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“学校有一条……：上课不许玩手机”的规定内容相合，是正确答案。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”是菜谱，与“上课不许玩手机”的禁止内容无关，句子不通。"}, {"text": "奖状", "is_correct": false, "explanation": "语义：“奖状”是表彰证书，不是禁止规定，与后面的禁止内容矛盾。"}, {"text": "课表", "is_correct": false, "explanation": "语义：“课表”是课程安排表，不是禁止性规定，与句中的禁止内容不符。"}], "explanations": {"禁令": "禁令：与“学校有一条……：上课不许玩手机”的规定内容相合，是正确答案。", "食谱": "语义：“食谱”是菜谱，与“上课不许玩手机”的禁止内容无关，句子不通。", "奖状": "语义：“奖状”是表彰证书，不是禁止规定，与后面的禁止内容矛盾。", "课表": "语义：“课表”是课程安排表，不是禁止性规定，与句中的禁止内容不符。"}, "sentence_index": 0, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校贴出一条禁令，要求每位学生都穿校服。", "explanation": "这里应该用〈规定〉。禁令专指禁止某种行为，要求穿校服属于一般规定。"}, {"text": "医院走廊里贴着一条禁令：下周三有体检。", "explanation": "这里应该用〈通知〉。禁令是禁止性的规定，不用于告知体检时间。"}, {"text": "妈妈给我一条禁令，提醒我带好雨伞。", "explanation": "这里应该用〈叮嘱〉。禁令是不许做某事的规定，不用于叮嘱人做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "禁令", "is_correct": true, "explanation": "禁令：与“定了一条……：晚上十点后不看电视”的约束内容相合，是正确答案。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“定”多接规定、规则，不能说“定了一条座位”。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：“歌词”是歌曲的文字，与“晚上十点后不看电视”的约束内容无关。"}, {"text": "名言", "is_correct": false, "explanation": "语义：“名言”是有道理的格言，没有约束力，不能用来“定”下不看电视的要求。"}], "explanations": {"禁令": "禁令：与“定了一条……：晚上十点后不看电视”的约束内容相合，是正确答案。", "座位": "搭配：“定”多接规定、规则，不能说“定了一条座位”。", "歌词": "语义：“歌词”是歌曲的文字，与“晚上十点后不看电视”的约束内容无关。", "名言": "语义：“名言”是有道理的格言，没有约束力，不能用来“定”下不看电视的要求。"}, "sentence_index": 6, "correct_answer": "禁令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爸爸给大家发了一份禁令，邀请我们周末去公园。", "explanation": "这里应该用〈请柬〉。禁令是不许做某事的规定，不用于发出邀请这类事项。"}, {"text": "老师写了一条禁令，评价我的作文很好。", "explanation": "这里应该用〈评语〉。禁令是不许做某事的规定，不用于对作文作出评价。"}, {"text": "妈妈定了一条禁令，计划下周去旅行。", "explanation": "这里应该用〈打算〉。禁令是不许做某事的规定，不能用来表示对未来活动的打算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里有一只禁令：不许在教室里吃东西。", "corrected_sentence": "班里有一条禁令：不许在教室里吃东西。", "error_description": "量词错误：“禁令”的量词应为“条”（或“项”），“只”多用于动物，不能用于“禁令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈定了一只禁令：晚饭前不许吃零食。", "corrected_sentence": "妈妈定了一条禁令：晚饭前不许吃零食。", "error_description": "量词错误：“禁令”的量词应为“条”（或“项”），“只”多用于动物，不能用于“禁令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89aab5bf-f104-4ab8-958d-d27bc571e793') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
