INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "取向就是你喜欢什么或者选择什么。", "primary_collocate": null, "pronunciation": "qǔ xiàng", "ipa": "tɕʰy˨˩˦ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们每个人的取向都不同。", "target_word": "取向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不了解他的取向。", "target_word": "取向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的取向是安静的生活。", "target_word": "取向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买东西时，年轻人的取向变了。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的取向不一样，吃饭很难选。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要尊重别人的取向。", "target_word": "取向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喜欢旅行，取向很清楚。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想知道学生的阅读取向。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对颜色的取向很固定，只穿黑色衣服。", "target_word": "取向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问卷可以看出大家的取向。", "target_word": "取向", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种取向", "label": "量词"}, {"form": "价值取向", "label": "复合"}, {"form": "性取向", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人喜欢或选择的倾向（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”指气象状况，不属于每个人的特征，句意不通。"}, {"text": "取向", "is_correct": true, "explanation": "取向：指个人喜欢或选择的倾向，“每个人的取向都不同”说明人们的倾向各异，句中正确。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”用于场地、土地，不说“每个人的面积”。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”指地点的高度，不能用来说人，句子不通。"}], "explanations": {"天气": "语义：“天气”指气象状况，不属于每个人的特征，句意不通。", "取向": "取向：指个人喜欢或选择的倾向，“每个人的取向都不同”说明人们的倾向各异，句中正确。", "面积": "搭配：“面积”用于场地、土地，不说“每个人的面积”。", "海拔": "语义：“海拔”指地点的高度，不能用来说人，句子不通。"}, "sentence_index": 0, "correct_answer": "取向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的取向很清楚，一路从北往南流。", "explanation": "这里应该用〈流向〉。取向指人的选择或倾向，河水的流动方向要用〈流向〉。"}, {"text": "这座山脉的取向很明显，从东到西延伸。", "explanation": "这里应该用〈走向〉。取向指人的选择或倾向，山脉的延伸方向要用〈走向〉。"}, {"text": "这套房子的取向很好，冬天有阳光。", "explanation": "这里应该用〈朝向〉。取向指人的选择或倾向，房屋朝哪个方向要用〈朝向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分量", "is_correct": false, "explanation": "语义：“分量”指重量或份量，不能用来说明人的喜好是否清楚，句子不通。"}, {"text": "取向", "is_correct": true, "explanation": "取向：指个人喜欢或选择的倾向，“他喜欢旅行，取向很清楚”说明他的偏好鲜明，句中正确。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：“亮度”指光的明暗，与喜好无关，放入句中读不通。"}, {"text": "音量", "is_correct": false, "explanation": "搭配：“清楚”用于说明、想法等，不能与“音量”搭配，“音量很清楚”不成立。"}], "explanations": {"分量": "语义：“分量”指重量或份量，不能用来说明人的喜好是否清楚，句子不通。", "取向": "取向：指个人喜欢或选择的倾向，“他喜欢旅行，取向很清楚”说明他的偏好鲜明，句中正确。", "亮度": "语义：“亮度”指光的明暗，与喜好无关，放入句中读不通。", "音量": "搭配：“清楚”用于说明、想法等，不能与“音量”搭配，“音量很清楚”不成立。"}, "sentence_index": 6, "correct_answer": "取向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个病人有发烧的取向，需要多观察。", "explanation": "这里应该用〈倾向〉。取向指人对喜好或选择的方向，“有…的倾向”描述发烧这类病情苗头时要用〈倾向〉。"}, {"text": "他从小立下宏伟的取向，想成为宇航员。", "explanation": "这里应该用〈志向〉。取向指喜好或选择，立下的宏伟理想和奋斗目标要用〈志向〉。"}, {"text": "这条路的取向很清楚，一直通到山顶。", "explanation": "这里应该用〈方向〉。取向指人的选择或喜好，道路延伸的方向要用〈方向〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的生活取向得很简单，不爱买东西。", "corrected_sentence": "她的生活取向很简单，不爱买东西。", "error_description": "助词错误：“得”是补语标记，只能接在动词或形容词后；“生活取向”是名词作主语，后面直接接“很简单”，不能加“得”。正确说法是「她的生活取向很简单」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一把独特的取向，喜欢自己动手做饭。", "corrected_sentence": "他有一种独特的取向，喜欢自己动手做饭。", "error_description": "量词错误：“取向”应用量词“种”，不能用“把”（“把”用于带柄的东西）。正确说法是「一种独特的取向」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放纵", "is_correct": true, "explanation": "反义：“放纵”指任由自己或他人不受约束，与“约束”相对。"}, {"text": "陪伴", "is_correct": false, "explanation": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。"}, {"text": "检查", "is_correct": false, "explanation": "无反义关系：“检查”是查看核实，与“约束”不是对立关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}], "correct_answer": "放纵", "explanations": {"放纵": "反义：“放纵”指任由自己或他人不受约束，与“约束”相对。", "陪伴": "无反义关系：“陪伴”是跟随相伴，与“约束”不构成反义。", "检查": "无反义关系：“检查”是查看核实，与“约束”不是对立关系。", "欢迎": "无反义关系：“欢迎”是表示接纳的态度，与“约束”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "反义：“放任”指任其自由、不加限制，与“约束”相对。"}, {"text": "尊重", "is_correct": false, "explanation": "无反义关系：“尊重”是敬重，与“约束”不构成反义。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”是修复物品，与“约束”不相对。"}, {"text": "表扬", "is_correct": false, "explanation": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}], "correct_answer": "放任", "explanations": {"放任": "反义：“放任”指任其自由、不加限制，与“约束”相对。", "尊重": "无反义关系：“尊重”是敬重，与“约束”不构成反义。", "修理": "无反义关系：“修理”是修复物品，与“约束”不相对。", "表扬": "无反义关系：“表扬”是称赞，不是“约束”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是管住别人或自己，不让他做不该做的事。", "primary_collocate": null, "pronunciation": "yuē shù", "ipa": "ɥe˥ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他很会约束自己。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "父母要约束孩子玩手机的行为。", "target_word": "约束", "complexity_tier": "T3", "furigana": "fù mǔ yào yuē shù hái zi wán shǒu jī de xíng wéi", "sentence_source": "generated"}, {"text": "你应该约束一下自己的脾气。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我约束不了他。", "target_word": "约束", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师约束学生不要在课上说话。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常约束不住自己，一直吃零食。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥要约束自己，少吃甜食。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他约束了自己一个月，没有玩游戏。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子太小，没人约束就会乱跑。", "target_word": "约束", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自由惯了，不喜欢别人约束他。", "target_word": "约束", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "约束了", "label": "体标"}, {"form": "约束过", "label": "体标"}, {"form": "自我约束", "label": "复合"}, {"form": "約束", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管住别人或自己，不让做不该做的事（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指管住自己，不让自己做不该做的事，与句意相符。"}, {"text": "绑架", "is_correct": false, "explanation": "语义：“绑架”是非法扣押他人，不能用于“很会……自己”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”接的是车辆等，不能接“自己”。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”是大批销售货物，不能用在人身上。"}], "explanations": {"约束": "正确：“约束”指管住自己，不让自己做不该做的事，与句意相符。", "绑架": "语义：“绑架”是非法扣押他人，不能用于“很会……自己”。", "驾驶": "搭配：“驾驶”接的是车辆等，不能接“自己”。", "批发": "语义：“批发”是大批销售货物，不能用在人身上。"}, "sentence_index": 0, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校约束学生的宿舍。", "explanation": "这里应该用〈管理〉。“约束”是管住人的行为，不能用于宿舍这类场所。"}, {"text": "他约束着生病的父母。", "explanation": "这里应该用〈照顾〉。“约束”是管住人不让其越界，不表示照料。"}, {"text": "这场大雨约束了一个小时。", "explanation": "这里应该用〈持续〉。“约束”是管住人的行为，不能用来表示时间的长度；大雨的时长应说“持续”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约束", "is_correct": true, "explanation": "正确：“约束”指管住自己，与“减肥要……少吃甜食”的要求相符。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是任由自己，与“少吃甜食”的要求相反。"}, {"text": "纵容", "is_correct": false, "explanation": "语义：“纵容”是迁就、不加制止，与“减肥”的要求相反。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”接的是节目或影像，不能接“自己”。"}], "explanations": {"约束": "正确：“约束”指管住自己，与“减肥要……少吃甜食”的要求相符。", "放纵": "语义：“放纵”是任由自己，与“少吃甜食”的要求相反。", "纵容": "语义：“纵容”是迁就、不加制止，与“减肥”的要求相反。", "播放": "搭配：“播放”接的是节目或影像，不能接“自己”。"}, "sentence_index": 6, "correct_answer": "约束"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈约束孩子的健康。", "explanation": "这里应该用〈关心〉。“约束”的对象是人的行为，不能用于“健康”。"}, {"text": "他约束了那幅美丽的画。", "explanation": "这里应该用〈欣赏〉。“约束”是管住人的行为，不能用于画作；欣赏画作应说“欣赏那幅画”。"}, {"text": "这个乐队约束了那首老歌。", "explanation": "这里应该用〈演唱〉。“约束”是管住人的行为，不能用于歌曲；演唱歌曲应说“演唱那首老歌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对自己约束了很严格。", "corrected_sentence": "他对自己约束得很严格。", "error_description": "体标误用：「了」表示完成，不能直接接形容词作补语；程度补语前应当用「得」。正确说法是「他对自己约束得很严格」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是约束自己着。", "corrected_sentence": "他总是约束自己。", "error_description": "错误：体标“着”放在了句末宾语“自己”之后。正确句中“约束”后直接接宾语，不加“着”，正确应为“他总是约束自己”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
