INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从另一个方面看，就能看到不同的情况。", "primary_collocate": null, "pronunciation": "fǎn guān", "ipa": "fan˨˩˦ kuan˥˥", "syllable_count": 2, "sentences": [{"text": "小李的成绩一直很好，反观小王，常常不及格。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天南方很热，反观北方，晚上还有点凉。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上买东西的人越来越多，反观商店，客人越来越少。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐喜欢吃辣，反观妹妹，一点辣的也不吃。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同学都很安静，反观隔壁班，吵得很。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话总是很客气，反观他的朋友，一点也不礼貌。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市工作机会很多，反观小镇，年轻人都走了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年这家工厂赚了很多钱，反观今年，生意差多了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸身体很好，反观我，经常生病。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左边的房子很新，反观右边的，已经很旧了。", "target_word": "反观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "换到另一方面来看，发现情况不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”表示思念过去的人或事，与成绩的前后对照无关，句意不通。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等，不能说“测量小王”，句子不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从另一方面看，发现不同的情况，“反观小王”引出与小李相反的成绩，句中正确。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”表示称赞，与“常常不及格”的情况相矛盾，句意不通。"}], "explanations": {"怀念": "语义：“怀念”表示思念过去的人或事，与成绩的前后对照无关，句意不通。", "测量": "搭配：“测量”的对象是长度、重量等，不能说“测量小王”，句子不通。", "反观": "反观：从另一方面看，发现不同的情况，“反观小王”引出与小李相反的成绩，句中正确。", "赞美": "语义：“赞美”表示称赞，与“常常不及格”的情况相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在音乐会上反观演奏，非常陶醉。", "explanation": "这里应该用〈聆听〉。反观指引出对照的另一方，不表示用耳朵认真听。"}, {"text": "我们在美术馆反观名画，很有收获。", "explanation": "这里应该用〈欣赏〉。反观指从另一方面看、引出不同的情况，不表示欣赏艺术品。"}, {"text": "站在山上反观大海，心情很好。", "explanation": "这里应该用〈远眺〉。反观指引出对照的情况，不表示向远处望去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赠送", "is_correct": false, "explanation": "搭配：“赠送”的对象是物品或人，不能说“赠送小镇”，句子不通。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指洗涤，与城乡机会的对比无关，句意不通。"}, {"text": "挥舞", "is_correct": false, "explanation": "语义：“挥舞”指挥动，与年轻人外流的情况无关，放入句中读不通。"}, {"text": "反观", "is_correct": true, "explanation": "反观：从另一方面看，发现不同的情况，“反观小镇”引出与大城市相反的情况，句中正确。"}], "explanations": {"赠送": "搭配：“赠送”的对象是物品或人，不能说“赠送小镇”，句子不通。", "清洗": "语义：“清洗”指洗涤，与城乡机会的对比无关，句意不通。", "挥舞": "语义：“挥舞”指挥动，与年轻人外流的情况无关，放入句中读不通。", "反观": "反观：从另一方面看，发现不同的情况，“反观小镇”引出与大城市相反的情况，句中正确。"}, "sentence_index": 6, "correct_answer": "反观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家来到纪念馆，反观烈士的遗像。", "explanation": "这里应该用〈瞻仰〉。反观指引出对照的另一方，不表示恭敬地观看。"}, {"text": "他反观这张旧照片，陷入了回忆。", "explanation": "这里应该用〈端详〉。反观指引出对照的另一方，不表示仔细观察某物。"}, {"text": "他反观手机屏幕，半天没说话。", "explanation": "这里应该用〈盯〉。反观指从另一方面看、引出不同的情况，不表示目不转睛地看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "城里的房价很高，反观，却便宜得多。", "corrected_sentence": "城里的房价很高，反观乡下，却便宜得多。", "error_description": "缺少宾语：“反观”是动词，后面要直接带对照的对象，此处缺少对象；应说「反观乡下」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地今年收成很好，反观，几乎没有收成。", "corrected_sentence": "这块地今年收成很好，反观邻居家的地，几乎没有收成。", "error_description": "缺少宾语：“反观”后面要带对照的对象（邻居家的地），不能单独使用。正确说法是「反观邻居家的地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。"}, {"text": "钱包", "is_correct": false, "explanation": "无反义关系：“钱包”是装钱的物品，与“处罚”无关。"}, {"text": "天气", "is_correct": false, "explanation": "无反义关系：“天气”指气候状况，与“处罚”不构成反义。"}, {"text": "花园", "is_correct": false, "explanation": "无反义关系：“花园”是种植花草的地方，与“处罚”不构成反义。"}], "correct_answer": "奖励", "explanations": {"奖励": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。", "钱包": "无反义关系：“钱包”是装钱的物品，与“处罚”无关。", "天气": "无反义关系：“天气”指气候状况，与“处罚”不构成反义。", "花园": "无反义关系：“花园”是种植花草的地方，与“处罚”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。"}, {"text": "书包", "is_correct": false, "explanation": "无反义关系：“书包”是装书的用品，与“处罚”无关。"}, {"text": "季节", "is_correct": false, "explanation": "无反义关系：“季节”指一年中的时段，与“处罚”不构成反义。"}, {"text": "操场", "is_correct": false, "explanation": "无反义关系：“操场”是进行体育活动的场地，与“处罚”不构成反义。"}], "correct_answer": "奖励", "explanations": {"奖励": "反义：作为名词，“奖励”与“处罚”意思相对，一个是好的回报，一个是惩罚。", "书包": "无反义关系：“书包”是装书的用品，与“处罚”无关。", "季节": "无反义关系：“季节”指一年中的时段，与“处罚”不构成反义。", "操场": "无反义关系：“操场”是进行体育活动的场地，与“处罚”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做了不对的事，就要受到处罚。", "primary_collocate": null, "pronunciation": "chǔ fá", "ipa": "tʂʰu˨˩˦ fa˧˥", "syllable_count": 2, "sentences": [{"text": "做错事就要受到处罚。", "target_word": "处罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他因为迟到受到了处罚。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次的处罚太重了。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给了他一个小小的处罚。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都不想接受处罚。", "target_word": "处罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "违规的处罚是罚款五百元。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不怕处罚，还是继续迟到。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对这种行为，法律有严格的处罚。", "target_word": "处罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认了错误，处罚轻了一些。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中打人的处罚是停赛一场。", "target_word": "处罚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项处罚", "label": "量词"}, {"form": "处罚决定", "label": "复合"}, {"form": "行政处罚", "label": "复合"}, {"form": "處罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做错事后所受的惩罚（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。"}, {"text": "出发", "is_correct": false, "explanation": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。"}, {"text": "除法", "is_correct": false, "explanation": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。"}, {"text": "书法", "is_correct": false, "explanation": "shū fǎ（书法）与 chǔ fá 声母不同（sh 与 ch），声调也不同，意思是写字的艺术。"}, {"text": "词法", "is_correct": false, "explanation": "cí fǎ（词法）与 chǔ fá 声母不同（c 与 ch），声调也不同，意思是词的构成和变化规则。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。", "出发": "chū fā（出发）与 chǔ fá 两个音节的声调都不同，意思是动身、启程。", "除法": "chú fǎ（除法）与 chǔ fá 两个音节的声调都不同，意思是数学中的除法。", "书法": "shū fǎ（书法）与 chǔ fá 声母不同（sh 与 ch），声调也不同，意思是写字的艺术。", "词法": "cí fǎ（词法）与 chǔ fá 声母不同（c 与 ch），声调也不同，意思是词的构成和变化规则。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指做错事后受到的惩罚，与句意相符。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对好表现的回报，与“做错事”相矛盾。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“做错事”相矛盾。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“受到”后面接“礼物”不自然，应说“收到礼物”。"}], "explanations": {"处罚": "正确：“处罚”指做错事后受到的惩罚，与句意相符。", "奖励": "语义：“奖励”是对好表现的回报，与“做错事”相矛盾。", "表扬": "语义：“表扬”是称赞，与“做错事”相矛盾。", "礼物": "搭配：“受到”后面接“礼物”不自然，应说“收到礼物”。"}, "sentence_index": 0, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次违规要交五百元处罚。", "explanation": "这里应该用〈罚款〉。“交”的是钱，应说“交五百元罚款”；“处罚”是制裁本身，不能用“交……元”来表示付款。"}, {"text": "他这次考试得了好处罚。", "explanation": "这里应该用〈成绩〉。“好”用于成绩、结果，“处罚”本身是负面的，不能说“好处罚”。"}, {"text": "他的处罚唱得很好听。", "explanation": "这里应该用〈歌曲〉。“处罚”是对违规行为的制裁，不能用来指歌声；这句要说“他的歌唱得很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。"}, {"text": "触发", "is_correct": false, "explanation": "chù fā（触发）与 chǔ fá 两个音节的声调都不同，意思是引起、引发。"}, {"text": "煮法", "is_correct": false, "explanation": "zhǔ fǎ（煮法）与 chǔ fá 声母不同（zh 与 ch），第二音节声调也不同，意思是烹煮的方法。"}, {"text": "厨房", "is_correct": false, "explanation": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。"}, {"text": "处方", "is_correct": false, "explanation": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}], "explanations": {"处罚": "正确答案：处罚（chǔ fá），名词，指做错事后所受的惩罚。", "触发": "chù fā（触发）与 chǔ fá 两个音节的声调都不同，意思是引起、引发。", "煮法": "zhǔ fǎ（煮法）与 chǔ fá 声母不同（zh 与 ch），第二音节声调也不同，意思是烹煮的方法。", "厨房": "chú fáng（厨房）与 chǔ fá 第一音节声调不同，第二音节多了韵尾 ng，意思是做饭的地方。", "处方": "chǔ fāng（处方）与 chǔ fá 第二音节声调不同且多了韵尾 ng，意思是医生开的药方。"}, "sentence_index": null, "correct_answer": "处罚"}, "level_3": {"options": [{"text": "处罚", "is_correct": true, "explanation": "正确：“处罚”指做错事后受到的惩罚，与“不怕”的语境相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：没有人会“怕”蛋糕，与句意不符。"}, {"text": "食物", "is_correct": false, "explanation": "语义：县是行政区域，不是食物，句意不通。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：“早餐”不是令人害怕的事物，与“不怕”的语义不合。"}], "explanations": {"处罚": "正确：“处罚”指做错事后受到的惩罚，与“不怕”的语境相符。", "蛋糕": "语义：没有人会“怕”蛋糕，与句意不符。", "食物": "语义：县是行政区域，不是食物，句意不通。", "早餐": "语义：“早餐”不是令人害怕的事物，与“不怕”的语义不合。"}, "sentence_index": 6, "correct_answer": "处罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次学习有很大的处罚。", "explanation": "这里应该用〈收获〉。“收获”指好的成果，“处罚”是负面的制裁，不能用来描述学习的成果。"}, {"text": "他获得了很多处罚。", "explanation": "这里应该用〈奖金〉。“获得”多用于奖金、荣誉等好的结果，受罚应说“受到处罚”。"}, {"text": "老师给了他一只处罚。", "explanation": "这里应该用〈项〉（一项处罚）。“只”是动物的量词，处罚的量词应是“项”或“次”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他受到很重处罚。", "corrected_sentence": "他受到很重的处罚。", "error_description": "错误：“很重”修饰名词“处罚”时须加“的”，应说“受到很重的处罚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校给了他一头处罚。", "corrected_sentence": "学校给了他一次处罚。", "error_description": "错误：量词“头”用于大型牲畜，处罚应用“次”。正确应为“学校给了他一次处罚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
