INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26038, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个东西把另一个东西包在中间。", "primary_collocate": null, "pronunciation": "hán gài", "ipa": "xan˧˥ kai˥˩", "syllable_count": 2, "sentences": [{"text": "浓密的森林涵盖了整个山谷。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环绕村庄的山林涵盖着周围的田地。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "huán rào cūn zhuāng de shān lín hán gài zhe zhōu wéi de tián dì.", "sentence_source": "generated"}, {"text": "四周的山脉涵盖着这座湖。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "sì zhōu de shān mài hán gài zhe zhè zuò hú.", "sentence_source": "generated"}, {"text": "群山涵盖着整个盆地。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "qún shān hán gài zhe zhěng gè pén dì.", "sentence_source": "generated"}, {"text": "一圈礁石涵盖着中间的小岛。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "yì quān jiāo shí hán gài zhe zhōng jiān de xiǎo dǎo.", "sentence_source": "generated"}, {"text": "透明的薄膜涵盖着幼小的种子。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "tòu míng de báo mó hán gài zhe yòu xiǎo de zhǒng zi.", "sentence_source": "generated"}, {"text": "外面的硬壳涵盖着里面的果肉。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓣涵盖着中间的花蕊。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连绵的山峦涵盖着这座小城。", "target_word": "涵盖", "complexity_tier": "T3", "furigana": "lián mián de shān luán hán gài zhe zhè zuò xiǎo chéng.", "sentence_source": "generated"}, {"text": "一圈高墙涵盖了整座院子。", "target_word": "涵盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涵盖了", "label": "体标"}, {"form": "涵盖着", "label": "体标"}, {"form": "涵蓋", "label": "繁体"}], "register": "书面", "sense_fingerprint": "一物把另一物包围、罩在中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案，指一物把另一物包在中间。"}, {"text": "寒带", "is_correct": false, "explanation": "寒带（hán dài）与涵盖（hán gài）第二音节声母不同（d 与 g），意思是寒冷地带。"}, {"text": "汉代", "is_correct": false, "explanation": "汉代（hàn dài）与涵盖（hán gài）首音节声调不同，末音节声母不同（d 与 g），意思是汉朝。"}, {"text": "寒害", "is_correct": false, "explanation": "寒害（hán hài）与涵盖（hán gài）第二音节声母不同（h 与 g），意思是寒冷造成的灾害。"}], "explanations": {"涵盖": "正确答案，指一物把另一物包在中间。", "寒带": "寒带（hán dài）与涵盖（hán gài）第二音节声母不同（d 与 g），意思是寒冷地带。", "汉代": "汉代（hàn dài）与涵盖（hán gài）首音节声调不同，末音节声母不同（d 与 g），意思是汉朝。", "寒害": "寒害（hán hài）与涵盖（hán gài）第二音节声母不同（h 与 g），意思是寒冷造成的灾害。"}, "sentence_index": null, "correct_answer": "涵盖"}, "level_3": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案。森林覆盖整个山谷，是“包在中间”的意思。"}, {"text": "修建", "is_correct": false, "explanation": "语义：森林是自然生长的，不会“修建”山谷，句意不通。"}, {"text": "抢购", "is_correct": false, "explanation": "搭配：“抢购”的对象是商品，不能说抢购“山谷”。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能带“整个山谷”作宾语。"}], "explanations": {"涵盖": "正确答案。森林覆盖整个山谷，是“包在中间”的意思。", "修建": "语义：森林是自然生长的，不会“修建”山谷，句意不通。", "抢购": "搭配：“抢购”的对象是商品，不能说抢购“山谷”。", "散步": "配价：“散步”是不及物动词，不能带“整个山谷”作宾语。"}, "sentence_index": 0, "correct_answer": "涵盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈涵盖着熟睡的孩子。", "explanation": "这里应该用〈搂〉。涵盖指一物包在另一物外面的静态覆盖，人抱护孩子应说“搂着”。"}, {"text": "她涵盖着桌上的书。", "explanation": "这里应该用〈压〉。涵盖指一物包在另一物外面，人按住桌上的书应说“压着”。"}, {"text": "这个小孩涵盖着一块糖。", "explanation": "这里应该用〈含〉。涵盖指一物包在另一物外面，嘴里含着糖应说“含着”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涵盖", "is_correct": true, "explanation": "正确答案。外面的硬壳包在里面的果肉外，是“包在中间”的意思。"}, {"text": "切碎", "is_correct": false, "explanation": "语义：硬壳是外层的壳，不能把里面的果肉“切碎”，句意与“外面的”不合。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”多搭配气味、光等，不能说散发“果肉”。"}, {"text": "熬", "is_correct": false, "explanation": "语义：硬壳不能“熬”果肉，“熬”多指久煮或忍耐，与句意不合。"}], "explanations": {"涵盖": "正确答案。外面的硬壳包在里面的果肉外，是“包在中间”的意思。", "切碎": "语义：硬壳是外层的壳，不能把里面的果肉“切碎”，句意与“外面的”不合。", "散发": "搭配：“散发”多搭配气味、光等，不能说散发“果肉”。", "熬": "语义：硬壳不能“熬”果肉，“熬”多指久煮或忍耐，与句意不合。"}, "sentence_index": 6, "correct_answer": "涵盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鸟涵盖着一根树枝。", "explanation": "这里应该用〈停在〉。涵盖指一物包在另一物外面，小鸟站在树枝上应说“停在”。"}, {"text": "他涵盖着那封信。", "explanation": "这里应该用〈压〉。涵盖表示一物包在另一物外面，按住信纸应说“压着”。"}, {"text": "这瓶饮料涵盖大量糖。", "explanation": "这里应该用〈含有〉。涵盖表示“盖在外面”，不用于说饮料中所含的成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一层薄雾涵盖了着整片湖面。", "corrected_sentence": "一层薄雾涵盖着整片湖面。", "error_description": "错误：“了”与“着”不能同时用在同一个动词后。表示覆盖的持续状态应说“涵盖着”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一层薄雾被涵盖着整片湖面。", "corrected_sentence": "一层薄雾涵盖着整片湖面。", "error_description": "错误：多加了“被”，且“涵盖”后已带宾语，构成“被+动词+宾语”的错误结构。盖住湖面的是“一层薄雾”，应说“一层薄雾涵盖着整片湖面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
