INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方，比如省、市。", "primary_collocate": null, "pronunciation": "xíng zhèng qū", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "省和市都是行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政区的天气很好。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想搬到另一个行政区住。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的行政区在河的东边。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政区的路修得很宽。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上用不同的颜色表示行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县也是一种行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市分成了八个行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说出自己所在的行政区。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行政区的小学很多。", "target_word": "行政区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "行政區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "省、市这类有管理范围的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b120eee5-96a8-434e-8d00-ab99f4fe0b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政区", "is_correct": true, "explanation": "行政区指按行政划分的地方，省和市都属于这一类，与句意相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：省和市是行政管理范围，不是河流，句意不通。"}, {"text": "政府", "is_correct": false, "explanation": "语义：省和市是行政区域，本身不是政府机构，句意不通。"}, {"text": "首都", "is_correct": false, "explanation": "搭配：“首都”只指国家的首府，不能用来指省和市。"}], "explanations": {"行政区": "行政区指按行政划分的地方，省和市都属于这一类，与句意相符。", "河流": "语义：省和市是行政管理范围，不是河流，句意不通。", "政府": "语义：省和市是行政区域，本身不是政府机构，句意不通。", "首都": "搭配：“首都”只指国家的首府，不能用来指省和市。"}, "sentence_index": 0, "correct_answer": "行政区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用行政区写作业。", "explanation": "这里应该用〈铅笔〉。行政区是管理范围，不是文具，不能用来写字。"}, {"text": "他看到了一把行政区。", "explanation": "量词用错：“把”多用于有柄的器具，不能用来计量“行政区”，应用“个”。"}, {"text": "他的行政区很高，比我还高。", "explanation": "这里应该用〈树〉。行政区是区域，没有高矮，不能说“很高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政区", "is_correct": true, "explanation": "行政区指按行政划分的地方，县属于这一类，“县也是一种行政区”符合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：县是行政区域，不是乐器，句意不通。"}, {"text": "食物", "is_correct": false, "explanation": "语义：县是行政区域，不是食物，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：县不是颜色，放入句中句意不通。"}], "explanations": {"行政区": "行政区指按行政划分的地方，县属于这一类，“县也是一种行政区”符合语境。", "乐器": "语义：县是行政区域，不是乐器，句意不通。", "食物": "语义：县是行政区域，不是食物，句意不通。", "颜色": "语义：县不是颜色，放入句中句意不通。"}, "sentence_index": 6, "correct_answer": "行政区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "行政区今年要去上小学了。", "explanation": "这里应该用〈孩子〉。行政区是地方范围，不是人，不会上学。"}, {"text": "这个行政区很爱吃辣，每天都要吃两碗。", "explanation": "这里应该用〈我〉。行政区是地方范围，不是人，不会吃饭。"}, {"text": "行政区每天早上六点去上班。", "explanation": "这里应该用〈爸爸〉。行政区是地方范围，不是人，不会上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家这个行政区里。", "corrected_sentence": "他家在这个行政区里。", "error_description": "缺少介词：处所“这个行政区里”要用“在”引出，应说“他家在这个行政区里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市分成了六条行政区。", "corrected_sentence": "这座城市分成了六个行政区。", "error_description": "量词错误：“行政区”前应用“个”，“条”不能用于行政区。正确说法是“这座城市分成了六个行政区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b43f5e5f-f30e-4a50-aa33-8e6e8160a3a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
