INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26042, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情接下来发生的情况。", "primary_collocate": null, "pronunciation": "hòu xù", "ipa": "xoʊ̯˥˩ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这件事的后续怎么样了？", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有交代后续，我们只好自己猜。", "target_word": "后续", "complexity_tier": "T3", "furigana": "hòu xù", "sentence_source": "generated"}, {"text": "电影的后续部分讲了他们的新生活。", "target_word": "后续", "complexity_tier": "T3", "furigana": "hòu xù", "sentence_source": "generated"}, {"text": "你知道这个故事的后续吗？", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻只写了事故，没有写后续。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后续发生的事，谁也没想到。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很想知道后续，请你告诉我吧。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书看到一半，我还不知道后续。", "target_word": "后续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友问我这件事后续如何，我说还不错。", "target_word": "后续", "complexity_tier": "T3", "furigana": "hòu xù", "sentence_source": "generated"}, {"text": "这起事故的后续，大家都不太清楚。", "target_word": "后续", "complexity_tier": "T3", "furigana": "hòu xù", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事情接下来发生的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后续", "is_correct": true, "explanation": "正确：后续指事情接下来发生的情况，符合句中问“事情之后怎么样了”的语境。"}, {"text": "前因", "is_correct": false, "explanation": "语义：前因指事情发生之前的原因，句中问的是之后的发展，与其不符。"}, {"text": "来历", "is_correct": false, "explanation": "语义：来历指事物从哪里来，句中问的是事情接下来的状况，不是它的起源。"}, {"text": "结构", "is_correct": false, "explanation": "搭配：结构指组成方式，不能说事情的结构怎么样了，搭配不当。"}], "explanations": {"后续": "正确：后续指事情接下来发生的情况，符合句中问“事情之后怎么样了”的语境。", "前因": "语义：前因指事情发生之前的原因，句中问的是之后的发展，与其不符。", "来历": "语义：来历指事物从哪里来，句中问的是事情接下来的状况，不是它的起源。", "结构": "搭配：结构指组成方式，不能说事情的结构怎么样了，搭配不当。"}, "sentence_index": 0, "correct_answer": "后续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要后续这个计划，每周开会一次。", "explanation": "这里应该用〈跟进〉。后续是名词，指事情之后的情况，不能当动词用；对计划采取行动要说跟进。"}, {"text": "我把后续放进了冰箱。", "explanation": "语义误用：后续指事情之后的情况，不是能放进冰箱的东西；这里应该用〈食物〉。"}, {"text": "我的后续很高，比你还高。", "explanation": "语义误用：后续指事情之后的情况，不能用来形容人的身高；这里应该用〈身材〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后续", "is_correct": true, "explanation": "正确：后续指事情之后的情况，符合“很想知道”的内容。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以“知道”的内容，句意不通。"}, {"text": "体貌", "is_correct": false, "explanation": "体貌：体貌指人的外貌形体，不能用来指事情的情况，搭配不当。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指人的体形，不能用于事情，搭配不当。"}], "explanations": {"后续": "正确：后续指事情之后的情况，符合“很想知道”的内容。", "冰箱": "语义：冰箱是家电，不是可以“知道”的内容，句意不通。", "体貌": "体貌：体貌指人的外貌形体，不能用来指事情的情况，搭配不当。", "身材": "体貌：身材只指人的体形，不能用于事情，搭配不当。"}, "sentence_index": 6, "correct_answer": "后续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为迟到，受到了很重的后续。", "explanation": "这里应该用〈处分〉。后续指事情之后的情况，不指因违纪受到的惩罚，那要说处分。"}, {"text": "这件衣服的后续是一百块。", "explanation": "这里应该用〈售价〉。后续指事情之后的情况，不指商品的价钱，要说售价。"}, {"text": "他是我父亲的后续，长得一模一样。", "explanation": "这里应该用〈后代〉。后续指事情之后的情况，不指人，表示子孙要说后代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经知道这件事后续了。", "corrected_sentence": "我们已经知道这件事的后续了。", "error_description": "“后续”修饰名词“事”时中间要加“的”。误去掉“的”，“后续”就成了谓语，句子不通。应为“这件事的后续”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还在等这件事的后续了消息。", "corrected_sentence": "我还在等这件事的后续消息。", "error_description": "“后续”作定语修饰“消息”时，中间不能插“了”。误加“了”，应为“这件事的后续消息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
