INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西变得适合一个地方或一个国家。", "primary_collocate": null, "pronunciation": "shǔ dì huà", "ipa": "ʂu˨˩ ti˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这个游戏要属地化，才能在日本卖得好。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想把这款手机属地化，让本地人更方便使用。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单做了属地化，加入了当地人爱吃的菜。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "属地化就是让产品适合当地人。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套教材的属地化，要把例子换成本地的。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家连锁店在中国属地化得很好。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机应用属地化后，用户一下子多了。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，我们必须尽快属地化，不然没人买。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把广告属地化，用了当地的语言和明星。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "属地化做得好的品牌，更容易得到本地人喜欢。", "target_word": "属地化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "属地化了", "label": "体标"}, {"form": "属地化过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "让东西适合某个地方或国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73af155f-4a0d-432b-a365-77d4bc223b26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷却", "is_correct": false, "explanation": "语义：句中要表达的是让游戏适应日本市场，“冷却”与此无关。"}, {"text": "属地化", "is_correct": true, "explanation": "正确。“这个游戏要属地化，才能在日本卖得好”说的是按当地情况调整，符合句意。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做食品的工艺，与游戏适应市场无关。"}, {"text": "口语化", "is_correct": false, "explanation": "语域：“口语化”指语言风格，不能用于游戏的市场调整。"}], "explanations": {"冷却": "语义：句中要表达的是让游戏适应日本市场，“冷却”与此无关。", "属地化": "正确。“这个游戏要属地化，才能在日本卖得好”说的是按当地情况调整，符合句意。", "烘焙": "语义：烘焙是做食品的工艺，与游戏适应市场无关。", "口语化": "语域：“口语化”指语言风格，不能用于游戏的市场调整。"}, "sentence_index": 0, "correct_answer": "属地化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把碗属地化干净了。", "explanation": "这里应该用〈洗〉。属地化是按当地情况调整产品或服务，不指洗涤餐具，应说洗。"}, {"text": "工人把坏掉的椅子属地化好了。", "explanation": "这里应该用〈修理〉。属地化是按当地情况调整，不指修复坏掉的物品。"}, {"text": "孩子已经把作业属地化完了。", "explanation": "这里应该用〈做〉。属地化用于调整产品或服务，不能用于完成作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "戒烟", "is_correct": false, "explanation": "搭配：“戒烟”的对象是人，不能用于描述手机应用。"}, {"text": "翻唱", "is_correct": false, "explanation": "语义：翻唱指重新演唱歌曲，与手机应用的使用情况无关。"}, {"text": "属地化", "is_correct": true, "explanation": "正确。“手机应用属地化后，用户一下子多了”说明应用经过本地化调整，符合句意。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：熬夜是人晚睡的行为，不能用来描述手机应用。"}], "explanations": {"戒烟": "搭配：“戒烟”的对象是人，不能用于描述手机应用。", "翻唱": "语义：翻唱指重新演唱歌曲，与手机应用的使用情况无关。", "属地化": "正确。“手机应用属地化后，用户一下子多了”说明应用经过本地化调整，符合句意。", "熬夜": "语义：熬夜是人晚睡的行为，不能用来描述手机应用。"}, "sentence_index": 6, "correct_answer": "属地化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师属地化了学生的作业。", "explanation": "这里应该用〈检查〉。属地化只用于产品和服务，不能用于批改学生的作业。"}, {"text": "这家店要属地化营业面积。", "explanation": "这里应该用〈扩大〉。属地化是调整产品以适应当地，不能用于营业面积的增减。"}, {"text": "我们热烈属地化新朋友。", "explanation": "这里应该用〈欢迎〉。属地化的对象是产品或服务，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏已经属地化了过。", "corrected_sentence": "这个游戏已经属地化过了。", "error_description": "体标错误：「了」与「过」同现时，「过」须在前，应说「属地化过了」，不能说「属地化了过」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件属地化的很快。", "corrected_sentence": "这个软件属地化得很快。", "error_description": "错误：补语标记用错了。「的」不能用在补语位置，应说「属地化得很快」，「得」接在动词后、补语前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f69e7c2f-17b1-4f84-8722-27e2c385f8ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
