INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西破裂或打碎后留下的小块。", "primary_collocate": null, "pronunciation": "suì piàn", "ipa": "sweɪ̯˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "地上有很多玻璃碎片，你小心点。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子掉在地上，变成了很多碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手捡起一块碎片，不小心划破了手。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把墙上的碎片清扫干净了。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把碎片放进了垃圾桶。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机坠毁以后，山上到处都是飞机碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块瓷器的碎片很锋利，别用手摸。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古学家在土里找到了一些陶器碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓶摔碎以后，我把碎片一块一块捡起来。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太空里有很多卫星留下的碎片。", "target_word": "碎片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "玻璃碎片", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西打碎后留下的很小的片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "正确。「玻璃碎片」指破碎后的小块玻璃，是需要小心的东西。"}, {"text": "手指", "is_correct": false, "explanation": "语义：「玻璃手指」指不存在的东西，句子读不通。"}, {"text": "丝绸", "is_correct": false, "explanation": "搭配：「玻璃」不能修饰「丝绸」，二者不搭配。"}, {"text": "水果", "is_correct": false, "explanation": "语义：「玻璃水果」读不通，玻璃与水果不能构成需要小心的东西。"}], "explanations": {"碎片": "正确。「玻璃碎片」指破碎后的小块玻璃，是需要小心的东西。", "手指": "语义：「玻璃手指」指不存在的东西，句子读不通。", "丝绸": "搭配：「玻璃」不能修饰「丝绸」，二者不搭配。", "水果": "语义：「玻璃水果」读不通，玻璃与水果不能构成需要小心的东西。"}, "sentence_index": 0, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "杯子摔碎以后，地上留下了一只碎片。", "explanation": "量词误用：「只」多用于动物、成对的物件或器皿，碎片一般用〈块〉或〈片〉计量，这里应该用〈块〉。"}, {"text": "这包茶叶已经磨成了细细的碎片，泡水很方便。", "explanation": "近义词误用：这里应该用〈粉末〉。碎片指破裂后的小块，磨成细末的东西要说「粉末」。"}, {"text": "雨停后，树叶上挂着许多碎片，一滴滴往下落。", "explanation": "近义词误用：这里应该用〈水滴〉。碎片是固体破裂后的小块，不会一滴滴往下落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "碎片", "is_correct": true, "explanation": "正确。「碎片」是瓷器破裂后的小块，边缘锋利，所以别用手摸。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会锋利，「颜色很锋利」读不通。"}, {"text": "花纹", "is_correct": false, "explanation": "语义：花纹没有锋利的属性，句子读不通。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：「锋利」形容刀刃或尖端，不能用来形容重量。"}], "explanations": {"碎片": "正确。「碎片」是瓷器破裂后的小块，边缘锋利，所以别用手摸。", "颜色": "语义：颜色不会锋利，「颜色很锋利」读不通。", "花纹": "语义：花纹没有锋利的属性，句子读不通。", "重量": "搭配：「锋利」形容刀刃或尖端，不能用来形容重量。"}, "sentence_index": 6, "correct_answer": "碎片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片农场被切成了许多碎片，没法统一管理。", "explanation": "用错了词义：这里是「碎片」的抽象义，指完整区域被分割后的状态，不是破裂的小块。"}, {"text": "电脑变慢了，我们要先清理磁盘碎片。", "explanation": "用错了词义：这里是「碎片」的计算机义，指磁盘上零散存放的文件片段，与物体破裂无关。"}, {"text": "他每天利用碎片时间看书。", "explanation": "用错了词义：这里是「碎片」的时间义，指零散、断续的时间，与破碎的小块无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他手上扎进了一只碎片，流了不少血。", "corrected_sentence": "他手上扎进了一块碎片，流了不少血。", "error_description": "量词误用：「碎片」一般用「块」或「片」计量，「只」多用于动物、成对的物件或器皿，不能用来计量碎片。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "花瓶摔碎片了，满地都是。", "corrected_sentence": "花瓶摔成碎片了，满地都是。", "error_description": "补语缺失：「摔」表示结果时要加补语「成」，应说「摔成碎片」，不能说「摔碎片」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自上而下", "is_correct": true, "explanation": "自上而下：从上面往下面，与“自下而上”的空间方向相反，是本义的反义词。"}, {"text": "偶尔", "is_correct": false, "explanation": "与“自下而上”无反义关系，“偶尔”指不常发生。"}, {"text": "一起", "is_correct": false, "explanation": "与“自下而上”无反义关系，“一起”指共同。"}, {"text": "忽然", "is_correct": false, "explanation": "与“自下而上”无反义关系，“忽然”指出乎意料地发生。"}], "correct_answer": "自上而下", "explanations": {"自上而下": "自上而下：从上面往下面，与“自下而上”的空间方向相反，是本义的反义词。", "偶尔": "与“自下而上”无反义关系，“偶尔”指不常发生。", "一起": "与“自下而上”无反义关系，“一起”指共同。", "忽然": "与“自下而上”无反义关系，“忽然”指出乎意料地发生。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自上而下", "is_correct": true, "explanation": "自上而下：从上面往下面，与“自下而上”的空间方向相反，是本义的反义词。"}, {"text": "已经", "is_correct": false, "explanation": "与“自下而上”无反义关系，“已经”指动作或状态已完成。"}, {"text": "渐渐", "is_correct": false, "explanation": "与“自下而上”无反义关系，“渐渐”指逐步变化。"}, {"text": "竟然", "is_correct": false, "explanation": "与“自下而上”无反义关系，“竟然”表示出乎意料。"}], "correct_answer": "自上而下", "explanations": {"自上而下": "自上而下：从上面往下面，与“自下而上”的空间方向相反，是本义的反义词。", "已经": "与“自下而上”无反义关系，“已经”指动作或状态已完成。", "渐渐": "与“自下而上”无反义关系，“渐渐”指逐步变化。", "竟然": "与“自下而上”无反义关系，“竟然”表示出乎意料。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "从下面往上面。", "primary_collocate": null, "pronunciation": "zì xià ér shàng", "ipa": "tsɹ̩˥˩ ɕia˥˩ ɚ˧˥ ʂɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "他自下而上地看了看整栋楼。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们自下而上检查每一层楼。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她自下而上地擦着窗户。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画这棵树时，要自下而上地画。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油漆工自下而上刷墙。", "target_word": "自下而上", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电梯自下而上地运送货物。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯光自下而上照亮了整座塔。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他抬头自下而上地看着高楼。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你自下而上数一数这里有几层。", "target_word": "自下而上", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山的时候，我们自下而上走了三个小时。", "target_word": "自下而上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "空间上从下面往上面的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自下而上", "is_correct": true, "explanation": "自下而上：从下面往上面，修饰“看”，表示视线的方向，句意通顺。"}, {"text": "香甜", "is_correct": false, "explanation": "语义：“香甜”形容气味或味道，不能修饰“看”。"}, {"text": "沙哑", "is_correct": false, "explanation": "搭配：“沙哑”形容嗓音，与“看”搭配不当。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体的状态，不能修饰“看”。"}], "explanations": {"自下而上": "自下而上：从下面往上面，修饰“看”，表示视线的方向，句意通顺。", "香甜": "语义：“香甜”形容气味或味道，不能修饰“看”。", "沙哑": "搭配：“沙哑”形容嗓音，与“看”搭配不当。", "潮湿": "语义：“潮湿”形容空气或物体的状态，不能修饰“看”。"}, "sentence_index": 0, "correct_answer": "自下而上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自下而上地走下楼梯，回家了。", "explanation": "这里应该用〈自上而下〉。走下楼梯是从上往下，与“自下而上”的方向相反。"}, {"text": "他自下而上地跳进了湖里。", "explanation": "这里应该用〈自上而下〉。“跳进湖里”是从上往下，与“自下而上”的方向相反。"}, {"text": "他站在楼顶，自下而上地看着街道。", "explanation": "这里应该用〈自上而下〉。站在楼顶看街道是由上往下看，与“自下而上”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自下而上", "is_correct": true, "explanation": "自下而上：从下往上，修饰“照亮”，表示光的方向，句意通顺。"}, {"text": "悲伤", "is_correct": false, "explanation": "语义：“悲伤”形容情绪，灯光不能悲伤，不能修饰“照亮”。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”指不说话，不能修饰“照亮”。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，与“灯光”“照亮”搭配不当。"}], "explanations": {"自下而上": "自下而上：从下往上，修饰“照亮”，表示光的方向，句意通顺。", "悲伤": "语义：“悲伤”形容情绪，灯光不能悲伤，不能修饰“照亮”。", "沉默": "语义：“沉默”指不说话，不能修饰“照亮”。", "嘹亮": "搭配：“嘹亮”形容声音，与“灯光”“照亮”搭配不当。"}, "sentence_index": 6, "correct_answer": "自下而上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这架飞机自下而上地降落在跑道上。", "explanation": "这里应该用〈自上而下〉。降落是从上往下，与“自下而上”的方向相反。"}, {"text": "电梯自下而上地从一楼下到了地下室。", "explanation": "这里应该用〈自上而下〉。“从一楼下到地下室”是从上往下，与“自下而上”的方向相反。"}, {"text": "这块石头自下而上地滚到了山脚下。", "explanation": "这里应该用〈自上而下〉。滚到山脚下是从上往下，与“自下而上”的方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员自下而上的搜查了每一层。", "corrected_sentence": "消防员自下而上地搜查了每一层。", "error_description": "助词错误：“自下而上”修饰动词“搜查”作状语，应用“地”，不能用“的”。用“的”则成了定语，应说“自下而上地搜查了每一层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客自下而上得仰望着这座雕像。", "corrected_sentence": "游客自下而上地仰望着这座雕像。", "error_description": "助词错误：“自下而上”修饰动词“仰望”作状语，应用“地”，不能用“得”（“得”用于引出补语）。应说“自下而上地仰望着这座雕像”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
