INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26056, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一点一点地变化或前进。", "primary_collocate": null, "pronunciation": "jiàn jìn", "ipa": "tɕjɛn˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "孩子长大是渐进的，每天都变一点点。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮是渐进的，天空慢慢变白了。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的变化是渐进的，朋友们一开始并没有察觉。", "target_word": "渐进", "complexity_tier": "T3", "furigana": "tā de biànhuà shì jiàn jìn de, péng you men yì kāishǐ bìng méiyǒu chájué.", "sentence_source": "generated"}, {"text": "这个游戏的难度是渐进的，越玩越难。", "target_word": "渐进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "减肥最好是渐进的，一下子瘦太多对身体不好。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天的变暖是渐进的，今天比昨天只暖一点。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的恢复是渐进的，先能坐，再能站，后来能走。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水上涨是渐进的，不是一夜之间发生的。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的友谊是渐进的，不是一见面就很好。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学跑步的方法最好是渐进的，先走十分钟，再慢慢加长。", "target_word": "渐进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渐进式", "label": "复合"}, {"form": "渐进性", "label": "复合"}, {"form": "漸進", "label": "繁体"}], "register": "书面", "sense_fingerprint": "变化只是一点一点地发生，不是突然的（变化是渐进的）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01edaae3-9fb1-4797-a818-53b09db41e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进（jiàn jìn）：一点一点地变化，是正确答案。"}, {"text": "监禁", "is_correct": false, "explanation": "监禁（jiān jìn）第一个音节为第一声，与渐进的 jiàn（第四声）声调不同，意思是关押。"}, {"text": "先进", "is_correct": false, "explanation": "先进（xiān jìn）第一个音节声母由 j 变为 x，声调也不同，意思是走在前面、水平高。"}, {"text": "前进", "is_correct": false, "explanation": "前进（qián jìn）第一个音节声母由 j 变为 q，声调也不同，意思是向前走。"}], "explanations": {"渐进": "渐进（jiàn jìn）：一点一点地变化，是正确答案。", "监禁": "监禁（jiān jìn）第一个音节为第一声，与渐进的 jiàn（第四声）声调不同，意思是关押。", "先进": "先进（xiān jìn）第一个音节声母由 j 变为 x，声调也不同，意思是走在前面、水平高。", "前进": "前进（qián jìn）第一个音节声母由 j 变为 q，声调也不同，意思是向前走。"}, "sentence_index": null, "correct_answer": "渐进"}, "level_3": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进：作谓语，说明“长大”是一点一点进行的，与“每天都变一点点”相合，句意正确。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”与“每天都变一点点”矛盾，句意不通。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：“迅速”说变化很快，与“每天都变一点点”的缓慢相矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说排列或外形，不能用来说明“长大”。"}], "explanations": {"渐进": "渐进：作谓语，说明“长大”是一点一点进行的，与“每天都变一点点”相合，句意正确。", "突然": "语义：“突然”与“每天都变一点点”矛盾，句意不通。", "迅速": "语义：“迅速”说变化很快，与“每天都变一点点”的缓慢相矛盾。", "整齐": "搭配：“整齐”说排列或外形，不能用来说明“长大”。"}, "sentence_index": 0, "correct_answer": "渐进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "雷声是渐进的，一响就震动了整个山谷。", "explanation": "这里应该用〈猛然〉。渐进表示一点一点地变化，雷声一下子震动山谷是瞬间的，不能说“渐进的雷声”。"}, {"text": "一场渐进的暴雨把城市淹没了。", "explanation": "这里应该用〈突然〉。暴雨是一下子降临的，不能用“渐进的”来描述它。"}, {"text": "这道题的解法是渐进的，他想都没想就做出来了。", "explanation": "这里应该用〈一下子〉。渐进指一步步的过程，不加思索地马上做出来要说“一下子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "渐进", "is_correct": true, "explanation": "渐进：作谓语，说明恢复是一步步进行的，与“先能坐，再能站，后来能走”的顺序相合，句意正确。"}, {"text": "突兀", "is_correct": false, "explanation": "语义：“突兀”指突然出现，与“先能坐，再能站，后来能走”的逐步过程矛盾。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”指不再前进，与“先能坐，再能站”的前进过程矛盾。"}, {"text": "凌乱", "is_correct": false, "explanation": "搭配：“凌乱”说状态或样子，不能用来修饰“恢复”。"}], "explanations": {"渐进": "渐进：作谓语，说明恢复是一步步进行的，与“先能坐，再能站，后来能走”的顺序相合，句意正确。", "突兀": "语义：“突兀”指突然出现，与“先能坐，再能站，后来能走”的逐步过程矛盾。", "停滞": "语义：“停滞”指不再前进，与“先能坐，再能站”的前进过程矛盾。", "凌乱": "搭配：“凌乱”说状态或样子，不能用来修饰“恢复”。"}, "sentence_index": 6, "correct_answer": "渐进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的一拳是渐进的，把对手打倒了。", "explanation": "这里应该用〈瞬间〉。渐进指一步步地变化，一拳把人打倒是瞬间完成的，不能说“渐进的一拳”。"}, {"text": "一声渐进的枪响，把大家都吓坏了。", "explanation": "这里应该用〈骤然〉。枪响是瞬间发生的，不能用“渐进的”描述。"}, {"text": "这场演讲是渐进的，他只用了一秒钟就讲完了。", "explanation": "这里应该用〈顷刻〉。渐进指一步步的过程，一秒钟完成不能说“渐进的演讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她渐进的长高了不少。", "corrected_sentence": "她渐进地长高了不少。", "error_description": "的地用错：“渐进”修饰动词“长高”，作状语要用“地”，应说“渐进地长高”，用“的”句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的恢复过程是渐进地，每天都有一点进步。", "corrected_sentence": "他的恢复过程是渐进的，每天都有一点进步。", "error_description": "的地用错：作谓语时要用“的”，“是渐进地”不通，应说“是渐进的”，表示一点点地进步。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
