INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以照着画的样子。", "primary_collocate": null, "pronunciation": "mú bǎn", "ipa": "mu˧˥ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子照着模板画了一只小鸟。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸上有一个房子的模板。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把模板放在纸上，再用笔描出来。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术课上，老师发了动物模板。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有模板，我画不好这朵花。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个圆形模板可以画出很多小圆。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用星星模板在墙上画了一圈。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把模板剪下来，放在布上。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套模板有猫，也有狗。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友喜欢用模板画画。", "target_word": "模板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "星星模板", "label": "复合"}], "register": "中性", "sense_fingerprint": "可照着描画的图样板", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模板", "is_correct": true, "explanation": "正确答案。“照着”描画的对象是可供描摹的样子。"}, {"text": "白菜", "is_correct": false, "explanation": "语义：白菜不是可供描画的样子，无法照着它画鸟。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“照着”搭配“画”时，宾语应是可以描摹的图样，不说照着歌词画画。"}, {"text": "家伙", "is_correct": false, "explanation": "语域：“家伙”是口语，且指代含糊，不能作为描画的样子。"}], "explanations": {"模板": "正确答案。“照着”描画的对象是可供描摹的样子。", "白菜": "语义：白菜不是可供描画的样子，无法照着它画鸟。", "歌词": "搭配：“照着”搭配“画”时，宾语应是可以描摹的图样，不说照着歌词画画。", "家伙": "语域：“家伙”是口语，且指代含糊，不能作为描画的样子。"}, "sentence_index": 0, "correct_answer": "模板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "化验员取了一份尿液模板。", "explanation": "这里应该用〈样本〉。模板是可照着描画的样子，不能用来指检验用的尿液材料。"}, {"text": "他用模板煮了一锅汤。", "explanation": "这里应该用〈锅〉。模板指可照着画的样子，不是烹饪用具。"}, {"text": "她拿起模板，给花浇了水。", "explanation": "这里应该用〈水壶〉。模板指可照着画的样子，不是浇水的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模板", "is_correct": true, "explanation": "正确答案。“星星模板”是可以照着在墙上描画的图样。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子不能用来在墙上画圈，句中“星星”指的是可描画的图样。"}, {"text": "围裙", "is_correct": false, "explanation": "语义：围裙是衣物，无法作为在墙上画圈的工具或样式。"}, {"text": "脚丫", "is_correct": false, "explanation": "语域：“脚丫”是口语，且用脚画圈的说法与句意不符。"}], "explanations": {"模板": "正确答案。“星星模板”是可以照着在墙上描画的图样。", "饺子": "语义：饺子不能用来在墙上画圈，句中“星星”指的是可描画的图样。", "围裙": "语义：围裙是衣物，无法作为在墙上画圈的工具或样式。", "脚丫": "语域：“脚丫”是口语，且用脚画圈的说法与句意不符。"}, "sentence_index": 6, "correct_answer": "模板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小朋友喜欢拍模板。", "explanation": "这里应该用〈照片〉。模板指可照着画的样子，不是拍摄的对象。"}, {"text": "小朋友喜欢照着模板唱歌。", "explanation": "这里应该用〈曲谱〉。模板指可照着画的样子，不指乐谱。"}, {"text": "小朋友喜欢用模板吃饭。", "explanation": "这里应该用〈碗〉。模板指可照着画的样子，不是吃饭的器具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她用这条模板画了一朵花。", "corrected_sentence": "她用这个模板画了一朵花。", "error_description": "错误：量词用错。模板是片状的图样，不用“条”（“条”多用于细长之物），应说“这个模板”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一条圆形模板。", "corrected_sentence": "这是一个圆形模板。", "error_description": "错误：量词用错。模板是片状的图样，不用“条”（“条”多用于细长之物），应说“一个圆形模板”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
