INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26060, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示用一件小事来代表一个大的意思。", "primary_collocate": null, "pronunciation": "xiàng zhēng xìng", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "老板只收了他象征性的一块钱。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她象征性地吃了几口饭。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，大家象征性地握了握手。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是象征性的奖励，不是很多钱。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他象征性地付了一元房租。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子象征性地帮妈妈拿了一个杯子。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司象征性地送了每人一朵花。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱是象征性的，主要是表示心意。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长象征性地剪了一下彩带。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校只象征性地收了一点费用。", "target_word": "象征性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "象征性地", "label": "复合"}, {"form": "象征性的", "label": "复合"}, {"form": "象徵性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只做小事表示心意、并非实质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ab76373-a806-4838-933e-5ef3747780ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性”指只做小事表示心意，句中“只收一块钱”正是这个意思。"}, {"text": "完整性", "is_correct": false, "explanation": "语义：“完整性”指齐全无缺，与“只收一块钱”的小额含义不符。"}, {"text": "准确性", "is_correct": false, "explanation": "语义：“准确性”指符合实际的程度，不能说明金额的小与少。"}, {"text": "公开性", "is_correct": false, "explanation": "搭配：“公开性”说事情是否公开，不修饰金额。"}], "explanations": {"象征性": "“象征性”指只做小事表示心意，句中“只收一块钱”正是这个意思。", "完整性": "语义：“完整性”指齐全无缺，与“只收一块钱”的小额含义不符。", "准确性": "语义：“准确性”指符合实际的程度，不能说明金额的小与少。", "公开性": "搭配：“公开性”说事情是否公开，不修饰金额。"}, "sentence_index": 0, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支笔的象征性很好，写字很流畅。", "explanation": "这里应该用〈流畅性〉。“象征性”指用小事代表大意思，笔写得顺不顺要看流畅性，不能这样用。"}, {"text": "这台机器的象征性很好，连续工作一整天都没问题。", "explanation": "这里应该用〈稳定性〉。“象征性”指用小事代表大意思，机器能否连续工作要看稳定性，不能这样用。"}, {"text": "这辆车的象征性很好，油耗很低。", "explanation": "这里应该用〈经济性〉。“象征性”指用小事代表大意思，油耗低说的是经济性，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征性", "is_correct": true, "explanation": "“象征性地”修饰“送”，表示只做形式、表达心意，与句意相符。"}, {"text": "粗暴", "is_correct": false, "explanation": "语义：“粗暴”指态度或行为强硬，与送花这种温和的赠予行为不符。"}, {"text": "恶毒", "is_correct": false, "explanation": "语义：“恶毒”指心肠狠毒，与送花这一行为不相容。"}, {"text": "凶狠", "is_correct": false, "explanation": "搭配：“凶狠”多修饰打斗、目光，不修饰“送”这类赠予动作。"}], "explanations": {"象征性": "“象征性地”修饰“送”，表示只做形式、表达心意，与句意相符。", "粗暴": "语义：“粗暴”指态度或行为强硬，与送花这种温和的赠予行为不符。", "恶毒": "语义：“恶毒”指心肠狠毒，与送花这一行为不相容。", "凶狠": "搭配：“凶狠”多修饰打斗、目光，不修饰“送”这类赠予动作。"}, "sentence_index": 6, "correct_answer": "象征性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种工具的象征性很强，人人都会用。", "explanation": "这里应该用〈实用性〉。“象征性”说事物代表抽象意义，工具的好坏看实用性，不能这样用。"}, {"text": "这把椅子的象征性很好，用很多年都不坏。", "explanation": "这里应该用〈耐用性〉。“象征性”指用小事代表大意思，椅子能用多久要看耐用性，不能这样用。"}, {"text": "这台秤的象征性很高，称出来的重量很准。", "explanation": "这里应该用〈精确性〉。“象征性”指用小事代表大意思，秤称得准不准要看精确性，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他象征性的给了朋友一点钱，表示感谢。", "corrected_sentence": "他象征性地给了朋友一点钱，表示感谢。", "error_description": "错误：“象征性”作状语修饰动词“给”时应用“地”，不能用“的”，应说“象征性地给了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次收费是象征性地，主要为了表示态度。", "corrected_sentence": "这次收费是象征性的，主要为了表示态度。", "error_description": "用法错误：作谓语时应用“象征性的”，“象征性地”是副词，不能直接作谓语。应为“这次收费是象征性的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a0fd508-6058-4e43-8143-35abed154cc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
