INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家在别的国家的人心中的样子。", "primary_collocate": null, "pronunciation": "guó jì xíng xiàng", "ipa": "kuo˧˥ tɕi˥˩ ɕiŋ˧˥ ɕiɑŋ˥˩", "syllable_count": 4, "sentences": [{"text": "很多人觉得这个国家的国际形象很好。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的国际形象越来越好了。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道别国人怎么看我们的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家的国际形象会影响游客的选择。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影改变了外国人心中的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的表现也会影响国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，国际形象是别国人对我们的印象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛让这个小国有了新的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的国际形象需要大家一起努力。", "target_word": "国际形象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要维护自己国家的国际形象。", "target_word": "国际形象", "complexity_tier": "T3", "furigana": "wǒ men yào wéi hù zì jǐ guó jiā de guó jì xíng xiàng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "國際形象", "label": "繁体"}], "register": "中性", "sense_fingerprint": "别国人心中对一个国家的印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指别国人心中对一个国家的印象，“这个国家的国际形象很好”符合句意。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人或动物的体型，不用于说一个国家的样子。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是人的感受，国家没有心情，句意不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”一般说人的性情，“这个国家的脾气”搭配不当。"}], "explanations": {"国际形象": "“国际形象”指别国人心中对一个国家的印象，“这个国家的国际形象很好”符合句意。", "身材": "体貌：“身材”指人或动物的体型，不用于说一个国家的样子。", "心情": "语义：“心情”是人的感受，国家没有心情，句意不通。", "脾气": "搭配：“脾气”一般说人的性情，“这个国家的脾气”搭配不当。"}, "sentence_index": 0, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "国际形象是本国人对自己国家的看法。", "explanation": "这里应该用〈国家形象〉。“国际形象”指别国人心中的印象，不是本国人对自己国家的看法。"}, {"text": "国际形象是各国都要遵守的准则。", "explanation": "这里应该用〈国际规则〉。“准则”是大家共同遵守的规定，形象不是准则。"}, {"text": "他们为这个国家设计了一张国际形象。", "explanation": "这里应该用〈个〉。“形象”是抽象名词，计量用“个”；“张”用于纸、桌子等扁平物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际形象", "is_correct": true, "explanation": "“国际形象”指别国人对我们的印象，“……是别国人对我们的印象”符合句意。"}, {"text": "国际音乐", "is_correct": false, "explanation": "语义：“音乐”是艺术形式，不是别国人对我们的印象，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高度，不能说是别国人对我们的印象。"}, {"text": "国际口号", "is_correct": false, "explanation": "语义：“口号”是宣传用的语句，不是别国人对我们的印象。"}], "explanations": {"国际形象": "“国际形象”指别国人对我们的印象，“……是别国人对我们的印象”符合句意。", "国际音乐": "语义：“音乐”是艺术形式，不是别国人对我们的印象，句意不通。", "身高": "体貌：“身高”指人的身体高度，不能说是别国人对我们的印象。", "国际口号": "语义：“口号”是宣传用的语句，不是别国人对我们的印象。"}, "sentence_index": 6, "correct_answer": "国际形象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国际形象一致谴责这次袭击。", "explanation": "这里应该用〈国际舆论〉。“谴责”的主体是人或舆论，形象不会谴责。"}, {"text": "这些国家都加入了一个国际形象。", "explanation": "这里应该用〈国际组织〉。“加入”的对象是组织、团体，不能加入“形象”。"}, {"text": "国际形象非常紧张。", "explanation": "这里应该用〈国际局势〉。“紧张”形容局势、关系，形象不说“紧张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年我们国家有了一张新的国际形象。", "corrected_sentence": "这几年我们国家有了一个新的国际形象。", "error_description": "错误：“一张国际形象”。正确：“一个国际形象”。“张”用于纸、桌子等扁平物，“形象”是抽象名词，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们努力塑造一位积极的国际形象。", "corrected_sentence": "他们努力塑造一个积极的国际形象。", "error_description": "错误：“一位国际形象”。正确：“一个国际形象”。“位”用于人，“形象”不是人，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
