INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26066, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向公众或多数人发出号召，希望大家去做或不做某事。", "primary_collocate": null, "pronunciation": "hū yù", "ipa": "xu˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "老师呼吁大家一起打扫教室。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长大声呼吁大家不要放弃。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他呼吁同学们少玩手机。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长呼吁大家一起帮助那位老人。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明大声呼吁朋友们周末一起去公园捡垃圾。", "target_word": "呼吁", "complexity_tier": "T3", "furigana": "Xiǎo Míng dà shēng hū yù péng you men zhōu mò yì qǐ qù gōng yuán jiǎn lājī", "sentence_source": "generated"}, {"text": "社区大声呼吁大家一起节约用水。", "target_word": "呼吁", "complexity_tier": "T3", "furigana": "shè qū dà shēng hū yù dà jiā yì qǐ jié yuē yòng shuǐ", "sentence_source": "generated"}, {"text": "医生呼吁大家多喝水、多休息。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们呼吁过大家保护小动物。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在台上，呼吁大家安静一下。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们呼吁大家不要乱扔垃圾。", "target_word": "呼吁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "呼吁了", "label": "完成体"}, {"form": "呼吁过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "向大家发出号召，请人们去做或不做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼吁", "is_correct": true, "explanation": "语境正确：“呼吁”表示向大家发出号召，与“老师……大家一起打扫教室”相合。"}, {"text": "阻止", "is_correct": false, "explanation": "语义：“阻止”与“一起打扫教室”的行为相反，老师阻止大家劳动，读起来不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”与老师组织大家劳动的语境相反，句子不符合常理。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”多接“请求、邀请”等对象，“拒绝一起打扫教室”搭配不当，也与老师的引导语境冲突。"}], "explanations": {"呼吁": "语境正确：“呼吁”表示向大家发出号召，与“老师……大家一起打扫教室”相合。", "阻止": "语义：“阻止”与“一起打扫教室”的行为相反，老师阻止大家劳动，读起来不通。", "嘲笑": "语义：“嘲笑”与老师组织大家劳动的语境相反，句子不符合常理。", "拒绝": "搭配：“拒绝”多接“请求、邀请”等对象，“拒绝一起打扫教室”搭配不当，也与老师的引导语境冲突。"}, "sentence_index": 0, "correct_answer": "呼吁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他呼吁我帮他拿一下书。", "explanation": "这里应该用〈请〉。呼吁是向公众或多数人发出号召，对身边一个人提出简单的请求要用“请”。"}, {"text": "妈妈呼吁我早点睡觉。", "explanation": "这里应该用〈叮嘱〉。呼吁用于向公众或多数人发出号召，家长对孩子的嘱咐要用“叮嘱”。"}, {"text": "孩子在夜里呼吁妈妈。", "explanation": "这里应该用〈呼唤〉。呼吁的对象是公众或多数人，孩子在夜里叫妈妈要用“呼唤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼吁", "is_correct": true, "explanation": "语境正确：“呼吁”表示劝请大家去做某事，与“医生……大家多喝水、多休息”的健康建议相合。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：“禁止”与医生给出的健康建议相反，禁止多喝水、多休息与语境矛盾。"}, {"text": "责怪", "is_correct": false, "explanation": "搭配：“责怪”需接“某人加事由”的结构，“责怪大家多喝水”搭配不通。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”的宾语多指错误行为，“批评大家多喝水”把健康建议当作过错，语义不通。"}], "explanations": {"呼吁": "语境正确：“呼吁”表示劝请大家去做某事，与“医生……大家多喝水、多休息”的健康建议相合。", "禁止": "语义：“禁止”与医生给出的健康建议相反，禁止多喝水、多休息与语境矛盾。", "责怪": "搭配：“责怪”需接“某人加事由”的结构，“责怪大家多喝水”搭配不通。", "批评": "配价：“批评”的宾语多指错误行为，“批评大家多喝水”把健康建议当作过错，语义不通。"}, "sentence_index": 6, "correct_answer": "呼吁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我呼吁你原谅我。", "explanation": "这里应该用〈恳求〉。呼吁面向公众，对某个人表达恳切的请求要用“恳求”。"}, {"text": "我呼吁你少玩手机。", "explanation": "这里应该用〈劝〉。呼吁是向公众或多数人发出号召，对身边的一个人提出建议要用“劝”。"}, {"text": "老人呼吁我照顾他的猫。", "explanation": "这里应该用〈嘱托〉。呼吁是向大家大声说出共同要做的事，把一件具体的事郑重托付给某个人要用“嘱托”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师向全班的呼吁一起打扫教室。", "corrected_sentence": "老师向全班呼吁一起打扫教室。", "error_description": "错误：“呼吁”前多加了“的”，“全班的呼吁”变成名词短语，后面的“一起打扫教室”没有谓语。正确：应说“老师向全班呼吁一起打扫教室”，“呼吁”直接作动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长呼吁给同学们一起整理图书角。", "corrected_sentence": "班长呼吁同学们一起整理图书角。", "error_description": "错误：“呼吁”后直接带对象，对象前不能加“给”。正确：应说“班长呼吁同学们一起整理图书角”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
