INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26068, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "意思是“想要达到”或“为了”。", "primary_collocate": null, "pronunciation": "zhǐ zài", "ipa": "ʈʂɨ˨˩ tsai˥˩", "syllable_count": 2, "sentences": [{"text": "这次调查旨在了解市民对公交的看法。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写这封信旨在向老师表示感谢。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动旨在让人们少用塑料袋。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课旨在培养学生的阅读能力。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的交通办法旨在减少城市里的堵车。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的演讲旨在提醒大家注意健康。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱旨在帮助山区的孩子上学。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场展览旨在介绍中国的茶文化。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师布置这个作业，旨在让我们学会合作。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法旨在解决大家停车难的问题。", "target_word": "旨在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示想要达到的目标，常用于说明计划、活动、措施的用意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3029008e-9b1c-4965-998f-79cba7433aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝了解市民的看法”与调查的目的相反，读起来不通。"}, {"text": "旨在", "is_correct": true, "explanation": "“旨在”表示想要达到的目标，后接“了解”，说明调查的用意。"}, {"text": "完成", "is_correct": false, "explanation": "搭配：“完成”后接的是任务或工作，不能接“了解市民的看法”这样的心理认知。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃了解市民的看法”与做调查的意图相矛盾。"}], "explanations": {"拒绝": "语义：“拒绝了解市民的看法”与调查的目的相反，读起来不通。", "旨在": "“旨在”表示想要达到的目标，后接“了解”，说明调查的用意。", "完成": "搭配：“完成”后接的是任务或工作，不能接“了解市民的看法”这样的心理认知。", "放弃": "语义：“放弃了解市民的看法”与做调查的意图相矛盾。"}, "sentence_index": 0, "correct_answer": "旨在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我旨在明天天气晴朗。", "explanation": "语义：“旨在”表示有意去达到的目的，天气不受人控制，不能作为目的；这里应该用“希望”。"}, {"text": "关键旨在坚持下去。", "explanation": "近义词混用：“在于”用来说明关键所在；“旨在”表示目的，这里应该用“在于”。"}, {"text": "这次考试没及格，旨在题目太难了。", "explanation": "因果：“旨在”表示目的，不能用来说明已经发生的原因；这里应该用“因为”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "退还", "is_correct": false, "explanation": "语义：“退还帮助山区孩子上学”与钱的用途矛盾，读起来不通。"}, {"text": "花费", "is_correct": false, "explanation": "搭配：“花费”的宾语是钱或时间，不能直接接“帮助山区的孩子上学”。"}, {"text": "旨在", "is_correct": true, "explanation": "“旨在”表示目的，后接动词性成分“帮助”，说明这笔钱的用途。"}, {"text": "节约", "is_correct": false, "explanation": "语义：“节约帮助孩子上学”与捐助的用意相反。"}], "explanations": {"退还": "语义：“退还帮助山区孩子上学”与钱的用途矛盾，读起来不通。", "花费": "搭配：“花费”的宾语是钱或时间，不能直接接“帮助山区的孩子上学”。", "旨在": "“旨在”表示目的，后接动词性成分“帮助”，说明这笔钱的用途。", "节约": "语义：“节约帮助孩子上学”与捐助的用意相反。"}, "sentence_index": 6, "correct_answer": "旨在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈旨在做饭呢，没接电话。", "explanation": "语义：“旨在”表示目的，不表示动作正在进行；这里应该用“正在”。"}, {"text": "出门前要锁好门，旨在家里被偷。", "explanation": "语义：“旨在”表示想要达到的目的，不能表示要避免的坏结果；这里应该用“以免”。"}, {"text": "这个孩子旨在害怕黑暗。", "explanation": "配价：“旨在”后接的是可以有意去做的行为，“害怕”是不由自主的心理状态，不能作为目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小组旨在了研究城市交通的问题。", "corrected_sentence": "这个小组旨在研究城市交通的问题。", "error_description": "错误形式：“旨在”后面加了“了”。正确形式：应说“这个小组旨在研究城市交通的问题。”原因：“旨在”后接的是尚未实现的目标，不能带完成标记“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个社区设立了停车场，很旨在方便居民停车。", "corrected_sentence": "这个社区设立了停车场，旨在方便居民停车。", "error_description": "错误形式：“旨在”前面加了副词“很”。正确形式：应说“这个社区设立了停车场，旨在方便居民停车。”原因：“很”一般修饰形容词或部分心理动词，不能修饰“旨在”这类表示目的的词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
