INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几个人商量好、大家一起照着做的约定。", "primary_collocate": null, "pronunciation": "xié yì", "ipa": "ɕjɛ˧˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "我们三人订立了一项协议：谁迟到，谁请客。", "target_word": "协议", "complexity_tier": "T3", "furigana": "wǒmen sān rén dìnglì le yí xiàng xiéyì: shéi chídào, shéi qǐngkè", "sentence_source": "generated"}, {"text": "几个朋友订立了协议：每天早上一起跑步。", "target_word": "协议", "complexity_tier": "T3", "furigana": "jǐ gè péngyou dìnglì le xiéyì: měitiān zǎoshang yìqǐ pǎobù", "sentence_source": "generated"}, {"text": "孩子们有个小协议，不告诉老师。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和妹妹有协议，轮流洗碗。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家事先订立了协议，下午六点在门口见。", "target_word": "协议", "complexity_tier": "T3", "furigana": "dàjiā shìxiān dìnglì le xiéyì, xiàwǔ liù diǎn zài ménkǒu jiàn", "sentence_source": "generated"}, {"text": "他忘了我们的协议，没有来。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的协议是谁先到，谁买水。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们几个人的小协议。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全家有个协议：吃饭时不看手机。", "target_word": "协议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们事先订立了协议：考试前不熬夜。", "target_word": "协议", "complexity_tier": "T3", "furigana": "tóngxuémen shìxiān dìnglì le xiéyì: kǎoshì qián bú áoyè", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "協議", "label": "繁体"}], "register": "书面", "sense_fingerprint": "几个人私下商量好、大家一起照着做的约定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01edaae3-9fb1-4797-a818-53b09db41e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "协议", "is_correct": true, "explanation": "协议（xié yì，第二声、第四声）指几个人私下商量好、大家一起照做的约定，是正确答案。"}, {"text": "谢意", "is_correct": false, "explanation": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。"}, {"text": "写意", "is_correct": false, "explanation": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是写意、描绘意境。"}, {"text": "洗衣", "is_correct": false, "explanation": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。"}, {"text": "西医", "is_correct": false, "explanation": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}], "explanations": {"协议": "协议（xié yì，第二声、第四声）指几个人私下商量好、大家一起照做的约定，是正确答案。", "谢意": "谢意（xiè yì）的第一个音节是第四声，与 xié（第二声）声调不同，意思是感谢。", "写意": "写意（xiě yì）的第一个音节是第三声，与 xié（第二声）声调不同，意思是写意、描绘意境。", "洗衣": "洗衣（xǐ yī）两个音节的声调都与协议（xié yì）不同，意思是洗衣服。", "西医": "西医（xī yī）两个音节的声调都与协议（xié yì）不同，意思是西方医学。"}, "sentence_index": null, "correct_answer": "协议"}, "level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“订立了一项协议”指几个人商量好的约定，“谁迟到，谁请客”正是约定内容，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能被订立，“订立了一项天气”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不是约定，“谁迟到，谁请客”不能作为价格的内容。"}, {"text": "座位", "is_correct": false, "explanation": "语义：座位与“谁迟到，谁请客”无关，不能作为订立的约定内容。"}], "explanations": {"协议": "“订立了一项协议”指几个人商量好的约定，“谁迟到，谁请客”正是约定内容，符合句意。", "天气": "搭配：“天气”不能被订立，“订立了一项天气”说不通。", "价格": "语义：价格不是约定，“谁迟到，谁请客”不能作为价格的内容。", "座位": "语义：座位与“谁迟到，谁请客”无关，不能作为订立的约定内容。"}, "sentence_index": 0, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们俩很有协议，一个眼神就知道对方的想法。", "explanation": "这里应该用〈默契〉。协议要事先商量明确，不能用来形容心照不宣的配合。"}, {"text": "早上跑步已经成了我的协议。", "explanation": "这里应该用〈习惯〉。协议是几个人事先商量好的约定，自己长期养成的做法用习惯。"}, {"text": "我把这周的协议写在了日记本上。", "explanation": "这里应该用〈计划〉。协议需要几个人一起商量好，自己一个人定的安排用计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "协议", "is_correct": true, "explanation": "“我们的协议是谁先到，谁买水”说明的是大家商量好的约定，符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是约定，“名字是谁先到，谁买水”无法成立。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能表示“谁先到，谁买水”的约定。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是要喝的东西，不能说“饮料是谁先到，谁买水”。"}], "explanations": {"协议": "“我们的协议是谁先到，谁买水”说明的是大家商量好的约定，符合句意。", "名字": "语义：名字不是约定，“名字是谁先到，谁买水”无法成立。", "作业": "语义：作业是学习任务，不能表示“谁先到，谁买水”的约定。", "饮料": "语义：饮料是要喝的东西，不能说“饮料是谁先到，谁买水”。"}, "sentence_index": 6, "correct_answer": "协议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对妈妈许下了协议，每天写作业。", "explanation": "这里应该用〈承诺〉。承诺是一方对另一方的保证，协议要几个人一起商量好。"}, {"text": "老师给我们布置了协议：背十首古诗。", "explanation": "这里应该用〈任务〉。协议要几个人商量好，老师单方面布置的要求用任务。"}, {"text": "我们班的班歌是一首好听的歌。", "explanation": "这里应该用〈班歌〉。协议是几个人商量好要遵守的约定，一首歌不是约定，应说班歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们三人订好了一协议。", "corrected_sentence": "我们三人订好了协议。", "error_description": "“协议”前用数量词“一”时需要量词，应说“一份协议”；此句中“协议”前不需要数量词，应说“订好了协议”，不能说“订好了一协议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前订了过协议。", "corrected_sentence": "我们以前订过协议。", "error_description": "“了”和“过”不能同时用在同一动词后。表示曾经做过要用“过”，应说“订过协议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
