INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26079, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "双方就某件事反复商量、讨价还价，争取达成各自想要的结果。", "primary_collocate": null, "pronunciation": "tán pàn", "ipa": "tʰan³⁵ pʰan⁵¹", "syllable_count": 2, "sentences": [{"text": "我和房东谈判了很久，他才同意少收钱。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想多玩一小时，正在跟妈妈谈判。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先谈判一下，看看价钱能不能便宜。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和老板谈判，想要更多的假期。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西的时候，你可以和老板谈判价格。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子为了玩具，在客厅里谈判。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不用吵，我们坐下来谈判吧。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩谈判了半天，还是没分好蛋糕。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想吵架，只想好好谈判。", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想跟老师谈判，晚一天交作业可以吗？", "target_word": "谈判", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "谈判了", "label": "体标（了）"}, {"form": "谈判过", "label": "体标（过）"}, {"form": "谈判一下", "label": "动量结构"}, {"form": "談判", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个人或两边的人为一件事互相商量，争取各自想要的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26079, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谈判", "is_correct": true, "explanation": "“才同意少收钱”说明双方经过讨价还价，“谈判”指双方商量并达成结果，与语境相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步只是闲逛，不涉及讨价还价，无法导致房东“同意少收钱”。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”不是商量事情，与“才同意少收钱”之间没有合理的因果关系。"}, {"text": "旅行", "is_correct": false, "explanation": "搭配：“和房东旅行”后接“才同意少收钱”，二者之间没有可以商量价格的关联。"}], "explanations": {"谈判": "“才同意少收钱”说明双方经过讨价还价，“谈判”指双方商量并达成结果，与语境相符。", "散步": "语义：散步只是闲逛，不涉及讨价还价，无法导致房东“同意少收钱”。", "玩": "语义：“玩”不是商量事情，与“才同意少收钱”之间没有合理的因果关系。", "旅行": "搭配：“和房东旅行”后接“才同意少收钱”，二者之间没有可以商量价格的关联。"}, "sentence_index": 0, "correct_answer": "谈判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我跟老板谈判，希望他原谅我。", "explanation": "这里应该用〈道歉〉。谈判是双方各有诉求、商量出结果，请求原谅不是谈判。"}, {"text": "我和朋友谈判了这部电影的好坏。", "explanation": "这里应该用〈讨论〉。谈判要为达成一致而协商，只是交流对电影的看法时用讨论。"}, {"text": "我一个人在屋里谈判了很久。", "explanation": "谈判至少需要两方，且要围绕有分歧的事商量；一个人不能谈判，这里应说〈想了很久〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26079, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谈判", "is_correct": true, "explanation": "“坐下来”和“不用吵”说明双方要心平气和地商量，“谈判”符合语境。"}, {"text": "打架", "is_correct": false, "explanation": "语义：“打架”与“不用吵”的意思相反，也与坐下来好好商量的语境冲突。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“坐下来”后接的应是安静交谈的活动，“跑步”需要起身奔跑，二者不搭。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与商量事情无关，句中劝双方商量的语境无法接受。"}], "explanations": {"谈判": "“坐下来”和“不用吵”说明双方要心平气和地商量，“谈判”符合语境。", "打架": "语义：“打架”与“不用吵”的意思相反，也与坐下来好好商量的语境冲突。", "跑步": "搭配：“坐下来”后接的应是安静交谈的活动，“跑步”需要起身奔跑，二者不搭。", "睡觉": "语义：“睡觉”与商量事情无关，句中劝双方商量的语境无法接受。"}, "sentence_index": 6, "correct_answer": "谈判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我跟妈妈谈判了今天的天气。", "explanation": "这里应该用〈聊〉。谈判的对象必须是双方有分歧、需要商量结果的事，天气不是谈判的对象，只能说“聊天气”。"}, {"text": "我跟同学谈判地球是不是圆的。", "explanation": "这里应该用〈争论〉。谈判是为利益或安排商量出结果；地球是不是圆的是客观事实，只能争论或查证，不能谈判。"}, {"text": "两支球队在球场上谈判了半场。", "explanation": "谈判是双方为达成一致而协商，比赛双方是竞争关系，不能说谈判；这里应说〈比赛〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们先谈判的一下这个价钱吧。", "corrected_sentence": "我们先谈判一下这个价钱吧。", "error_description": "错误：多出了“的”。“谈判”是动词，其后不能直接加“的”，应说“谈判一下这个价钱”，删去“的”即可，正确句为“我们先谈判一下这个价钱吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想跟老板谈判了，争取一点加薪。", "corrected_sentence": "我想跟老板谈判，争取一点加薪。", "error_description": "体标错误：“想”表示尚未发生的打算，不能与“了”搭配，应说“我想跟老板谈判”，不能说“我想跟老板谈判了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
