INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文书就是写在纸上的文件或信件。", "primary_collocate": null, "pronunciation": "wén shū", "ipa": "wən³⁵ ʂu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他把重要的文书放在抽屉里。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶留下了一份很旧的文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文书是用毛笔写的。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在桌子上找到一份文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文书上写着我们家的地址。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看文书，一边写笔记。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份文书寄给王先生。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文书丢了，我们得重新写一份。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们抄写一份文书。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看过那份文书，没有说话。", "target_word": "文书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份文书", "label": "量词（份）"}, {"form": "旧文书", "label": "复合词"}, {"form": "文書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "写在纸上的文件或信件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书指写在纸上的文件或信件，可以放进抽屉，与句意相符。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车体积太大，放不进抽屉。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象不可能放进抽屉里。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：形容词“重要的”通常修饰文件、证件等，不修饰饮料。"}], "explanations": {"文书": "文书指写在纸上的文件或信件，可以放进抽屉，与句意相符。", "汽车": "语义：汽车体积太大，放不进抽屉。", "大象": "语义：大象不可能放进抽屉里。", "饮料": "搭配：形容词“重要的”通常修饰文件、证件等，不修饰饮料。"}, "sentence_index": 0, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在晚会上唱了文书，大家都很喜欢。", "explanation": "这里应该用〈歌〉。唱的是歌曲，文书指写在纸上的文件或信件，不能用来唱。"}, {"text": "他花了一晚上煮了一份文书，香味很浓。", "explanation": "这里应该用〈汤〉。文书指写在纸上的文件或信件，不能用来煮。"}, {"text": "我在桌子上找到一只文书。", "explanation": "这里应该用〈份〉。文书是纸张，量词用“份”或“封”（信件），“只”用于动物等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文书", "is_correct": true, "explanation": "文书指写在纸上的文件或信件，可以寄出，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见摸不着，不能装进信封寄出。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是自然现象，不是可以寄出的物品。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：量词“份”一般搭配文件、礼物，不说“这份雨水”。"}], "explanations": {"文书": "文书指写在纸上的文件或信件，可以寄出，与句意相符。", "空气": "语义：空气看不见摸不着，不能装进信封寄出。", "闪电": "语义：闪电是自然现象，不是可以寄出的物品。", "雨水": "搭配：量词“份”一般搭配文件、礼物，不说“这份雨水”。"}, "sentence_index": 6, "correct_answer": "文书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天晚上写文书，记录当天的心情。", "explanation": "这里应该用〈日记〉。文书是写在纸上的文件或信件，多用于办事或传递信息，不用来记录个人心情。"}, {"text": "他在操场上踢文书，玩得很开心。", "explanation": "这里应该用〈足球〉。文书指写在纸上的文件或信件，不能用来踢。"}, {"text": "他这几年一直在写文书，讲一个小镇的故事。", "explanation": "这里应该用〈小说〉。文书指写在纸上的公务文件或信件，不是虚构的叙事作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那只文书交给了律师。", "corrected_sentence": "他把那份文书交给了律师。", "error_description": "量词错误：“文书”是纸张，应用量词“份”，不用“只”（“只”用于动物等）。应说“那份文书”，不说“那只文书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那份文书我已经读了过。", "corrected_sentence": "那份文书我已经读过了。", "error_description": "体标错误：“了”与“过”不能叠用，应说“读过了”，不说“读了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个东西从这里拿到那里。", "primary_collocate": null, "pronunciation": "zhuǎn yí", "ipa": "ʈʂwan˨˩ i˧˥", "syllable_count": 2, "sentences": [{"text": "他把文件转移到新的柜子里。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这批数据转移到新的服务器上。", "target_word": "转移", "complexity_tier": "T3", "furigana": "qǐng bǎ zhè pī shùjù zhuǎnyí dào xīn de fúwùqì shàng", "sentence_source": "generated"}, {"text": "搬家时，我们把旧档案转移到了新的仓库。", "target_word": "转移", "complexity_tier": "T3", "furigana": "bānjiā shí, wǒmen bǎ jiù dàng''àn zhuǎnyí dào le xīn de cāngkù", "sentence_source": "generated"}, {"text": "她把样品从大罐转移到小瓶里。", "target_word": "转移", "complexity_tier": "T3", "furigana": "tā bǎ yàngpǐn cóng dà guàn zhuǎnyí dào xiǎo píng lǐ", "sentence_source": "generated"}, {"text": "我想把照片转移到电脑上。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在转移仓库里的东西。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他悄悄转移了桌上的东西。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂把生产线转移到了另一个城市。", "target_word": "转移", "complexity_tier": "T3", "furigana": "gōngchǎng bǎ shēngchǎnxiàn zhuǎnyí dào le lìng yí gè chéngshì", "sentence_source": "generated"}, {"text": "仓库管理员把这批货物转移到了港口。", "target_word": "转移", "complexity_tier": "T3", "furigana": "cāngkù guǎnlǐyuán bǎ zhè pī huòwù zhuǎnyí dào le gǎngkǒu", "sentence_source": "generated"}, {"text": "她把鸡蛋转移到另一个盒子里。", "target_word": "转移", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转移了", "label": "体标"}, {"form": "转移着", "label": "体标"}, {"form": "转移过", "label": "体标"}, {"form": "轉移", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把物品或东西从一处搬到、移到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01edaae3-9fb1-4797-a818-53b09db41e91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转移", "is_correct": true, "explanation": "转移（zhuǎn yí，第三声、第二声）指把东西从一处搬到另一处，是正确答案。"}, {"text": "转椅", "is_correct": false, "explanation": "转椅（zhuàn yǐ）两个音节的声调都与转移（zhuǎn yí）不同，意思是可以旋转的椅子。"}, {"text": "专一", "is_correct": false, "explanation": "专一（zhuān yī）两个音节的声调都与转移（zhuǎn yí）不同，意思是专心、不分散。"}, {"text": "转义", "is_correct": false, "explanation": "转义（zhuǎn yì）只有第二个音节的声调与转移（zhuǎn yí）不同，意思是词语的引申含义。"}], "explanations": {"转移": "转移（zhuǎn yí，第三声、第二声）指把东西从一处搬到另一处，是正确答案。", "转椅": "转椅（zhuàn yǐ）两个音节的声调都与转移（zhuǎn yí）不同，意思是可以旋转的椅子。", "专一": "专一（zhuān yī）两个音节的声调都与转移（zhuǎn yí）不同，意思是专心、不分散。", "转义": "转义（zhuǎn yì）只有第二个音节的声调与转移（zhuǎn yí）不同，意思是词语的引申含义。"}, "sentence_index": null, "correct_answer": "转移"}, "level_3": {"options": [{"text": "转移", "is_correct": true, "explanation": "“把文件转移到新的柜子里”指把文件从一处搬到另一处，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于文件，“把文件吃到柜子里”无法成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不是文件，“把文件唱到柜子里”说不通。"}, {"text": "删", "is_correct": false, "explanation": "搭配：“删”指去掉内容，不带“到……里”表示搬运的终点，搭配不通。"}], "explanations": {"转移": "“把文件转移到新的柜子里”指把文件从一处搬到另一处，符合句意。", "吃": "语义：“吃”不能用于文件，“把文件吃到柜子里”无法成立。", "唱": "语义：“唱”的对象不是文件，“把文件唱到柜子里”说不通。", "删": "搭配：“删”指去掉内容，不带“到……里”表示搬运的终点，搭配不通。"}, "sentence_index": 0, "correct_answer": "转移"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们把旧房子转移成了咖啡馆。", "explanation": "这里应该用〈改造〉。转移指东西从一处搬到另一处，把房子改成另一种用途要用改造。"}, {"text": "他用相机转移了那片云。", "explanation": "这里应该用〈拍〉。转移是把东西从一处搬到另一处，用相机记录景物要用拍。"}, {"text": "工人转移了那面旧墙的裂缝。", "explanation": "这里应该用〈修补〉。转移指把东西搬到别处，裂缝不能被搬走，应说修补。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转移", "is_correct": true, "explanation": "“他悄悄转移了桌上的东西”指暗中把桌上的东西移开，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象不是物品，“悄悄唱了桌上的东西”说不通。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，“喂了桌上的东西”说不通。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：祝贺的对象是人或事，不能用于桌上的东西。"}], "explanations": {"转移": "“他悄悄转移了桌上的东西”指暗中把桌上的东西移开，符合句意。", "唱": "语义：“唱”的对象不是物品，“悄悄唱了桌上的东西”说不通。", "喂": "搭配：“喂”的对象是人或动物，“喂了桌上的东西”说不通。", "祝贺": "语义：祝贺的对象是人或事，不能用于桌上的东西。"}, "sentence_index": 6, "correct_answer": "转移"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把饭转移碎了。", "explanation": "这里应该用〈嚼〉。转移是搬动东西，不指把饭弄碎，把饭咀嚼碎要用嚼。"}, {"text": "她把自己转移得很漂亮。", "explanation": "这里应该用〈打扮〉。转移指搬动东西，不指修饰外表。"}, {"text": "他转移了一口苹果。", "explanation": "这里应该用〈咬〉。转移指搬到别处，不能把一口苹果搬走，咬下一口要用咬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钥匙转移在另一个口袋里。", "corrected_sentence": "他把钥匙转移到另一个口袋里。", "error_description": "表示搬到的终点要用“到”，不用“在”。应说“转移到另一个口袋里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾经转移着这批货物。", "corrected_sentence": "我们曾经转移过这批货物。", "error_description": "“着”表示动作持续或状态保持，与“曾经”表示的过去经历不搭。应说“转移过这批货物”，“过”要紧跟在动词后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ea7dbde-5da2-430e-b9ae-300258b83ac7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
