INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26090, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始写一个文件或计划的第一版。", "primary_collocate": null, "pronunciation": "qǐ cǎo", "ipa": "tɕʰi˨˩˦ tsʰɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "她打开电脑，开始起草演讲稿。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份申请书是我昨晚起草的。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先起草，再慢慢修改，文章会更好。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秘书起草好通知以后交给了经理。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在起草给客户的回信。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先起草一份简单的计划书。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们分组起草班级规则。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师起草了一份学习要求。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先起草一个提纲，我来补充。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新制度的第一稿起草出来了。", "target_word": "起草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起草了", "label": "完成体"}, {"form": "起草过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "动笔写出文件、计划、稿子的第一版，之后再修改", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3029008e-9b1c-4965-998f-79cba7433aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的宾语应为食物，不能说吃「演讲稿」。"}, {"text": "起草", "is_correct": true, "explanation": "起草：开始写出演讲稿的初稿，与「开始」的动作相符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：「摘」用于果实、花草等，不能摘「演讲稿」。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」指唱歌、吟唱，与「开始写演讲稿」的意思不符。"}], "explanations": {"吃": "搭配：「吃」的宾语应为食物，不能说吃「演讲稿」。", "起草": "起草：开始写出演讲稿的初稿，与「开始」的动作相符。", "摘": "搭配：「摘」用于果实、花草等，不能摘「演讲稿」。", "唱": "语义：「唱」指唱歌、吟唱，与「开始写演讲稿」的意思不符。"}, "sentence_index": 0, "correct_answer": "起草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他起草了一幅字。", "explanation": "这里应该用〈写〉。写字、作画用〈写〉，起草指拟写文件、方案等文字材料，不能用于书法作品。"}, {"text": "我们起草了一段视频。", "explanation": "这里应该用〈制作〉。视频要拍摄、剪辑制作，不是起草的文字材料。"}, {"text": "这套房子是他起草的。", "explanation": "这里应该用〈设计〉。房子是设计、建造出来的，不能用起草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "搭配：「煮」只用于食物，不能说煮「班级规则」。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」指丢弃，与分组拟定班级规则的意思相反。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」指擦拭，与拟定规则的行为无关。"}, {"text": "起草", "is_correct": true, "explanation": "起草：分组初步拟写班级规则，与句意相符。"}], "explanations": {"煮": "搭配：「煮」只用于食物，不能说煮「班级规则」。", "扔": "语义：「扔」指丢弃，与分组拟定班级规则的意思相反。", "擦": "语义：「擦」指擦拭，与拟定规则的行为无关。", "起草": "起草：分组初步拟写班级规则，与句意相符。"}, "sentence_index": 6, "correct_answer": "起草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们起草了一场新学期活动。", "explanation": "这里应该用〈策划〉。起草针对文件、方案的文字内容，活动要策划，不能说起草。"}, {"text": "学校起草了一场篮球比赛。", "explanation": "这里应该用〈组织〉。比赛是组织、举办的活动，不是文件，不能用起草。"}, {"text": "这档节目是他起草的。", "explanation": "这里应该用〈录制〉。节目要录制、制作，不是起草的文字内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸正在起草了一封感谢信。", "corrected_sentence": "爸爸正在起草一封感谢信。", "error_description": "错误：「正在」表示动作进行中，不能与完成体「了」同用。应去掉「了」，说「正在起草一封感谢信」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没起草了申请书。", "corrected_sentence": "我还没起草过申请书。", "error_description": "错误：「还没」后面要用经历体「过」，不能用完成体「了」。应说「还没起草过申请书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
