INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "比别人好的地方。", "primary_collocate": null, "pronunciation": "yōu shì", "ipa": "joʊ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他个子高，打篮球很有优势。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会说两种语言是你的优势。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的最大优势是价格低。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队在人数上有优势。", "target_word": "优势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人的优势是学得快。", "target_word": "优势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的优势是交通方便。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的优势是会做饭，也会唱歌。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机的优势在于电池用得久。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有经验，这是他最大的优势。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要发挥自己的优势。", "target_word": "优势", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "胜过他人的有利条件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26092, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优势", "is_correct": true, "explanation": "正确答案，指比别人好的地方。"}, {"text": "有事", "is_correct": false, "explanation": "第一音节声调不同（yǒu 第三声，yōu 第一声），意思是有事情要做。"}, {"text": "有时", "is_correct": false, "explanation": "两个音节的声调都不同（yǒu 第三声、shí 第二声），意思是有的时候。"}, {"text": "优质", "is_correct": false, "explanation": "第二音节声母不同（zhì 与 shì，zh 与 sh），意思是质量好。"}, {"text": "油市", "is_correct": false, "explanation": "第一音节声调不同（yóu 第二声与 yōu 第一声），意思是石油市场。"}], "explanations": {"优势": "正确答案，指比别人好的地方。", "有事": "第一音节声调不同（yǒu 第三声，yōu 第一声），意思是有事情要做。", "有时": "两个音节的声调都不同（yǒu 第三声、shí 第二声），意思是有的时候。", "优质": "第二音节声母不同（zhì 与 shì，zh 与 sh），意思是质量好。", "油市": "第一音节声调不同（yóu 第二声与 yōu 第一声），意思是石油市场。"}, "sentence_index": null, "correct_answer": "优势"}, "level_3": {"options": [{"text": "钱", "is_correct": false, "explanation": "语义：钱说的是经济状况，与打篮球的能力无关，读起来像是说他很富有。"}, {"text": "道理", "is_correct": false, "explanation": "搭配：“有道理”用于说法或做法，不用于描述运动能力。"}, {"text": "优势", "is_correct": true, "explanation": "优势指比别人好的有利条件，与个子高、打球有利的语境相符。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪大说明年老，与个子高、打球灵活的语境相矛盾。"}], "explanations": {"钱": "语义：钱说的是经济状况，与打篮球的能力无关，读起来像是说他很富有。", "道理": "搭配：“有道理”用于说法或做法，不用于描述运动能力。", "优势": "优势指比别人好的有利条件，与个子高、打球有利的语境相符。", "年纪": "语义：年纪大说明年老，与个子高、打球灵活的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "优势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "多喝水对身体有很多优势。", "explanation": "这里应该用〈好处〉。优势指与别人相比的有利条件，说对身体的益处要用〈好处〉。"}, {"text": "这个学生的数学优势很高。", "explanation": "这里应该用〈水平〉。优势是有利条件，不以高低来衡量，说程度高低要用〈水平〉，如“数学水平很高”。"}, {"text": "我们队的优势增加了三个人。", "explanation": "这里应该用〈人数〉。优势指有利条件，不能用来计数；队里人员增加要说〈人数〉，如「我们队的人数增加了三个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缺点", "is_correct": false, "explanation": "语义：缺点指不足之处，与“会做饭，也会唱歌”这样的长处相矛盾。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述外形，不能用来概括会做饭、会唱歌这样的能力。"}, {"text": "优势", "is_correct": true, "explanation": "优势指比别人好的地方，此处指她擅长的长处，符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄说明岁数，不能用来列举她会做的事情。"}], "explanations": {"缺点": "语义：缺点指不足之处，与“会做饭，也会唱歌”这样的长处相矛盾。", "身材": "体貌：身材描述外形，不能用来概括会做饭、会唱歌这样的能力。", "优势": "优势指比别人好的地方，此处指她擅长的长处，符合语境。", "年龄": "语义：年龄说明岁数，不能用来列举她会做的事情。"}, "sentence_index": 6, "correct_answer": "优势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方案的优势是成本太高。", "explanation": "这里应该用〈缺点〉。优势指比别人好的地方，成本太高是不足之处，应该说〈缺点〉。"}, {"text": "这次地震给这座城市造成了很大的优势。", "explanation": "这里应该用〈损失〉。优势指有利条件，地震带来的是破坏，应该说〈损失〉，如「造成了很大的损失」。"}, {"text": "他这次考了很好的优势。", "explanation": "这里应该用〈成绩〉。考试的结果要说〈成绩〉，“考了优势”不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队在速度上占了一只优势。", "corrected_sentence": "我们队在速度上占了一个优势。", "error_description": "量词错误：“优势”是抽象名词，计量要用“个”，不能用“只”。正确：“占了一个优势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电脑的优势是于速度快。", "corrected_sentence": "这台电脑的优势在于速度快。", "error_description": "错误：“在于”被写成了“是于”。正确：“优势在于速度快”，表示优势的所在要用“在于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
