INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26093, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "尽力去做。", "primary_collocate": null, "pronunciation": "lì tú", "ipa": "li˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "他力图跑得更快，可是腿已经没力气了。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我国力图在十年内消除贫困。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂力图提高产量，同时保证质量。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她力图让孩子明白读书的重要。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对手力图阻止他进球，但没成功。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生力图救活这位病人。", "target_word": "力图", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新政策力图解决住房问题。", "target_word": "力图", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他力图改变自己的生活。", "target_word": "力图", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这篇文章力图说明环境保护的意义。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她力图控制情绪，不让别人看出来。", "target_word": "力图", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "尽全力去做某件事，强调努力的目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d1afd8d-7568-4ad1-946b-8aa6b7a80d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "力图", "is_correct": true, "explanation": "力图：尽力去做，这里表示他想跑得更快。"}, {"text": "拖延", "is_correct": false, "explanation": "配价：“拖延”需要接时间或事项作宾语，不能直接带“跑得更快”这样的动作结构。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“想跑得更快”的意图正相反。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”是讨厌的意思，与“跑得更快”的追求不合。"}], "explanations": {"力图": "力图：尽力去做，这里表示他想跑得更快。", "拖延": "配价：“拖延”需要接时间或事项作宾语，不能直接带“跑得更快”这样的动作结构。", "放弃": "语义：“放弃”与“想跑得更快”的意图正相反。", "厌恶": "语义：“厌恶”是讨厌的意思，与“跑得更快”的追求不合。"}, "sentence_index": 0, "correct_answer": "力图"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他力图被车撞倒了。", "explanation": "这里应该用〈遭遇〉。力图表示主动尽力去做，被车撞倒是被动的遭遇，不能用“力图”。"}, {"text": "下雨了，他力图淋湿了衣服。", "explanation": "这里应该用〈不小心〉。力图指有意尽力去做，淋湿衣服是无意的，不能用“力图”。"}, {"text": "这盏灯力图自己亮起来。", "explanation": "这里应该用〈自动〉。力图表示有意识地尽力去做，灯自己亮起来是自动发生的，应说“自动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力图", "is_correct": true, "explanation": "力图：尽力去做，这里表示新政策努力要解决的目标。"}, {"text": "停止", "is_correct": false, "explanation": "语义：政策“停止解决”住房问题，与政策的目的正相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：政策“拒绝解决”住房问题与政策本身的性质相反，与语境冲突。"}, {"text": "懒得", "is_correct": false, "explanation": "语域：“懒得”是口语，带有个人情绪，不适合用于正式的政策语境。"}], "explanations": {"力图": "力图：尽力去做，这里表示新政策努力要解决的目标。", "停止": "语义：政策“停止解决”住房问题，与政策的目的正相反。", "拒绝": "语义：政策“拒绝解决”住房问题与政策本身的性质相反，与语境冲突。", "懒得": "语域：“懒得”是口语，带有个人情绪，不适合用于正式的政策语境。"}, "sentence_index": 6, "correct_answer": "力图"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他力图突然打了个喷嚏。", "explanation": "这里应该用〈不由自主〉。力图指主动尽力去做，打喷嚏不受意识控制，不能用“力图”。"}, {"text": "他力图每天都下雨。", "explanation": "这里应该用〈盼望〉。力图指主动尽力去做，天气不由人控制，不能用“力图”。"}, {"text": "他力图一觉醒来就长高了。", "explanation": "这里应该用〈希望〉。力图指有意识地尽力去做，身高增长不能靠努力达到，不能用“力图”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他力图过在比赛前恢复体力。", "corrected_sentence": "他力图在比赛前恢复体力。", "error_description": "错误：“力图”后多了“过”。正确应为“力图在比赛前……”，“过”表示经历，不能接在“力图”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府力图着改善城市的交通状况。", "corrected_sentence": "政府力图改善城市的交通状况。", "error_description": "错误：“力图”后多了“着”。正确应为“力图改善……”，“着”不能接在“力图”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54654dd-d0a3-471f-a5a0-4923a4acf613') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
