INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不让做某些事情。", "primary_collocate": null, "pronunciation": "jìn xiàn", "ipa": "tɕin˥˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "公园里的禁限都写在牌子上，比如不能踩草。", "target_word": "禁限", "complexity_tier": "T3", "furigana": "gōng yuán lǐ de jìnxiàn dōu xiě zài páizi shàng, bǐrú bù néng cǎi cǎo", "sentence_source": "generated"}, {"text": "学校对玩手机有禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路对大卡车有禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的禁限是为了大家好。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子觉得家里的禁限太多，不开心。", "target_word": "禁限", "complexity_tier": "T3", "furigana": "hái zi juéde jiā lǐ de jìnxiàn tài duō, bù kāixīn", "sentence_source": "generated"}, {"text": "游泳池的禁限主要是为了安全。", "target_word": "禁限", "complexity_tier": "T3", "furigana": "yóu yǒng chí de jìnxiàn zhǔyào shì wèile ānquán", "sentence_source": "generated"}, {"text": "我们要知道图书馆的禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸给我们定了上网的禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市对放烟花有禁限。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，禁限不是为了惩罚学生。", "target_word": "禁限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不让做某些事情的规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26098, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：禁限 jìnxiàn，指不让做某些事情的规定。"}, {"text": "进行", "is_correct": false, "explanation": "进行 jìnxíng 与 jìnxiàn 韵母不同（-ing / -ian），意思是进行、开展。"}, {"text": "尽心", "is_correct": false, "explanation": "尽心 jìnxīn 与 jìnxiàn 韵母不同（-in / -ian），意思是竭尽心力。"}, {"text": "进香", "is_correct": false, "explanation": "进香 jìnxiāng 与 jìnxiàn 韵母不同（-iang / -ian），意思是到寺庙烧香拜神。"}, {"text": "金线", "is_correct": false, "explanation": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}], "explanations": {"禁限": "正确：禁限 jìnxiàn，指不让做某些事情的规定。", "进行": "进行 jìnxíng 与 jìnxiàn 韵母不同（-ing / -ian），意思是进行、开展。", "尽心": "尽心 jìnxīn 与 jìnxiàn 韵母不同（-in / -ian），意思是竭尽心力。", "进香": "进香 jìnxiāng 与 jìnxiàn 韵母不同（-iang / -ian），意思是到寺庙烧香拜神。", "金线": "金线 jīnxiàn 与 jìnxiàn 第一音节声调不同（阴平 / 去声），意思是金色的线。"}, "sentence_index": null, "correct_answer": "禁限"}, "level_3": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：「公园里的禁限都写在牌子上」中，禁限指不让做某些事的规定，可以写在牌子上。"}, {"text": "烤鸭", "is_correct": false, "explanation": "语义：烤鸭是食物，不是能写在牌子上、约束行为的规定，与‘比如不能踩草’的语境冲突。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不能写在牌子上，与‘比如不能踩草’的规定语境冲突。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是衣物，不是能写在牌子上、约束行为的规定，与“比如不能踩草”的语境冲突。"}], "explanations": {"禁限": "正确：「公园里的禁限都写在牌子上」中，禁限指不让做某些事的规定，可以写在牌子上。", "烤鸭": "语义：烤鸭是食物，不是能写在牌子上、约束行为的规定，与‘比如不能踩草’的语境冲突。", "脾气": "语义：脾气不能写在牌子上，与‘比如不能踩草’的规定语境冲突。", "雨衣": "语义：雨衣是衣物，不是能写在牌子上、约束行为的规定，与“比如不能踩草”的语境冲突。"}, "sentence_index": 0, "correct_answer": "禁限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的禁限很有趣。", "explanation": "这里应该用〈内容〉。禁限指禁止和限制的规定，不指书的内容；说书有意思应该用‘内容’作主语。"}, {"text": "他被学校记了一次禁限。", "explanation": "这里应该用〈过〉。禁限指规定，不指处罚；学校给学生记录违纪要说‘记过’。"}, {"text": "医院里有一朵禁限。", "explanation": "这里应该用〈条〉或〈项〉。量词‘朵’用于花朵，禁限是规定，应说‘一条禁限’。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26098, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：禁限 jìnxiàn，指不让做某些事情的规定。"}, {"text": "尽显", "is_correct": false, "explanation": "尽显 jìnxiǎn 与 jìnxiàn 声调不同（第三声 / 第四声），意思是充分显示。"}, {"text": "尽信", "is_correct": false, "explanation": "尽信 jìnxìn 与 jìnxiàn 韵母不同（-in / -ian），意思是完全相信。"}, {"text": "尽孝", "is_correct": false, "explanation": "尽孝 jìnxiào 与 jìnxiàn 末尾音不同（-ao / -an），意思是孝敬父母。"}, {"text": "进项", "is_correct": false, "explanation": "进项 jìnxiàng 与 jìnxiàn 韵母不同（-iang / -ian），意思是收入。"}], "explanations": {"禁限": "正确：禁限 jìnxiàn，指不让做某些事情的规定。", "尽显": "尽显 jìnxiǎn 与 jìnxiàn 声调不同（第三声 / 第四声），意思是充分显示。", "尽信": "尽信 jìnxìn 与 jìnxiàn 韵母不同（-in / -ian），意思是完全相信。", "尽孝": "尽孝 jìnxiào 与 jìnxiàn 末尾音不同（-ao / -an），意思是孝敬父母。", "进项": "进项 jìnxiàng 与 jìnxiàn 韵母不同（-iang / -ian），意思是收入。"}, "sentence_index": null, "correct_answer": "禁限"}, "level_3": {"options": [{"text": "禁限", "is_correct": true, "explanation": "正确：「我们要知道图书馆的禁限」中，禁限指图书馆不让做的事的规定，是需要知道的内容。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烧烤是饮食活动，不是图书馆需要让人知道的规定，与语境冲突。"}, {"text": "床", "is_correct": false, "explanation": "语义：床是家具，不属于图书馆需要让人知道的规定，与语境冲突。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是衣物，不是图书馆需要让人知道的规定，与语境冲突。"}], "explanations": {"禁限": "正确：「我们要知道图书馆的禁限」中，禁限指图书馆不让做的事的规定，是需要知道的内容。", "烧烤": "语义：烧烤是饮食活动，不是图书馆需要让人知道的规定，与语境冲突。", "床": "语义：床是家具，不属于图书馆需要让人知道的规定，与语境冲突。", "雨衣": "语义：雨衣是衣物，不是图书馆需要让人知道的规定，与语境冲突。"}, "sentence_index": 6, "correct_answer": "禁限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天吃一个禁限。", "explanation": "这里应该用〈苹果〉。禁限是规定，不能吃；说吃的东西，要用“苹果”。"}, {"text": "这次比赛的禁限是三十人。", "explanation": "这里应该用〈名额〉。禁限指禁止和限制的规定，不指人数。"}, {"text": "院子里种了一些禁限。", "explanation": "这里应该用〈草〉。禁限指规定，不是植物，种在地里的要说‘草’。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公园里有一朵禁限，不能在草地上野餐。", "corrected_sentence": "公园里有一条禁限，不能在草地上野餐。", "error_description": "量词错误：禁限是规定，应用量词‘条’。‘朵’用于花，说‘一朵禁限’是错的，正确应为‘一条禁限’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校对打篮球吃了禁限。", "corrected_sentence": "学校对打篮球制定了禁限。", "error_description": "搭配错误：“吃”不能与“禁限”搭配；禁限应与“制定”搭配，正确形式：“制定了禁限”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
