INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26102, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道还没发生的事情。", "primary_collocate": null, "pronunciation": "yù jiàn", "ipa": "y⁵¹ tɕjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "她预见到明天会下雨，所以带了伞。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早就预见他会迟到。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说他能预见将来发生的事。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也预见不了明天会发生什么。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子好像预见了老师会出什么题。", "target_word": "预见", "complexity_tier": "T3", "furigana": "zhè ge hái zi hǎoxiàng yùjiàn le lǎoshī huì chū shénme tí", "sentence_source": "generated"}, {"text": "爸爸预见到天气会变冷，给我买了毛衣。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能预见这个游戏的结局吗？", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他预见到自己会成功，所以一点也不怕。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有预见到路上会堵车。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她好像预见了我要来，早就做好了饭。", "target_word": "预见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "预见到", "label": "结果补语"}, {"form": "预见了", "label": "体标"}, {"form": "预见不了", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "提前知道还没发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指知道还没发生的事情。"}, {"text": "物件", "is_correct": false, "explanation": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），声母都是零声母，意思是物品。"}, {"text": "预检", "is_correct": false, "explanation": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。"}, {"text": "去见", "is_correct": false, "explanation": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。"}], "explanations": {"预见": "正确：预见 yùjiàn，指知道还没发生的事情。", "物件": "物件 wùjiàn 与 yùjiàn 韵母不同（u / ü），声母都是零声母，意思是物品。", "预检": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。", "去见": "去见 qùjiàn 与 yùjiàn 声母不同（q / 零声母），意思是前去会见。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「她预见到明天会下雨，所以带了伞」中，预见表示提前知道将要发生的事，与带伞的行为相合。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：忘记了明天会下雨，就不会带伞，与句中‘所以带了伞’的因果冲突。"}, {"text": "否认", "is_correct": false, "explanation": "语义：否认表示不承认，与句中因为预料到下雨而带伞的做法矛盾。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：‘拒绝’不带‘明天会下雨’这样的小句作宾语。"}], "explanations": {"预见": "正确：「她预见到明天会下雨，所以带了伞」中，预见表示提前知道将要发生的事，与带伞的行为相合。", "忘记": "语义：忘记了明天会下雨，就不会带伞，与句中‘所以带了伞’的因果冲突。", "否认": "语义：否认表示不承认，与句中因为预料到下雨而带伞的做法矛盾。", "拒绝": "配价：‘拒绝’不带‘明天会下雨’这样的小句作宾语。"}, "sentence_index": 0, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上预见了一只猫。", "explanation": "这里应该用〈看见〉。预见指事先知道还没发生的事，不能用来表示眼前见到的具体事物。"}, {"text": "妈妈预见了我的来信。", "explanation": "这里应该用〈收到〉。预见不能表示接到信件；接到东西要说‘收到’。"}, {"text": "他预见了自行车。", "explanation": "这里应该用〈修好〉。修好的是器物，动作是‘修好了自行车’；预见的对象只能是事情，不能是器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26102, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：预见 yùjiàn，指知道还没发生的事情。"}, {"text": "意见", "is_correct": false, "explanation": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。"}, {"text": "续建", "is_correct": false, "explanation": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。"}, {"text": "预检", "is_correct": false, "explanation": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。"}], "explanations": {"预见": "正确：预见 yùjiàn，指知道还没发生的事情。", "意见": "意见 yìjiàn 与 yùjiàn 韵母不同（i / ü），意思是看法。", "续建": "续建 xùjiàn 与 yùjiàn 声母不同（x / 零声母），意思是继续建设。", "预检": "预检 yùjiǎn 与 yùjiàn 声调不同（第三声 / 第四声），意思是事先检查。"}, "sentence_index": null, "correct_answer": "预见"}, "level_3": {"options": [{"text": "预见", "is_correct": true, "explanation": "正确：「你能预见这个游戏的结局吗？」中，预见表示事先知道还没发生的结局，与句意相合。"}, {"text": "报废", "is_correct": false, "explanation": "配价：‘报废’的对象是器物，不能带‘这个游戏的结局’作宾语。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：‘登记’用于人员或事项的备案，不说‘登记结局’。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：‘修理’用于器物，不用于‘结局’。"}], "explanations": {"预见": "正确：「你能预见这个游戏的结局吗？」中，预见表示事先知道还没发生的结局，与句意相合。", "报废": "配价：‘报废’的对象是器物，不能带‘这个游戏的结局’作宾语。", "登记": "搭配：‘登记’用于人员或事项的备案，不说‘登记结局’。", "修理": "搭配：‘修理’用于器物，不用于‘结局’。"}, "sentence_index": 6, "correct_answer": "预见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚预见了妈妈。", "explanation": "这里应该用〈梦见〉。预见是事先料到将来，不指睡着时出现的画面。"}, {"text": "我预见了他的电话号码。", "explanation": "这里应该用〈记住〉。预见指事先知道还没发生的事，不指把已知的内容牢记。"}, {"text": "他认真预见了课文。", "explanation": "这里应该用〈预习〉。预见不指学习课文；上课前学习新内容要说‘预习’。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他预见完了这次考试的难度。", "corrected_sentence": "他预见到了这次考试的难度。", "error_description": "补语错误：‘预见’不接‘完’作结果补语，应说‘预见到’。‘预见完’表示预见的过程结束，与语义不合，正确应为‘预见到了这次考试的难度’。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很预见到结果。", "corrected_sentence": "他能预见到结果。", "error_description": "副词错误：“很”是程度副词，多修饰形容词或状态性词语，不能直接修饰“预见到结果”这一动作；表示能力应用“能”，正确为“他能预见到结果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
