INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26104, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "和整个国家都有关系。", "primary_collocate": null, "pronunciation": "quán guó xìng", "ipa": "tɕʰɥɛn˧˥ kwɔ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这是一件全国性的大事。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国性的节日，大家都放假。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题影响很大，是全国性的。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一个全国性的比赛中得了第一名。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条新闻是全国性的，各地都在报道。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国性的会议每年开一次。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的小事变成了全国性的话题。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸是全国性的，不只是本地人看。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试是全国性的，几百万人参加。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方的小问题，不是全国性的问题。", "target_word": "全国性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "和整个国家都有关系的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f2921a4-34be-472b-b0db-c2ea060409ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全国性", "is_correct": true, "explanation": "正确：全国性指和整个国家都有关系，符合“大事”的语境。"}, {"text": "私人性", "is_correct": false, "explanation": "语义：私人性指只和个人有关，与“大事”及全国范围的意思相反。"}, {"text": "细小性", "is_correct": false, "explanation": "语义：细小性指微不足道，与“大事”相互矛盾。"}, {"text": "家庭性", "is_correct": false, "explanation": "语义：家庭性指只和一个家庭有关，与整个国家无关，不符合句意。"}], "explanations": {"全国性": "正确：全国性指和整个国家都有关系，符合“大事”的语境。", "私人性": "语义：私人性指只和个人有关，与“大事”及全国范围的意思相反。", "细小性": "语义：细小性指微不足道，与“大事”相互矛盾。", "家庭性": "语义：家庭性指只和一个家庭有关，与整个国家无关，不符合句意。"}, "sentence_index": 0, "correct_answer": "全国性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事只和本村有关，是一件全国性的小事。", "explanation": "这里应该用〈地方性〉。全国性指和整个国家都有关系，只和本村有关的事应说地方性。"}, {"text": "这是我们家的全国性问题，只跟我们家有关。", "explanation": "这里应该用〈家事〉。全国性指和整个国家有关，只涉及一家的问题应说家事。"}, {"text": "这位老师的脾气很全国性。", "explanation": "这里应该用〈暴躁〉。全国性指和整个国家有关，不能用来形容人的脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全国性", "is_correct": true, "explanation": "正确：小事变成了和整个国家有关的话题，符合句意。"}, {"text": "私密性", "is_correct": false, "explanation": "语义：私密性指只涉及个人隐私，与“变成了话题”的公开传播相反。"}, {"text": "业余性", "is_correct": false, "explanation": "搭配：业余性多指非专业的活动，不用来修饰“话题”，搭配不当。"}, {"text": "隐秘性", "is_correct": false, "explanation": "语义：隐秘性指不公开，与“变成了话题”的公开讨论相反。"}], "explanations": {"全国性": "正确：小事变成了和整个国家有关的话题，符合句意。", "私密性": "语义：私密性指只涉及个人隐私，与“变成了话题”的公开传播相反。", "业余性": "搭配：业余性多指非专业的活动，不用来修饰“话题”，搭配不当。", "隐秘性": "语义：隐秘性指不公开，与“变成了话题”的公开讨论相反。"}, "sentence_index": 6, "correct_answer": "全国性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个全国性的活动，只在我们楼里进行。", "explanation": "这里应该用〈社区性〉。全国性指和整个国家有关，只在一栋楼里进行的活动应说社区性。"}, {"text": "这是一项全国性的政策，只在一个省实行。", "explanation": "这里应该用〈区域性〉。政策只在一个省实行，说全国性与实际范围矛盾。"}, {"text": "我们这个社团很全国性，只有三个人。", "explanation": "这里应该用〈小型〉。全国性指和整个国家有关，只有三个人的社团不能说全国性，应说小型。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项政策是全国性地，各地都要执行。", "corrected_sentence": "这项政策是全国性的，各地都要执行。", "error_description": "结构助词误用：「全国性」作谓语时应用「的」，「地」只用于修饰动词，此处应为「是全国性的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司是全国性了的，分店开遍各地。", "corrected_sentence": "这家公司是全国性的，分店开遍各地。", "error_description": "“全国性”后面的“的”前不能插“了”。误加“了”，应为“全国性的，分店开遍各地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bdfdeb5f-c35b-4ad5-8aa7-518c6db8a774') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "与“透明”互为反义，指光线不能穿过、看不清后面。"}, {"text": "厚重", "is_correct": false, "explanation": "无关：“厚重”形容分量或厚度，与“透明”不构成反义。"}, {"text": "香甜", "is_correct": false, "explanation": "无关：“香甜”形容味道，与“透明”不构成反义。"}, {"text": "滚烫", "is_correct": false, "explanation": "无关：“滚烫”形容温度，与“透明”不构成反义。"}], "correct_answer": "不透明", "explanations": {"不透明": "与“透明”互为反义，指光线不能穿过、看不清后面。", "厚重": "无关：“厚重”形容分量或厚度，与“透明”不构成反义。", "香甜": "无关：“香甜”形容味道，与“透明”不构成反义。", "滚烫": "无关：“滚烫”形容温度，与“透明”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不透明", "is_correct": true, "explanation": "与“透明”互为反义，指光线不能穿过。"}, {"text": "冰凉", "is_correct": false, "explanation": "无关：“冰凉”形容温度感受，与“透明”不构成反义。"}, {"text": "宽阔", "is_correct": false, "explanation": "无关：“宽阔”形容面积或空间，与“透明”不构成反义。"}, {"text": "柔和", "is_correct": false, "explanation": "无关：“柔和”形容光线或语气的温和，与“透明”不构成反义。"}], "correct_answer": "不透明", "explanations": {"不透明": "与“透明”互为反义，指光线不能穿过。", "冰凉": "无关：“冰凉”形容温度感受，与“透明”不构成反义。", "宽阔": "无关：“宽阔”形容面积或空间，与“透明”不构成反义。", "柔和": "无关：“柔和”形容光线或语气的温和，与“透明”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能看到后面的东西，比如玻璃。", "primary_collocate": null, "pronunciation": "tòu míng", "ipa": "tʰou̯˥˩ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "玻璃是透明的。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透明的杯子里有牛奶。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子是透明的，我看得见里面。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户的玻璃很透明。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着透明的雨衣出门了。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水是透明的，没有颜色。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个透明的书包。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "透明的门后面是一间小店。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块塑料很透明，像玻璃一样。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块冰很透明，里面的花看得清楚。", "target_word": "透明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "半透明", "label": "复合"}, {"form": "透明度", "label": "复合"}], "register": "中性", "sense_fingerprint": "通俗说法：像玻璃一样能看到后面的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95bb63fc-9d85-45b8-839d-46c1b0107726') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "玻璃能让光线穿过、看见后面的东西，这里只能用“透明”。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：玻璃质地硬，不说“柔软”。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来描述玻璃的性质。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：玻璃不具有“温暖”的属性，与其物理性质不符。"}], "explanations": {"透明": "玻璃能让光线穿过、看见后面的东西，这里只能用“透明”。", "柔软": "语义：玻璃质地硬，不说“柔软”。", "清脆": "搭配：“清脆”形容声音，不用来描述玻璃的性质。", "温暖": "语义：玻璃不具有“温暖”的属性，与其物理性质不符。"}, "sentence_index": 0, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张图片很透明。", "explanation": "这里应该用〈清晰〉。“清晰”说图像看得清，“透明”说物体能让光穿过，不用来形容图片。"}, {"text": "这块饼干很透明。", "explanation": "这里应该用〈清脆〉。“清脆”形容饼干咬起来的声音和口感，“透明”不用来形容饼干。"}, {"text": "他的脚步很透明。", "explanation": "这里应该用〈轻盈〉。“轻盈”形容脚步轻快，“透明”说物体能让光穿过，不用来形容脚步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透明", "is_correct": true, "explanation": "“透明”指书包的材质能让人看见里面，与句意相合。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容书包。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：书包没有情绪，不能说“高兴”。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”形容味道，不用来形容书包。"}], "explanations": {"透明": "“透明”指书包的材质能让人看见里面，与句意相合。", "清脆": "搭配：“清脆”形容声音，不用来形容书包。", "高兴": "语义：书包没有情绪，不能说“高兴”。", "香甜": "搭配：“香甜”形容味道，不用来形容书包。"}, "sentence_index": 6, "correct_answer": "透明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光很透明。", "explanation": "这里应该用〈耀眼〉。“耀眼”形容光线强烈刺目，“透明”形容物体，不用来形容光线本身。"}, {"text": "夜空里的星星很透明。", "explanation": "这里应该用〈闪亮〉。“闪亮”说光的闪耀，“透明”说物体能让光穿过，不用来形容星星。"}, {"text": "鸟叫声很透明。", "explanation": "这里应该用〈清脆〉。“清脆”形容声音，“透明”不用来形容鸟叫声。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个玻璃杯是透明。", "corrected_sentence": "这个玻璃杯是透明的。", "error_description": "漏掉“的”：“是”字句中形容词作谓语时通常要带“的”，应说“是透明的”，不说“是透明”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这扇窗很很透明。", "corrected_sentence": "这扇窗很透明。", "error_description": "重复错误：程度副词“很”只用一个，应说“这扇窗很透明”，不能说“很很透明”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df5ce1e7-06a4-48ac-8785-f5064a80c657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
