INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个东西能做好它的工作。", "primary_collocate": null, "pronunciation": "yǒu xiào xìng", "ipa": "joʊ˨˩˦ ɕjaʊ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种药的有效性很高，吃了就不疼了。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么知道这个方法的有效性？", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把锁的有效性怎么样？", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个口罩的有效性已经测过了。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先试用一下，再判断它的有效性。", "target_word": "有效性", "complexity_tier": "T3", "furigana": "wǒ men xiān shì yòng yí xià，zài pàn duàn tā de yǒu xiào xìng。", "sentence_source": "generated"}, {"text": "洗手的有效性很高，可以少生病。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件的有效性让大家很满意。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灭火器的有效性每年都要检查。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种闹钟的有效性不高，我还是迟到了。", "target_word": "有效性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，判断学习方法好不好，要看它的有效性。", "target_word": "有效性", "complexity_tier": "T3", "furigana": "lǎo shī shuō， pàn duàn xué xí fāng fǎ hǎo bu hǎo， yào kàn tā de yǒu xiào xìng。", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一个东西能做好它的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有效性", "is_correct": true, "explanation": "正确。“这种药的有效性很高”说明药能做好它的工作，与“吃了就不疼了”的语境一致。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“药的体温很高”不成立，体温描述的是人的身体状况，不能说明药的工作效果。"}, {"text": "字数", "is_correct": false, "explanation": "语义：“字数”是文字的数量，与药能否起效无关。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“座位很高”不是常见搭配，“座位”不用来说明药的效果。"}], "explanations": {"有效性": "正确。“这种药的有效性很高”说明药能做好它的工作，与“吃了就不疼了”的语境一致。", "体温": "语义：“药的体温很高”不成立，体温描述的是人的身体状况，不能说明药的工作效果。", "字数": "语义：“字数”是文字的数量，与药能否起效无关。", "座位": "搭配：“座位很高”不是常见搭配，“座位”不用来说明药的效果。"}, "sentence_index": 0, "correct_answer": "有效性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块电池的有效性很长。", "explanation": "这里应该用〈寿命〉。有效性说明能否做好工作，不用“长”来形容，“长”用于寿命、时间。"}, {"text": "这把椅子的有效性很漂亮。", "explanation": "这里误用了〈外观〉的意思。有效性指做事的效果，不能用来形容外观；“漂亮”说的是外形或颜色。"}, {"text": "这首歌的有效性很好听。", "explanation": "这里误用了〈声音〉的意思。有效性指做事的效果，不能用“好听”来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有效性", "is_correct": true, "explanation": "正确。“软件的有效性”指软件能做好其工作的程度，与“让大家很满意”的语境一致。"}, {"text": "体重", "is_correct": false, "explanation": "语义：软件没有“体重”，句子不通。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：软件没有“年纪”，“年纪让大家满意”不成立。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：“软件的嗓门”不是常见搭配，“嗓门”只用于人或能发声的事物。"}], "explanations": {"有效性": "正确。“软件的有效性”指软件能做好其工作的程度，与“让大家很满意”的语境一致。", "体重": "语义：软件没有“体重”，句子不通。", "年纪": "语义：软件没有“年纪”，“年纪让大家满意”不成立。", "嗓门": "搭配：“软件的嗓门”不是常见搭配，“嗓门”只用于人或能发声的事物。"}, "sentence_index": 6, "correct_answer": "有效性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的有效性很好。", "explanation": "这里应该用〈味道〉。有效性不用来评价口感，“好”用于味道等可感知的品质。"}, {"text": "这台电脑的有效性很快。", "explanation": "这里应该用〈速度〉。有效性不用“快”来形容，“快”只用于速度。"}, {"text": "这个箱子的有效性很重，我拿不动。", "explanation": "这里误用了〈重量〉的意思。有效性指做事的效果，不能用“重”来形容，“重”说的是物体的重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该把这个口罩的有效性测。", "corrected_sentence": "我们应该把这个口罩的有效性测一下。", "error_description": "错误形式：“把……测”后缺少补语；正确形式：“把……测一下”。“把”字句的动词后要带补语，“测一下”表示简单尝试。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师说，这种方法的有效性的很重要。", "corrected_sentence": "老师说，这种方法的有效性很重要。", "error_description": "错误形式：“有效性的很重要”，其中“的”多余；正确形式：“有效性很重要”。“的”用于修饰名词，“很重要”是谓语，前面不能再加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
