INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26110, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让机器自己控制自己，不用人一直帮忙。", "primary_collocate": null, "pronunciation": "bì huán kòng zhì", "ipa": "pi⁵¹ xwan³⁵ kʰʊŋ⁵¹ ʈʂʐ̩⁵¹", "syllable_count": 4, "sentences": [{"text": "这台洗衣机用闭环控制，不用人一直看。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制让机器自己调整速度。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了闭环控制，热水器能自己保持水温。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，闭环控制就是机器自己管自己。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人靠闭环控制走路，不会摔倒。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制让工人不用一直站在机器旁边。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的扫地机器人用了闭环控制。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用闭环控制的话，机器自己就能停下来。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "闭环控制可以让机器自己发现问题。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在做一个有闭环控制的小风扇。", "target_word": "闭环控制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "闭环控制系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "机器自己管自己，不用人一直帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f156e2d9-fcb3-4ae1-8a57-d0d3cafb582f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26110, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。“用闭环控制”说明洗衣机靠自身调节工作，与“不用人一直看”相符。"}, {"text": "人工控制", "is_correct": false, "explanation": "语义：“人工控制”需要人一直操作，与“不用人一直看”的意思相反。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：洗衣机不会“用”拖鞋工作，句子说不通。"}, {"text": "说明书", "is_correct": false, "explanation": "语义：说明书是说明文件，不是控制手段，句子说不通。"}], "explanations": {"闭环控制": "正确。“用闭环控制”说明洗衣机靠自身调节工作，与“不用人一直看”相符。", "人工控制": "语义：“人工控制”需要人一直操作，与“不用人一直看”的意思相反。", "拖鞋": "语义：洗衣机不会“用”拖鞋工作，句子说不通。", "说明书": "语义：说明书是说明文件，不是控制手段，句子说不通。"}, "sentence_index": 0, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸用闭环控制换台，不用起身。", "explanation": "这里应该用〈遥控器〉。闭环控制指机器自己调节工作，不是人手里用来操作的器具。"}, {"text": "火灾时闭环控制会响，提醒大家离开。", "explanation": "这里应该用〈警报器〉。闭环控制是控制方式，不会发出声音提醒人。"}, {"text": "闭环控制显示水温是四十度。", "explanation": "这里应该用〈温度计〉。闭环控制不显示数值，不能用来测量水温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "闭环控制", "is_correct": true, "explanation": "正确。扫地机器人靠闭环控制自动调节工作，“用了闭环控制”符合句意。"}, {"text": "扫帚", "is_correct": false, "explanation": "语义：扫帚需要人手动操作，与扫地机器人自动清扫的功能不符。"}, {"text": "电饭煲", "is_correct": false, "explanation": "语义：扫地机器人不会“用”电饭煲，句子说不通。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是照明用品，与扫地机器人的工作无关，句子说不通。"}], "explanations": {"闭环控制": "正确。扫地机器人靠闭环控制自动调节工作，“用了闭环控制”符合句意。", "扫帚": "语义：扫帚需要人手动操作，与扫地机器人自动清扫的功能不符。", "电饭煲": "语义：扫地机器人不会“用”电饭煲，句子说不通。", "蜡烛": "语义：蜡烛是照明用品，与扫地机器人的工作无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "闭环控制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师设计了一只闭环控制，让小风扇自己调速。", "explanation": "这里应该用〈种〉。闭环控制是抽象的控制方式，〈只〉多用于动物，不能用于它。"}, {"text": "工程师设计了一把闭环控制，让小风扇自己调速。", "explanation": "这里应该用〈种〉。〈把〉多用于有柄的器具，闭环控制不是器具，不能用〈把〉计量。"}, {"text": "工程师设计了一台闭环控制，让小风扇自己调速。", "explanation": "这里应该用〈种〉。〈台〉用于机器设备，闭环控制是控制方法，不是设备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电饭煲把闭环控制来煮饭。", "corrected_sentence": "这台电饭煲用闭环控制来煮饭。", "error_description": "错误形式：“把闭环控制来煮饭”用“把”引出对象，但后面没有合适的动词结构；正确形式：“用闭环控制来煮饭”。“闭环控制”作为工具，应用“用”引出，“把”字句不能这样用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台空气净化器用一台闭环控制来调节风速。", "corrected_sentence": "这台空气净化器用一种闭环控制来调节风速。", "error_description": "量词错了。“闭环控制”是抽象的控制方式，应该用量词“种”，不能用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ac502d5-ced7-45c0-a359-11a82e46cae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
