INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种生活在水里的动物，可以游来游去。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "水里有一条鱼，正在游来游去。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩蹲在水边，看着鱼游来游去。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的缸里养着三条鱼，都很小。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼在水里游，鸟在天上飞。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把鱼放进了水里，鱼很快游走了。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的鱼看见我，一下子都游走了。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只猫一直看着水里的鱼。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池子里的鱼有红的，也有黑的。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼不能离开水，不然会死。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在河边看到过一条很大的鱼。", "target_word": "鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "金鱼", "label": "复合"}, {"form": "鱼肉", "label": "复合"}, {"form": "魚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鱼：生活在水里、会游来游去的动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水里、会游来游去的动物。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。"}, {"text": "育", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是培育。"}, {"text": "无", "is_correct": false, "explanation": "wú 与 yú 声母不同（w 与 y），意思是没有。"}, {"text": "如", "is_correct": false, "explanation": "rú 与 yú 声母不同（r 与 y），意思是像、如同。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 yú 声母不同（l 与 y），意思是炉子。"}, {"text": "局", "is_correct": false, "explanation": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}], "explanations": {"鱼": "正确。鱼：生活在水里、会游来游去的动物。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。", "育": "yù（第四声）与 yú（第二声）声调不同，意思是培育。", "无": "wú 与 yú 声母不同（w 与 y），意思是没有。", "如": "rú 与 yú 声母不同（r 与 y），意思是像、如同。", "炉": "lú 与 yú 声母不同（l 与 y），意思是炉子。", "局": "jú 与 yú 声母不同（j 与 y），意思是局面、机构。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河是地理上的水道，不会游来游去。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线没有生命，不会在水里游来游去。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。鱼生活在水里，会游来游去。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子没有生命，也不会游动。"}], "explanations": {"河": "语义：河是地理上的水道，不会游来游去。", "电线": "语义：电线没有生命，不会在水里游来游去。", "鱼": "正确。鱼生活在水里，会游来游去。", "绳子": "语义：绳子没有生命，也不会游动。"}, "sentence_index": 0, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作业写完了，我还有一点鱼时间。", "explanation": "这里应该用〈余〉。余表示“剩下”，与鱼同音但意思不同，应说“余时间”。"}, {"text": "这艘鱼船在海上开了一整天。", "explanation": "这里应该用〈渔船〉。捕鱼的船叫渔船，鱼指水里的动物，不能修饰船。"}, {"text": "他的爷爷一辈子都是鱼，常在海上过日子。", "explanation": "这里应该用〈渔夫〉。鱼指动物，以捕鱼为业的人叫渔夫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730')