INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26130, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "鱼", "is_correct": true, "explanation": "正确。鱼：生活在水里、会游来游去的动物。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。"}, {"text": "预", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。"}, {"text": "浴", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。"}, {"text": "芋", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。"}, {"text": "读", "is_correct": false, "explanation": "dú 与 yú 声母不同（d 与 y），意思是阅读。"}], "explanations": {"鱼": "正确。鱼：生活在水里、会游来游去的动物。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。", "预": "yù（第四声）与 yú（第二声）声调不同，意思是预先、事先。", "浴": "yù（第四声）与 yú（第二声）声调不同，意思是洗澡。", "芋": "yù（第四声）与 yú（第二声）声调不同，意思是芋头。", "读": "dú 与 yú 声母不同（d 与 y），意思是阅读。"}, "sentence_index": null, "correct_answer": "鱼"}, "level_3": {"options": [{"text": "电视", "is_correct": false, "explanation": "语义：电视是家用电器，不会在水里。"}, {"text": "鱼", "is_correct": true, "explanation": "正确。水里的鱼是猫看的对象。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，“水里的”不能修饰它。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“看着水里的……”指水中可见的东西，桌子不与之搭配。"}], "explanations": {"电视": "语义：电视是家用电器，不会在水里。", "鱼": "正确。水里的鱼是猫看的对象。", "冰箱": "语义：冰箱是家电，“水里的”不能修饰它。", "桌子": "搭配：“看着水里的……”指水中可见的东西，桌子不与之搭配。"}, "sentence_index": 6, "correct_answer": "鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在河边看到过一张鱼，它在水里游。", "explanation": "这里应该用〈条〉。“张”用于纸、桌子等平面的东西，鱼用“条”计量。"}, {"text": "池子里有一座鱼，正在游来游去。", "explanation": "这里应该用〈条〉。“座”用于山、房子等，不用于鱼。"}, {"text": "我家养了一面鱼，很可爱。", "explanation": "这里应该用〈条〉。“面”用于镜子、旗子等平面的东西，不用于鱼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
