INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "买点就是人们想买一个东西的原因。", "primary_collocate": null, "pronunciation": "mǎi diǎn", "ipa": "mai˨˩˦ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "对我来说，价钱低是买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你买这双鞋的买点是什么？", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢这个玩具，颜色就是买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个冰箱的买点是很安静，一点声音也没有。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈告诉我，买点就是想买的原因。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的买点都不一样。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人来说，安全是买点。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的买点是离家近，什么都有。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说买这本书的买点是作者有名。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找到买点以后，我就决定买了。", "target_word": "买点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "買點", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买点：人们想买某个东西的原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“是颜色”说不通，“颜色”不能作为“价钱低”这类评价的内容。"}, {"text": "买点", "is_correct": true, "explanation": "正确。买点指人们想买某个东西的原因，这里说价钱低是买的原因。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”与“价钱低”不相关，“是年龄”不通。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“价钱低”是对商品的评价，地址不与之搭配。"}], "explanations": {"颜色": "语义：“是颜色”说不通，“颜色”不能作为“价钱低”这类评价的内容。", "买点": "正确。买点指人们想买某个东西的原因，这里说价钱低是买的原因。", "年龄": "语义：“年龄”与“价钱低”不相关，“是年龄”不通。", "地址": "搭配：“价钱低”是对商品的评价，地址不与之搭配。"}, "sentence_index": 0, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个冰箱的买点是噪音很大，晚上吵得人睡不着。", "explanation": "这里应该用〈缺点〉。买点是人们想买的原因，“噪音很大”是缺点，不能叫买点。"}, {"text": "这个冰箱有三场买点，很多人都很喜欢。", "explanation": "这里应该用〈个〉。“场”用于比赛、演出等，买点用“个”计量。"}, {"text": "这个冰箱有两朵买点，颜色很好看。", "explanation": "这里应该用〈个〉。“朵”用于花、云等，不用于买点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：“安全是声音”说不通，声音不能作为安全这类评价的内容。"}, {"text": "买点", "is_correct": true, "explanation": "正确。对老人来说，安全是他们想买这个东西的原因。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”与“安全”不是同类的评价，句子不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不与“安全”搭配，句意不通。"}], "explanations": {"声音": "语义：“安全是声音”说不通，声音不能作为安全这类评价的内容。", "买点": "正确。对老人来说，安全是他们想买这个东西的原因。", "重量": "语义：“重量”与“安全”不是同类的评价，句子不通。", "味道": "搭配：“味道”不与“安全”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "买点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了一个买点迟到，老师没有批评他。", "explanation": "这里应该用〈理由〉。买点专指人们想买某个东西的原因，不能用来说迟到的借口。"}, {"text": "这台电脑有一张买点，速度很快。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面的东西，不用于买点。"}, {"text": "这种酒有三瓶买点。", "explanation": "这里应该用〈个〉。“瓶”用于装在瓶中的东西，不用于买点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个水壶买点是不容易凉。", "corrected_sentence": "这个水壶的买点是不容易凉。", "error_description": "结构助词错误：定语“这个水壶”与中心语“买点”之间要用“的”，应说“水壶的买点”，不能省去“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个电饭锅的买点叫煮饭快，而且省电。", "corrected_sentence": "这个电饭锅的买点是煮饭快，而且省电。", "error_description": "动词错误：“买点”后面要用“是”引出内容，“叫”不能这样用，应说“买点是煮饭快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一直做，没有停下。", "primary_collocate": null, "pronunciation": "bù tíng", "ipa": "pu˧˥ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我们一路上说个不停，一点也不累。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不停地问问题，妈妈很有耐心。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不停地跑，一直跑到学校门口。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天她忙个不停，连饭也顾不上吃。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车不停地向前开，窗外的树一棵棵往后走。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着电视，手不停地换台。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在房间里跳个不停，楼下的人都听见了。", "target_word": "不停", "complexity_tier": "T3", "furigana": "dì di zài fáng jiān lǐ tiào ge bù tíng, lóu xià de rén dōu tīng jiàn le.", "sentence_source": "generated"}, {"text": "小鸟在树上不停地叫，吵得我睡不着。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水不停地流，从来没有停下过。", "target_word": "不停", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不停地看表，好像在等什么人。", "target_word": "不停", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不停地", "label": "状语形式"}], "register": "通用", "sense_fingerprint": "副词，一直做某事而不停下来，可放在动词前或“V个不停”中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停（bù tíng）是副词，表示一直做，没有停下。"}, {"text": "不听", "is_correct": false, "explanation": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。"}, {"text": "不疼", "is_correct": false, "explanation": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。"}, {"text": "不提", "is_correct": false, "explanation": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}], "explanations": {"不停": "不停（bù tíng）是副词，表示一直做，没有停下。", "不听": "不听（bù tīng）与不停（bù tíng）的第二个音节声调不同：tīng 为第一声，tíng 为第二声。意思是不听。", "不疼": "不疼（bù téng）与不停（bù tíng）的韵母不同：-eng 与 -ing。意思是不疼。", "不提": "不提（bù tí）比不停（bù tíng）少了韵尾 -ng。意思是不提起。"}, "sentence_index": null, "correct_answer": "不停"}, "level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：“说个不停”表示说话持续不断，与“一路上”的闲聊相符。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“说个笑话”指讲一则笑话，只能说一次，与“一路上”持续不断的闲聊不符。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”是形容词，不能接在“说个”后表示程度，应说“说清楚”。"}, {"text": "齐全", "is_correct": false, "explanation": "搭配：“齐全”形容东西完备，不能接在“说个”后面，这个搭配不成立。"}], "explanations": {"不停": "不停：“说个不停”表示说话持续不断，与“一路上”的闲聊相符。", "笑话": "语义：“说个笑话”指讲一则笑话，只能说一次，与“一路上”持续不断的闲聊不符。", "清楚": "搭配：“清楚”是形容词，不能接在“说个”后表示程度，应说“说清楚”。", "齐全": "搭配：“齐全”形容东西完备，不能接在“说个”后面，这个搭配不成立。"}, "sentence_index": 0, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的答案不停地是三。", "explanation": "这里误用了“不停”。“不停地”描述动作或变化持续进行，而这里说的是固定不变的判断，不会持续发生，因此不能用“不停地”修饰。"}, {"text": "他不停地道了一次歉，之后就离开了。", "explanation": "“不停”表示动作接连不断地进行，而“道歉一次”只发生一次，二者矛盾，这里不能用“不停”修饰。"}, {"text": "屋里很安静，她不停地睡着了。", "explanation": "“睡着”是瞬间发生的结果，不是可以持续不停进行的动作，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不停", "is_correct": true, "explanation": "不停：“跳个不停”表示跳的动作持续不断，与“楼下的人都听见了”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”指没有声音，与“跳”的动作和“楼下的人都听见了”矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或动作一致，不能用来描述“跳”的程度，“跳个整齐”不成立。"}, {"text": "舒服", "is_correct": false, "explanation": "搭配：“舒服”是人的感受，不能接在“跳个”后面描述动作的程度。"}], "explanations": {"不停": "不停：“跳个不停”表示跳的动作持续不断，与“楼下的人都听见了”相符。", "安静": "语义：“安静”指没有声音，与“跳”的动作和“楼下的人都听见了”矛盾。", "整齐": "搭配：“整齐”形容排列或动作一致，不能用来描述“跳”的程度，“跳个整齐”不成立。", "舒服": "搭配：“舒服”是人的感受，不能接在“跳个”后面描述动作的程度。"}, "sentence_index": 6, "correct_answer": "不停"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板一接到电话，不停地站了起来，走出了办公室。", "explanation": "这里应该用〈立刻〉。“立刻”表示接到电话后马上做出的一次反应，“不停”强调持续不断，用在这里语义不通。"}, {"text": "老板不停地停下了笔，抬头看了我一眼。", "explanation": "这里的“不停”表示一直持续，却修饰了表示中断、停止的动作，语义相互抵触。"}, {"text": "老板不停地收到了一份合同。", "explanation": "“收到合同”是一次性的结果，不能持续不停地发生，不能用“不停”修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹不停得翻书，想找到那张照片。", "corrected_sentence": "妹妹不停地翻书，想找到那张照片。", "error_description": "“不停地”中的“地”写成了“得”。作状语修饰动词时应用“地”；“得”用于动词或形容词之后引出补语，这里不能用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟玩的不停，忘了写作业。", "corrected_sentence": "弟弟玩个不停，忘了写作业。", "error_description": "“个不停”是固定格式，中间的“个”不能换成“的”。应说“玩个不停”，不能说“玩的不停”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
