INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "帮就是帮助别人。", "primary_collocate": null, "pronunciation": "bāng", "ipa": "paŋ˥", "syllable_count": 1, "sentences": [{"text": "请你帮我拿一下这个包。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈在做饭，我去帮她。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常常帮同学补习数学。", "target_word": "帮", "complexity_tier": "T3", "furigana": "tā chángcháng bāng tóngxué bǔxí shùxué", "sentence_source": "generated"}, {"text": "你能帮我看看这个字怎么读吗？", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑坏了，朋友帮我修好了。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，邻居帮我把衣服收进来。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你帮了我这么多。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮我改了作业里的错字。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮我找到了手机。", "target_word": "帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明帮奶奶提着很重的菜。", "target_word": "帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "帮了", "label": "体标（了）"}, {"form": "帮过", "label": "体标（过）"}, {"form": "帮帮", "label": "重叠"}, {"form": "帮助", "label": "复合"}], "register": "中性", "sense_fingerprint": "给别人出力、提供帮助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be7eb40f-7d8a-4232-9c49-ff679e0a5a7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "帮", "is_correct": true, "explanation": "正确答案，指给别人出力、提供帮助。"}, {"text": "棒", "is_correct": false, "explanation": "声调不同（bàng 第四声，bāng 第一声），意思是好、厉害。"}, {"text": "搬", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是搬运。"}, {"text": "方", "is_correct": false, "explanation": "声母不同（f 与 b），意思是方向、方形。"}, {"text": "班", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是班级。"}], "explanations": {"帮": "正确答案，指给别人出力、提供帮助。", "棒": "声调不同（bàng 第四声，bāng 第一声），意思是好、厉害。", "搬": "韵母不同（ān 与 āng），意思是搬运。", "方": "声母不同（f 与 b），意思是方向、方形。", "班": "韵母不同（ān 与 āng），意思是班级。"}, "sentence_index": null, "correct_answer": "帮"}, "level_3": {"options": [{"text": "告诉", "is_correct": false, "explanation": "配价：“告诉”后面要接说话的内容，不能直接接“拿一下这个包”。"}, {"text": "帮", "is_correct": true, "explanation": "帮表示给予协助，符合请求别人帮忙拿东西的语境。"}, {"text": "打扰", "is_correct": false, "explanation": "语义：“打扰”表示妨碍别人，与请求帮忙的语境相反。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与请求帮忙的语境不合。"}], "explanations": {"告诉": "配价：“告诉”后面要接说话的内容，不能直接接“拿一下这个包”。", "帮": "帮表示给予协助，符合请求别人帮忙拿东西的语境。", "打扰": "语义：“打扰”表示妨碍别人，与请求帮忙的语境相反。", "批评": "语义：“批评”是指出错误，与请求帮忙的语境不合。"}, "sentence_index": 0, "correct_answer": "帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮我生了一场病。", "explanation": "这里应该用〈传染〉。生病是身体的状况，不能替别人生；病从他人身上传来要说〈传染〉，「帮」只表示协助出力。"}, {"text": "妈妈帮孩子吓了一跳。", "explanation": "这里应该用〈吓〉。使人受惊要用〈吓〉，「帮」表示给予协助，不能说“帮孩子吓了一跳”。"}, {"text": "他帮我丢了钥匙。", "explanation": "这里应该用〈害〉。「帮」表示给予协助，造成损失要用〈害〉，如「他害我丢了钥匙」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "帮", "is_correct": true, "explanation": "正确答案，指给别人出力、提供帮助。"}, {"text": "包", "is_correct": false, "explanation": "韵母不同（āo 与 āng），意思是包裹。"}, {"text": "斑", "is_correct": false, "explanation": "韵母不同（ān 与 āng），意思是斑点。"}, {"text": "刚", "is_correct": false, "explanation": "声母不同（g 与 b），意思是刚刚。"}, {"text": "绑", "is_correct": false, "explanation": "声调不同（bǎng 第三声，bāng 第一声），意思是捆绑。"}], "explanations": {"帮": "正确答案，指给别人出力、提供帮助。", "包": "韵母不同（āo 与 āng），意思是包裹。", "斑": "韵母不同（ān 与 āng），意思是斑点。", "刚": "声母不同（g 与 b），意思是刚刚。", "绑": "声调不同（bǎng 第三声，bāng 第一声），意思是捆绑。"}, "sentence_index": null, "correct_answer": "帮"}, "level_3": {"options": [{"text": "忘", "is_correct": false, "explanation": "语义：“忘”表示记不住，与感谢对方的语境相矛盾。"}, {"text": "帮", "is_correct": true, "explanation": "帮表示给予帮助，与“谢谢你……了我这么多”的语境相符。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“躲”表示避开，与感谢对方的语境不合。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”不能带“我”作宾语来表示给予帮助。"}], "explanations": {"忘": "语义：“忘”表示记不住，与感谢对方的语境相矛盾。", "帮": "帮表示给予帮助，与“谢谢你……了我这么多”的语境相符。", "躲": "语义：“躲”表示避开，与感谢对方的语境不合。", "坐": "配价：“坐”不能带“我”作宾语来表示给予帮助。"}, "sentence_index": 6, "correct_answer": "帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮我笑了一下。", "explanation": "这里应该用〈逗〉。使人发笑要用〈逗〉，「帮」是给予协助，不能让人笑。"}, {"text": "他帮我哭了一场。", "explanation": "这里应该用〈陪〉。陪别人一起哭要用〈陪〉，「帮」是出力协助，不能替人哭。"}, {"text": "妈妈帮我生气了。", "explanation": "这里应该用〈惹〉。使人生气要用〈惹〉，「帮」表示给予协助，不能说“帮我生气”，如“妈妈惹我生气了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他帮我了很多忙。", "corrected_sentence": "他帮了我很多忙。", "error_description": "错误：动态助词“了”放在了宾语“我”之后。正确：“帮了我很多忙”，“了”紧跟动词“帮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他常常帮别人忙。", "corrected_sentence": "他常常帮别人的忙。", "error_description": "离合错误：“帮忙”是离合词，宾语“别人”后要加“的”，漏掉“的”不能说。正确：“帮别人的忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'faf0706e-482b-4441-b6f8-5440a3433bf6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
