INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用水把衣服上的脏东西去掉。", "primary_collocate": null, "pronunciation": "xǐ yī fu", "ipa": "ɕi˨˩ i˥ fu", "syllable_count": 3, "sentences": [{"text": "衣服太脏了，我要用水洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子玩得满身是泥，妈妈忙着洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸下班回家，先洗衣服再做饭。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服上有汗味，我今天一定要洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她蹲在河边洗衣服，水很清。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宿舍里有洗衣机，同学们都不用手洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶习惯用手洗衣服，说这样洗得干净。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天忙了一天，晚上才有时间洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚来中国，还不会洗衣服。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣服前，先把口袋里的东西拿出来。", "target_word": "洗衣服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "洗洗衣服", "label": "重叠"}, {"form": "洗过衣服", "label": "体标"}], "register": "中性", "sense_fingerprint": "用水去掉衣服上的脏东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c55708a7-2145-4fac-8727-49a1b4830a21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：用水去掉衣服上的脏东西，与“衣服太脏了”的句意相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡的对象是人，句子讲的是衣服脏，句意不通。"}, {"text": "晾衣服", "is_correct": false, "explanation": "搭配：晾衣服不用水去掉脏东西，与“用水”不搭配。"}, {"text": "烫衣服", "is_correct": false, "explanation": "搭配：烫衣服要用熨斗，不能去掉脏东西，与“用水”不搭配。"}], "explanations": {"洗衣服": "洗衣服：用水去掉衣服上的脏东西，与“衣服太脏了”的句意相符。", "洗澡": "语义：洗澡的对象是人，句子讲的是衣服脏，句意不通。", "晾衣服": "搭配：晾衣服不用水去掉脏东西，与“用水”不搭配。", "烫衣服": "搭配：烫衣服要用熨斗，不能去掉脏东西，与“用水”不搭配。"}, "sentence_index": 0, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把碗放进水池，开始洗衣服。", "explanation": "这里应该用〈洗碗〉。洗衣服是去掉衣物上的脏东西，碗要用洗碗。"}, {"text": "妈妈拿起拖把，开始洗衣服。", "explanation": "这里应该用〈拖地〉。拖把用于拖地，洗衣服针对衣物。"}, {"text": "他把黑板擦拿进教室，开始洗衣服。", "explanation": "这里应该用〈擦黑板〉。黑板擦用于擦黑板，洗衣服针对衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洗衣服", "is_correct": true, "explanation": "洗衣服：用水去掉衣服上的脏东西，与“用手”“洗得干净”的句意相符。"}, {"text": "晒衣服", "is_correct": false, "explanation": "语义：晒衣服不能把衣服洗干净，“晒得干净”句意不通。"}, {"text": "熨衣服", "is_correct": false, "explanation": "搭配：熨衣服要用熨斗，不能用手去掉脏东西。"}, {"text": "喝水", "is_correct": false, "explanation": "语义：喝水与洗衣服无关，“用手喝水”说明洗得干净，句意不通。"}], "explanations": {"洗衣服": "洗衣服：用水去掉衣服上的脏东西，与“用手”“洗得干净”的句意相符。", "晒衣服": "语义：晒衣服不能把衣服洗干净，“晒得干净”句意不通。", "熨衣服": "搭配：熨衣服要用熨斗，不能用手去掉脏东西。", "喝水": "语义：喝水与洗衣服无关，“用手喝水”说明洗得干净，句意不通。"}, "sentence_index": 6, "correct_answer": "洗衣服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把青菜放进水池，开始洗衣服。", "explanation": "这里应该用〈洗菜〉。洗衣服针对衣物，青菜要用洗菜。"}, {"text": "他拿起菜刀，开始洗衣服。", "explanation": "这里应该用〈切菜〉。菜刀用于切菜，洗衣服不用刀。"}, {"text": "他把鞋子放进盆里，开始洗衣服。", "explanation": "这里应该用〈洗鞋〉。洗衣服针对衣物，鞋子要用洗鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午有空，就去洗衣服地方。", "corrected_sentence": "我下午有空，就去洗衣服的地方。", "error_description": "错误：“洗衣服地方”，应为“洗衣服的地方”。动词短语修饰名词时，中间要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥昨天洗衣服洗地很干净。", "corrected_sentence": "哥哥昨天洗衣服洗得很干净。", "error_description": "错误：“洗地”，应为“洗得”。动词后面引出补语要用“得”，“地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca7289fe-4294-4d82-bac5-cce18b000cb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用东西。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱取得物品，与“少用东西”的意思不构成反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "增加：指数量变多，与“省”的少用义没有反义关系。"}, {"text": "制造", "is_correct": false, "explanation": "制造：指做出物品，与“省”的意思没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用东西。", "购买": "购买：指花钱取得物品，与“少用东西”的意思不构成反义关系。", "增加": "增加：指数量变多，与“省”的少用义没有反义关系。", "制造": "制造：指做出物品，与“省”的意思没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "浪费：与“省”互为反义，指不节约、随意耗用东西。"}, {"text": "赚取", "is_correct": false, "explanation": "赚取：指获得钱财，与“少用东西”的意思没有反义关系。"}, {"text": "生产", "is_correct": false, "explanation": "生产：指制造物品，与“省”的少用义没有反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "扩大：指范围或规模变大，与“省”的意思没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "浪费：与“省”互为反义，指不节约、随意耗用东西。", "赚取": "赚取：指获得钱财，与“少用东西”的意思没有反义关系。", "生产": "生产：指制造物品，与“省”的少用义没有反义关系。", "扩大": "扩大：指范围或规模变大，与“省”的意思没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是少用东西，不浪费。", "primary_collocate": null, "pronunciation": "shěng", "ipa": "ʂɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "水很宝贵，洗手时要省着用。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要省水，不要让水一直流。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我想省一点，不买新衣服。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭很省油。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车省油，我们都喜欢。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开房间时关灯，这样才能省电。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少用一个塑料袋，也能省一点资源。", "target_word": "省", "complexity_tier": "T3", "furigana": "shǎo yòng yí gè sù liào dài, yě néng shěng yì diǎn zī yuán.", "sentence_source": "generated"}, {"text": "她把剩饭热了再吃，是为了省粮食。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不多，我们要省着花。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用旧书包上学，可以省一笔钱。", "target_word": "省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省了", "label": "体标"}, {"form": "省着", "label": "体标"}, {"form": "省省", "label": "重叠"}, {"form": "省油", "label": "复合"}], "register": "中性", "sense_fingerprint": "省：少用东西，不浪费", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bcd366b-9c48-45f8-b78e-b1f1f630c160') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：少用东西，不浪费。"}, {"text": "升", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“上升”。"}, {"text": "盛", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛、丰盛”。"}, {"text": "深", "is_correct": false, "explanation": "shēn 与 shěng 韵母不同（-n 与 -ng）、声调也不同，意思是“深浅”的“深”。"}, {"text": "婶", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。"}, {"text": "绳", "is_correct": false, "explanation": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。"}], "explanations": {"省": "省（shěng）：少用东西，不浪费。", "升": "shēng（第一声）与 shěng（第三声）声调不同，意思是“上升”。", "盛": "shèng（第四声）与 shěng（第三声）声调不同，意思是“兴盛、丰盛”。", "深": "shēn 与 shěng 韵母不同（-n 与 -ng）、声调也不同，意思是“深浅”的“深”。", "婶": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“婶婶”。", "绳": "shéng（第二声）与 shěng（第三声）声调不同，意思是“绳子”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示少用、不浪费，“洗手时要省着用”符合句意。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指把衣物穿在身上，与“水很宝贵”的语境不合，不能说“穿水”。"}, {"text": "戴", "is_correct": false, "explanation": "语义：“戴”指把东西戴在身上，与用水的语境不符，句意不通。"}, {"text": "带", "is_correct": false, "explanation": "配价：“带”要带着具体的人或物移动，“要带着用水”没有合理的宾语搭配。"}], "explanations": {"省": "“省”表示少用、不浪费，“洗手时要省着用”符合句意。", "穿": "语义：“穿”指把衣物穿在身上，与“水很宝贵”的语境不合，不能说“穿水”。", "戴": "语义：“戴”指把东西戴在身上，与用水的语境不符，句意不通。", "带": "配价：“带”要带着具体的人或物移动，“要带着用水”没有合理的宾语搭配。"}, "sentence_index": 0, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的错误省了很多。", "explanation": "这里应该用〈减少〉。“省”指少用、不浪费东西，错误数量的下降要说“减少”。"}, {"text": "这家店的油价省了很多。", "explanation": "这里应该用〈降低〉。“省”指少用、不浪费东西，价格的下降要说“降低”或“下降”。"}, {"text": "他省了这次比赛的机会。", "explanation": "这里应该用〈放弃〉。“省”是节约、少用的意思，不能用来表示放弃机会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "省", "is_correct": true, "explanation": "省（shěng）：少用东西，不浪费。"}, {"text": "生", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。"}, {"text": "声", "is_correct": false, "explanation": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。"}, {"text": "剩", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。"}, {"text": "审", "is_correct": false, "explanation": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。"}, {"text": "身", "is_correct": false, "explanation": "shēn 与 shěng 韵母不同（-n 与 -ng）、声调也不同，意思是“身体”。"}], "explanations": {"省": "省（shěng）：少用东西，不浪费。", "生": "shēng（第一声）与 shěng（第三声）声调不同，意思是“生命、出生”。", "声": "shēng（第一声）与 shěng（第三声）声调不同，意思是“声音”。", "剩": "shèng（第四声）与 shěng（第三声）声调不同，意思是“剩余”。", "审": "shěn 与 shěng 韵母不同（-n 与 -ng），意思是“审查”。", "身": "shēn 与 shěng 韵母不同（-n 与 -ng）、声调也不同，意思是“身体”。"}, "sentence_index": null, "correct_answer": "省"}, "level_3": {"options": [{"text": "省", "is_correct": true, "explanation": "“省”表示节约，“也能省一点资源”符合句意。"}, {"text": "耗", "is_correct": false, "explanation": "语域：“耗”偏书面语，口语中多说“耗费”，且“也能耗一点资源”与“少用”的语境相反。"}, {"text": "增", "is_correct": false, "explanation": "搭配：“增”单用时不带“一点资源”，应说“增加”，且与“少用”的语境相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”指丢弃具体的东西，不能说“扔一点资源”。"}], "explanations": {"省": "“省”表示节约，“也能省一点资源”符合句意。", "耗": "语域：“耗”偏书面语，口语中多说“耗费”，且“也能耗一点资源”与“少用”的语境相反。", "增": "搭配：“增”单用时不带“一点资源”，应说“增加”，且与“少用”的语境相反。", "扔": "搭配：“扔”指丢弃具体的东西，不能说“扔一点资源”。"}, "sentence_index": 6, "correct_answer": "省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这样做可以省家里的负担。", "explanation": "这里应该用〈减轻〉。“省”用于可以节约的钱、水、电等，“负担”的减轻要说“减轻”。"}, {"text": "这次改革让城市的范围省了一半。", "explanation": "这里应该用〈缩小〉。“省”用于可以节约的钱、水、电等，范围的缩小要说“缩小”。"}, {"text": "他每个月都省一点经验。", "explanation": "这里应该用〈积累〉。“省”指节约、不浪费，经验是靠实践积累的，不能“省”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月房租涨了，我们得钱省。", "corrected_sentence": "这个月房租涨了，我们得省钱。", "error_description": "错误：“钱省”。正确：“省钱”。“省”是动词，宾语“钱”要紧跟其后，不能放到动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把用剩的纸省来下，给孩子画画。", "corrected_sentence": "我们把用剩的纸省下来，给孩子画画。", "error_description": "错误：“省来下”。正确：“省下来”。“下来”是趋向补语，应紧跟动词，构成“省下来”，不能颠倒成“来下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68708ddd-d0ab-47d2-b530-b2d7bb897730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "正确：浪费与节省是反义，指用得过多，与省水正相反。"}, {"text": "漱口", "is_correct": false, "explanation": "漱口只是一个用水动作，与省水没有反义关系。"}, {"text": "拖地", "is_correct": false, "explanation": "拖地是一种家务动作，与省水不构成反义。"}, {"text": "洗车", "is_correct": false, "explanation": "洗车是一种用水的活动，与省水不构成反义。"}], "correct_answer": "浪费", "explanations": {"浪费": "正确：浪费与节省是反义，指用得过多，与省水正相反。", "漱口": "漱口只是一个用水动作，与省水没有反义关系。", "拖地": "拖地是一种家务动作，与省水不构成反义。", "洗车": "洗车是一种用水的活动，与省水不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "正确：浪费与节省是反义，指用得过多，与省水正相反。"}, {"text": "冲洗", "is_correct": false, "explanation": "冲洗只是一个清洗动作，与省水没有反义关系。"}, {"text": "擦桌子", "is_correct": false, "explanation": "擦桌子是一种清洁动作，与省水不构成反义。"}, {"text": "灌溉", "is_correct": false, "explanation": "灌溉是给农田供水，与省水不构成反义。"}], "correct_answer": "浪费", "explanations": {"浪费": "正确：浪费与节省是反义，指用得过多，与省水正相反。", "冲洗": "冲洗只是一个清洗动作，与省水没有反义关系。", "擦桌子": "擦桌子是一种清洁动作，与省水不构成反义。", "灌溉": "灌溉是给农田供水，与省水不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "省水就是少用一点水。", "primary_collocate": null, "pronunciation": "shěng shuǐ", "ipa": "ʂɤŋ˨˩ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "洗澡时间短一点，就能省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用洗菜的水冲厕所，这样可以省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里没有多少水了，今天我们要省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想省水，所以只用半桶水洗车。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟洗手时总是开着水龙头，一点也不省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月水费太高，我们得想办法省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用小杯子漱口，也是一种省水的办法。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上很缺水，住在那里的人天天省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省水，她把洗衣服的水留下来拖地。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用纸擦一下盘子，洗碗时就能省水。", "target_word": "省水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省水", "label": "原形"}], "register": "中性", "sense_fingerprint": "少用一点水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省水", "is_correct": true, "explanation": "正确答案。shěng shuǐ，指少用一点水。"}, {"text": "生水", "is_correct": false, "explanation": "shēng 与 shěng 声调不同（第一声与第三声），生水指没有烧开的水。"}, {"text": "盛水", "is_correct": false, "explanation": "shèng 与 shěng 声调不同（第四声与第三声），盛水指把水装进容器。"}, {"text": "神水", "is_correct": false, "explanation": "shén 与 shěng 韵母不同（-en 与 -eng），神水指神奇的水。"}], "explanations": {"省水": "正确答案。shěng shuǐ，指少用一点水。", "生水": "shēng 与 shěng 声调不同（第一声与第三声），生水指没有烧开的水。", "盛水": "shèng 与 shěng 声调不同（第四声与第三声），盛水指把水装进容器。", "神水": "shén 与 shěng 韵母不同（-en 与 -eng），神水指神奇的水。"}, "sentence_index": null, "correct_answer": "省水"}, "level_3": {"options": [{"text": "省水", "is_correct": true, "explanation": "正确：省水指少用水，与“洗澡时间短一点”的结果一致。"}, {"text": "浪费水", "is_correct": false, "explanation": "语义：浪费水与“时间短一点”的结果相反，句意冲突。"}, {"text": "冲水", "is_correct": false, "explanation": "搭配：冲水的对象是马桶等，不能说洗澡时间短就能冲水。"}, {"text": "糟蹋水", "is_correct": false, "explanation": "语域：糟蹋是口语且带贬义，与这句平实的说明不协调，同时也与“时间短”的结果相反。"}], "explanations": {"省水": "正确：省水指少用水，与“洗澡时间短一点”的结果一致。", "浪费水": "语义：浪费水与“时间短一点”的结果相反，句意冲突。", "冲水": "搭配：冲水的对象是马桶等，不能说洗澡时间短就能冲水。", "糟蹋水": "语域：糟蹋是口语且带贬义，与这句平实的说明不协调，同时也与“时间短”的结果相反。"}, "sentence_index": 0, "correct_answer": "省水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天黑以后，我们关灯，这样就能省水。", "explanation": "这里应该用〈省电〉。关灯节省的是电，省水指节约用水，不能用来说关灯的效果。"}, {"text": "坐高铁去北京，可以省水。", "explanation": "这里应该用〈省时间〉。坐高铁节省的是时间，省水只说用水减少。"}, {"text": "这家店的东西便宜，我们能省水。", "explanation": "这里应该用〈省钱〉。东西便宜是为了省钱，省水指节约用水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省水", "is_correct": true, "explanation": "正确：省水的办法指少用水的办法，与用小杯子漱口的做法一致。"}, {"text": "浇花", "is_correct": false, "explanation": "语义：用小杯子漱口与浇花无关，句中的“办法”指节约用水。"}, {"text": "煮饭", "is_correct": false, "explanation": "搭配：煮饭的对象是米和菜，“煮饭的办法”不能指漱口时节水。"}, {"text": "烧水", "is_correct": false, "explanation": "语义：烧水是加热水，与用小杯子漱口节约用水的意思不符。"}], "explanations": {"省水": "正确：省水的办法指少用水的办法，与用小杯子漱口的做法一致。", "浇花": "语义：用小杯子漱口与浇花无关，句中的“办法”指节约用水。", "煮饭": "搭配：煮饭的对象是米和菜，“煮饭的办法”不能指漱口时节水。", "烧水": "语义：烧水是加热水，与用小杯子漱口节约用水的意思不符。"}, "sentence_index": 6, "correct_answer": "省水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请了保姆以后，我们真省水。", "explanation": "这里应该用〈省心〉。请保姆是为了省心，省水指节约用水。"}, {"text": "网上买菜很省水，不用出门。", "explanation": "这里应该用〈省事〉。网上买菜省的是麻烦和精力，省水指节约用水。"}, {"text": "这种车很省水，开起来很合算。", "explanation": "这里应该用〈省油〉。汽车节省的是燃油，省水不能用来形容车的油耗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们正在省水了，水费少了。", "corrected_sentence": "这个月我们省了水，水费少了。", "error_description": "体标冲突：“正在”表示动作进行中，“了”表示动作已完成，二者不能同时用于同一动作。去掉“正在”，说“省了水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家了省水，水费一直很低。", "corrected_sentence": "我们家很省水，水费一直很低。", "error_description": "用词错误：“了”误用于“很”的位置；程度副词“很”应放在“省水”之前，说“很省水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
