INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时尚就是很多人喜欢的东西，比如衣服、发型。", "primary_collocate": null, "pronunciation": "shí shàng", "ipa": "ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "现在的时尚是短发和白鞋。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每天看手机，了解最新的时尚。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想知道现在年轻人喜欢什么时尚。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "姐姐很懂时尚，买的衣服都很好看。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太关心时尚，只想穿得舒服。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "时尚每年都不一样。", "target_word": "时尚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她跟着时尚剪了短头发。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "十年前的时尚现在又回来了。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友说红色是今年的时尚。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了跟上时尚，他买了一双新鞋。", "target_word": "时尚", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "快时尚", "label": "复合"}, {"form": "時尚", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时尚·很多人喜欢的衣服、发型等东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49c86a1a-5204-4936-87bc-89eede9ea748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时尚", "is_correct": true, "explanation": "时尚指很多人喜欢的衣服、发型等东西。"}, {"text": "史上", "is_correct": false, "explanation": "shǐ（第三声）与 shí（第二声）声调不同，史上指历史上。"}, {"text": "直上", "is_correct": false, "explanation": "zhí 与 shí 只差声母（zh 与 sh），直上指笔直向上。"}, {"text": "世上", "is_correct": false, "explanation": "shì（第四声）与 shí（第二声）声调不同，世上指世间。"}], "explanations": {"时尚": "时尚指很多人喜欢的衣服、发型等东西。", "史上": "shǐ（第三声）与 shí（第二声）声调不同，史上指历史上。", "直上": "zhí 与 shí 只差声母（zh 与 sh），直上指笔直向上。", "世上": "shì（第四声）与 shí（第二声）声调不同，世上指世间。"}, "sentence_index": null, "correct_answer": "时尚"}, "level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不能与“短发和白鞋”并列作主语，句子不通。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：指现在流行的短发和白鞋这类样式，与句意相符。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票与发型和鞋子无关，句子读来不通。"}, {"text": "发型", "is_correct": false, "explanation": "搭配：“发型”可以指短发，但白鞋不是发型，二者不能并列作主语。"}], "explanations": {"天气": "语义：天气不能与“短发和白鞋”并列作主语，句子不通。", "时尚": "正确：指现在流行的短发和白鞋这类样式，与句意相符。", "股票": "语义：股票与发型和鞋子无关，句子读来不通。", "发型": "搭配：“发型”可以指短发，但白鞋不是发型，二者不能并列作主语。"}, "sentence_index": 0, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上吃了一个时尚当早餐。", "explanation": "这里把“时尚”当成了食物。时尚指衣服、发型等很多人喜欢的东西，不能当作早餐来吃。"}, {"text": "我每天都在时尚里上学。", "explanation": "时尚指衣服、发型这类东西，不是场所，不能用“在……里”。"}, {"text": "他的年龄很时尚。", "explanation": "这里应该用〈年轻〉。时尚指衣服、发型等很多人喜欢的东西，不能用来形容年龄，应说“他很年轻”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：剪头发不会跟着考试，句子不通。"}, {"text": "时尚", "is_correct": true, "explanation": "正确：“跟着时尚剪头发”指跟随流行的发型样式。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能作为剪头发的依据，句子读来不通。"}, {"text": "配方", "is_correct": false, "explanation": "搭配：“跟着”后接流行的样式或风潮，不搭配配方。"}], "explanations": {"考试": "语义：剪头发不会跟着考试，句子不通。", "时尚": "正确：“跟着时尚剪头发”指跟随流行的发型样式。", "价格": "语义：价格不能作为剪头发的依据，句子读来不通。", "配方": "搭配：“跟着”后接流行的样式或风潮，不搭配配方。"}, "sentence_index": 6, "correct_answer": "时尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的心情很时尚。", "explanation": "这里应该用〈愉快〉。时尚指衣服、发型等很多人喜欢的东西，不能用来形容心情。"}, {"text": "今天时尚很好。", "explanation": "这里应该用〈天气〉。时尚指衣服、发型等很多人喜欢的东西，不能用来描述天气。"}, {"text": "他去商店买了时尚。", "explanation": "这里不对。时尚指潮流，本身不是能买的商品，不能用“买”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈觉得这种时尚了很好看。", "corrected_sentence": "妈妈觉得这种时尚很好看。", "error_description": "错误：“时尚”后多加了“了”。“了”不能用在名词“时尚”之后，应为“觉得这种时尚很好看”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一只时尚。", "corrected_sentence": "这是一种时尚。", "error_description": "错误：量词“只”用错，应为“一种时尚”。“只”用于动物，时尚是一类事物，应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
