INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "服装就是人们穿的衣服。", "primary_collocate": null, "pronunciation": "fú zhuāng", "ipa": "fu˧˥ ʈʂuaŋ˥", "syllable_count": 2, "sentences": [{"text": "这套服装很漂亮。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢买新服装。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们穿着红色的服装。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的服装都在打折。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的运动会上，同学们穿同样的服装。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的服装总是很干净。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加晚会要穿正式的服装。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的服装比冬天的轻。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们换上了表演的服装。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些服装是我妈妈做的。", "target_word": "服装", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套服装", "label": "量词"}, {"form": "服装店", "label": "复合"}, {"form": "服装设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们穿在身上的衣服的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4246d07b-ae3c-4f25-9405-93e74c5a5c69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "服装", "is_correct": true, "explanation": "正确：“服装”指人穿的衣服，“这套服装很漂亮”成立。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“套”一般不用来数食物，“漂亮”也不用来形容食物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以穿的东西，与句中指衣物的语境不符。"}, {"text": "早晨", "is_correct": false, "explanation": "语义：“早晨”指一天的时间，不能用“套”来数，也不说“很漂亮”。"}], "explanations": {"服装": "正确：“服装”指人穿的衣服，“这套服装很漂亮”成立。", "食物": "搭配：“套”一般不用来数食物，“漂亮”也不用来形容食物。", "天气": "语义：“天气”不是可以穿的东西，与句中指衣物的语境不符。", "早晨": "语义：“早晨”指一天的时间，不能用“套”来数，也不说“很漂亮”。"}, "sentence_index": 0, "correct_answer": "服装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只服装。", "explanation": "这里应该用〈套〉或〈件〉。“只”用于动物或成对物品中的一个，不用来数服装。"}, {"text": "这个礼盒的服装很精美，打开的时候很惊喜。", "explanation": "这里应该用〈包装〉。服装指穿在身上的衣物，商品的外包装要说包装。"}, {"text": "这间屋子刚刚完成了服装，墙面很漂亮。", "explanation": "这里应该用〈装修〉。服装指穿在身上的衣物，房屋的装饰要说装修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服装", "is_correct": true, "explanation": "正确：“服装”指人穿的衣服，“穿正式的服装”成立。"}, {"text": "饭菜", "is_correct": false, "explanation": "配价：“穿”的宾语须是衣物，“饭菜”不能被穿。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以穿的东西，与“正式”的穿着语境不合。"}, {"text": "玩具", "is_correct": false, "explanation": "配价：“穿”不能带“玩具”作宾语，玩具不是穿着的东西。"}], "explanations": {"服装": "正确：“服装”指人穿的衣服，“穿正式的服装”成立。", "饭菜": "配价：“穿”的宾语须是衣物，“饭菜”不能被穿。", "天空": "语义：“天空”不是可以穿的东西，与“正式”的穿着语境不合。", "玩具": "配价：“穿”不能带“玩具”作宾语，玩具不是穿着的东西。"}, "sentence_index": 6, "correct_answer": "服装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭店的服装很好，客人都很满意。", "explanation": "这里应该用〈服务〉。服装指衣物，饭店的待客工作要说服务；两词只是字形相近。"}, {"text": "士兵必须服装上级的命令。", "explanation": "这里应该用〈服从〉。服从的对象是命令和安排，“服装”指穿衣，不能带命令作宾语。"}, {"text": "这台机器的服装坏了，需要请师傅来修。", "explanation": "这里应该用〈装置〉。服装指穿在身上的衣物，机器的部件要说装置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一只新服装。", "corrected_sentence": "她买了一套新服装。", "error_description": "量词错误：“服装”前应用“套”或“件”等量词，不用“只”。“只”用于动物或成对物品中的一个，说“一只新服装”不地道，可改为“一套新服装”或“一件新服装”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的服装洗很干净。", "corrected_sentence": "她的服装洗得很干净。", "error_description": "状态补语错误：“洗”后接“很干净”要用“得”，应说“洗得很干净”，不能说“洗很干净”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17e3c91a-18e3-40f7-ad66-510a10e8293c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
