INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能用来检查东西好不好的石头。", "primary_collocate": null, "pronunciation": "shì jīn shí", "ipa": "ʂɻ̩˥˩ tɕin˥ ʂɻ̩˧˥", "syllable_count": 3, "sentences": [{"text": "他用试金石检查这块金子。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅拿出一块黑色的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块试金石是爷爷留下来的。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，人们用试金石看金子的真假。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用金子在试金石上擦一下，就能看出成色。", "target_word": "试金石", "complexity_tier": "T3", "furigana": "shì jīn shí", "sentence_source": "generated"}, {"text": "店里的试金石又黑又硬。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把金戒指放在试金石上擦了擦。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一块很老的试金石。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人带着试金石去买金子。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "试金石能帮我们看出金子的好坏。", "target_word": "试金石", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块试金石", "label": "量词"}], "register": "中性", "sense_fingerprint": "用来辨别金子成色的黑色石头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3029008e-9b1c-4965-998f-79cba7433aef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "试金石", "is_correct": true, "explanation": "正确：“试金石”是检验金子成色的石头，与“检查这块金子”相符。"}, {"text": "锤子", "is_correct": false, "explanation": "语义：锤子不能检验金子的成色，用锤子敲会损坏金子。"}, {"text": "扇子", "is_correct": false, "explanation": "搭配：“用扇子”与“检查金子”不搭配，扇子不能用来检验金子。"}, {"text": "豆腐", "is_correct": false, "explanation": "语义：豆腐无法检验金子的成色，句意不通。"}], "explanations": {"试金石": "正确：“试金石”是检验金子成色的石头，与“检查这块金子”相符。", "锤子": "语义：锤子不能检验金子的成色，用锤子敲会损坏金子。", "扇子": "搭配：“用扇子”与“检查金子”不搭配，扇子不能用来检验金子。", "豆腐": "语义：豆腐无法检验金子的成色，句意不通。"}, "sentence_index": 0, "correct_answer": "试金石"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用试金石切西瓜。", "explanation": "这里应该用〈刀〉。“试金石”是用来辨别金子成色的石头，不能用来切西瓜。"}, {"text": "他用试金石磨刀。", "explanation": "这里应该用〈磨刀石〉。“试金石”只用来辨别金子的成色，不能用来磨刀。"}, {"text": "老师傅用试金石唱歌。", "explanation": "这里应该用〈嗓子〉。唱歌要用嗓子，“试金石”是石头，不能用来唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "试金石", "is_correct": true, "explanation": "正确：“试金石”是石头，可以在上面擦拭物品，符合句意。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块遇热会融化，不能用来擦金戒指。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "搭配：“玻璃杯”是容器，不能用来擦拭物品，与“放在……上擦”不搭配。"}, {"text": "棉花糖", "is_correct": false, "explanation": "语义：棉花糖柔软易碎，不能用来擦金戒指。"}], "explanations": {"试金石": "正确：“试金石”是石头，可以在上面擦拭物品，符合句意。", "冰块": "语义：冰块遇热会融化，不能用来擦金戒指。", "玻璃杯": "搭配：“玻璃杯”是容器，不能用来擦拭物品，与“放在……上擦”不搭配。", "棉花糖": "语义：棉花糖柔软易碎，不能用来擦金戒指。"}, "sentence_index": 6, "correct_answer": "试金石"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用试金石量出金戒指的直径。", "explanation": "这里应该用〈卡尺〉。“试金石”只用来辨别金子的成色，不能用来量长度。"}, {"text": "他用试金石称出金子的重量。", "explanation": "这里应该用〈天平〉。“试金石”只能辨别金子的成色，不能用来称重。"}, {"text": "他用试金石吸起了地上的铁钉。", "explanation": "这里应该用〈磁石〉。“试金石”不能吸铁，吸铁要用磁石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从柜子里拿出一只试金石给我看。", "corrected_sentence": "他从柜子里拿出一块试金石给我看。", "error_description": "量词错误：“试金石”是石头，量词应用“块”。“只”用于动物等，不能用于“试金石”。正确：一块试金石。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这块金子放在试金石里擦了擦。", "corrected_sentence": "他把这块金子放在试金石上擦了擦。", "error_description": "方位词错误：“试金石”是石头，在它表面放东西用“上”，不能说“里”。正确：放在试金石上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74bab309-1a2c-4595-a3ce-d778df083a78') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
