INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "河水就是河里的水。", "primary_collocate": null, "pronunciation": "hé shuǐ", "ipa": "xɤ˧˥ ʂweɪ˨˩", "syllable_count": 2, "sentences": [{"text": "我们用桶从河里打了一桶河水。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，这里的河水可以直接洗菜。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把脚放进河水里，觉得很凉。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯河水有点黄，不能喝。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里有很多小石头。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手摸了摸河水，说太冷了。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用河水浇田，今年的菜长得很好。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照在河水上，河水发着光。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验课上，老师让我们观察一杯河水。", "target_word": "河水", "complexity_tier": "T3", "furigana": "hé shuǐ", "sentence_source": "generated"}, {"text": "这里的河水带着泥，看起来是黄色的。", "target_word": "河水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一桶河水", "label": "量词"}], "register": "中性", "sense_fingerprint": "河里的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b8871e-37c6-4207-918f-20fe6c25658f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河水", "is_correct": true, "explanation": "正确：河水是河里的水，可以用桶从河里打。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：河里打不出牛奶，句意不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：河里不会有汽油，与“从河里打”冲突。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“打”用于打水等液体，不能说“从河里打一桶石头”。"}], "explanations": {"河水": "正确：河水是河里的水，可以用桶从河里打。", "牛奶": "语义：河里打不出牛奶，句意不通。", "汽油": "语义：河里不会有汽油，与“从河里打”冲突。", "石头": "搭配：“打”用于打水等液体，不能说“从河里打一桶石头”。"}, "sentence_index": 0, "correct_answer": "河水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大海的河水很咸，不能直接喝。", "explanation": "这里应该用〈海水〉。大海里的水是海水，“河水”指河里的水，不能这样用。"}, {"text": "厨房的河水一开龙头就有。", "explanation": "这里应该用〈自来水〉。从水龙头出来的水应说自来水，河水指河里的水。"}, {"text": "医生给病人打针时，用的是河水。", "explanation": "这里应该用〈生理盐水〉。打针用的是经过消毒的生理盐水，河水是江河中的水，不能用于注射。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "河水", "is_correct": true, "explanation": "正确：河水可以用来浇田，符合“农民用……浇田”。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁不能用来浇田，句意不通。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋不能用来浇田，会伤害菜苗，与句中的“长得很好”冲突。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "搭配：浇的对象是液体，洗衣粉是粉末，“用洗衣粉浇田”不自然。"}], "explanations": {"河水": "正确：河水可以用来浇田，符合“农民用……浇田”。", "果汁": "语义：果汁不能用来浇田，句意不通。", "醋": "语义：醋不能用来浇田，会伤害菜苗，与句中的“长得很好”冲突。", "洗衣粉": "搭配：浇的对象是液体，洗衣粉是粉末，“用洗衣粉浇田”不自然。"}, "sentence_index": 6, "correct_answer": "河水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游客在海边散步，浪花打在脚上，河水很凉。", "explanation": "这里应该用〈海水〉。海边的水是海水，河水指江河中的水。"}, {"text": "下完雨后，屋顶上接了很多河水。", "explanation": "这里应该用〈雨水〉。屋顶接的是雨水，河水指江河中的水。"}, {"text": "厨房里放着一张河水。", "explanation": "这里应该用〈杯〉或〈桶〉。“张”用于纸、桌子等扁平物，液体常用“杯”“桶”等量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用杯子舀了一个河水，放在桌上澄清。", "corrected_sentence": "他用杯子舀了一杯河水，放在桌上澄清。", "error_description": "量词错误：“河水”不能用“个”来计量，应用“杯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村民们都喜欢很清得河水，不爱喝井水。", "corrected_sentence": "村民们都喜欢很清的河水，不爱喝井水。", "error_description": "结构助词错误：修饰语“很清”与“河水”之间应用“的”，不能用“得”，写作“很清的河水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73ffc8a1-e1de-492b-9238-3c3801a75a6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "减轻", "is_correct": true, "explanation": "减轻：与“加重”互为反义词，指使负担或程度变轻。"}, {"text": "说明", "is_correct": false, "explanation": "说明：指讲清楚道理，与“加重”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：指把物品聚到一起，与“加重”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：指出外游览，与“加重”没有反义关系。"}], "correct_answer": "减轻", "explanations": {"减轻": "减轻：与“加重”互为反义词，指使负担或程度变轻。", "说明": "说明：指讲清楚道理，与“加重”没有反义关系。", "收集": "收集：指把物品聚到一起，与“加重”没有反义关系。", "旅行": "旅行：指出外游览，与“加重”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
