INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更重或让问题变得更严重。", "primary_collocate": null, "pronunciation": "jiā zhòng", "ipa": "tɕia˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他往包里多放了几块石头，加重了背包的负担。", "target_word": "加重", "complexity_tier": "T3", "furigana": "tā wǎng bāo lǐ duō fàng le jǐ kuài shítou, jiāzhòng le bēibāo de fùdān.", "sentence_source": "generated"}, {"text": "熬夜会加重你的黑眼圈。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，奶奶的腿疼加重了。", "target_word": "加重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次失败加重了他心里的压力。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不吃药只会加重病情。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要再加重我的负担了。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货物太多，加重了卡车的负担。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪加重了山区的交通困难。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架只会加重两个人的矛盾。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的批评加重了他的紧张。", "target_word": "加重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加重了", "label": "体标"}, {"form": "加重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "让东西更重，或让问题、病情更严重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fd9d1-c648-40bc-8ba1-18290f6f76e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重 jiāzhòng，意思是让东西更重，或让问题、病情更严重。"}, {"text": "家中", "is_correct": false, "explanation": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。"}, {"text": "家长", "is_correct": false, "explanation": "第二个音节的韵母与声调都不同：-ǎng（第三声）与 -òng（第四声）不同，家长意思是父母或监护人。"}, {"text": "家政", "is_correct": false, "explanation": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。"}, {"text": "甲种", "is_correct": false, "explanation": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。"}, {"text": "间种", "is_correct": false, "explanation": "第一个音节多韵尾 n 且为第四声：jiàn 与 jiā 不同，第二个音节相同，间种意思是间隔种植。"}], "explanations": {"加重": "加重 jiāzhòng，意思是让东西更重，或让问题、病情更严重。", "家中": "第二个音节的声调不同：zhōng（第一声）与 zhòng（第四声）不同，家中意思是在家里。", "家长": "第二个音节的韵母与声调都不同：-ǎng（第三声）与 -òng（第四声）不同，家长意思是父母或监护人。", "家政": "第二个音节的韵母不同：zhèng 与 zhòng 的韵母是 eng 与 ong，家政意思是家务管理。", "甲种": "两个音节的声调都不同：jiǎzhǒng（第三声）与 jiāzhòng 不同，甲种意思是甲类。", "间种": "第一个音节多韵尾 n 且为第四声：jiàn 与 jiā 不同，第二个音节相同，间种意思是间隔种植。"}, "sentence_index": null, "correct_answer": "加重"}, "level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：说多放石头使背包更重，与语境一致。"}, {"text": "减轻", "is_correct": false, "explanation": "语义：往包里多放石头只会使负担变重，“减轻”与语境相反。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”不接“负担”作宾语，不能说保护“背包的负担”。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语须是活动，不能接“背包的负担”。"}], "explanations": {"加重": "加重：说多放石头使背包更重，与语境一致。", "减轻": "语义：往包里多放石头只会使负担变重，“减轻”与语境相反。", "保护": "搭配：“保护”不接“负担”作宾语，不能说保护“背包的负担”。", "参加": "配价：“参加”的宾语须是活动，不能接“背包的负担”。"}, "sentence_index": 0, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司去年的利润加重了两成。", "explanation": "这里应该用〈增加〉。加重说重量或负担变重，利润、数量要用增加。"}, {"text": "这次谈话后，我对他的了解加重了。", "explanation": "这里应该用〈加深〉。加重指重量或负担变重，抽象的了解要用加深。"}, {"text": "这个月，工厂的生产速度加重了。", "explanation": "这里应该用〈加快〉。加重说重量或负担变重，速度的变化要用加快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加重", "is_correct": true, "explanation": "加重：说货物使卡车负担更重，与“货物太多”的因果一致。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品的外观，不能说装饰“负担”。"}, {"text": "调查", "is_correct": false, "explanation": "配价：“调查”需要人作主语，“货物太多”不能调查。"}, {"text": "消灭", "is_correct": false, "explanation": "语义：货物太多会使负担变重，“消灭负担”与这一语境相反。"}], "explanations": {"加重": "加重：说货物使卡车负担更重，与“货物太多”的因果一致。", "装饰": "搭配：“装饰”的对象是物品的外观，不能说装饰“负担”。", "调查": "配价：“调查”需要人作主语，“货物太多”不能调查。", "消灭": "语义：货物太多会使负担变重，“消灭负担”与这一语境相反。"}, "sentence_index": 6, "correct_answer": "加重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的英语水平加重了很多。", "explanation": "这里应该用〈提高〉。加重用于重量、负担或病情，水平、质量要用提高。"}, {"text": "这次改革后，学校的规模加重了。", "explanation": "这里应该用〈扩大〉。加重指重量、负担或病情变得更重，规模、范围要用扩大。"}, {"text": "他的记忆力加重了不少。", "explanation": "这里应该用〈增强〉。加重用于重量、负担或病情，记忆力、能力要用增强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他往行李箱里放了很多书，行李箱很加重了。", "corrected_sentence": "他往行李箱里放了很多书，行李箱加重了。", "error_description": "副词“很”不能直接修饰动词“加重”，应去掉“很”，说“行李箱加重了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "长期加班加重得他的身体负担。", "corrected_sentence": "长期加班加重了他的身体负担。", "error_description": "“加重”后表示完成的“了”不能换成“得”（“得”引出补语）。应说“加重了他的身体负担”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
