INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用过的、脏了的水。", "primary_collocate": null, "pronunciation": "fèi shuǐ", "ipa": "feɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "洗完衣服的废水可以用来冲厕所。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里的废水要流到下水道。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条小河里全是工厂排出的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废水又脏又臭，不能喝。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把废水倒进河里。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂专门处理城市的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着黑色的废水流进大河。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用过的废水不要乱倒，要收集起来。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一个池子，专门存放实验室的废水。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗车店的废水常常带着很多泡沫。", "target_word": "废水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工业废水", "label": "复合"}, {"form": "生活废水", "label": "复合"}], "register": "中性", "sense_fingerprint": "用过之后变脏、不能再用的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fd9d1-c648-40bc-8ba1-18290f6f76e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指洗完衣服后用过、变脏的水。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是食品，洗完衣服不会产生牛奶，也不能用来冲厕所。"}, {"text": "果汁", "is_correct": false, "explanation": "语义：果汁是饮料，不是洗衣后的水，与“冲厕所”的用途冲突。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：洗衣服后的水才说“用来冲厕所”，汽油是危险液体，不能这样使用。"}], "explanations": {"废水": "废水：符合句意，指洗完衣服后用过、变脏的水。", "牛奶": "语义：牛奶是食品，洗完衣服不会产生牛奶，也不能用来冲厕所。", "果汁": "语义：果汁是饮料，不是洗衣后的水，与“冲厕所”的用途冲突。", "汽油": "搭配：洗衣服后的水才说“用来冲厕所”，汽油是危险液体，不能这样使用。"}, "sentence_index": 0, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这桶废水清澈透明，很干净。", "explanation": "这里应该用〈清水〉。废水是用过、受污染的水，不会清澈透明，清水才干净。"}, {"text": "早上他用废水刷牙。", "explanation": "这里应该用〈自来水〉。废水受污染，刷牙要用干净的自来水。"}, {"text": "清晨，草叶上挂满了废水。", "explanation": "这里应该用〈露水〉。废水是用过、受污染的水，清晨草叶上的水珠应是露水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "废水", "is_correct": true, "explanation": "废水：符合句意，指黑色的、受污染的水流进大河。"}, {"text": "青草", "is_correct": false, "explanation": "体貌：青草是绿色的，与句中“黑色”的外观相冲突。"}, {"text": "白雪", "is_correct": false, "explanation": "体貌：白雪是白色的，与句中“黑色”的外观相冲突。"}, {"text": "饮用水", "is_correct": false, "explanation": "语义：饮用水通常清澈，不会是黑色的，与句意冲突。"}], "explanations": {"废水": "废水：符合句意，指黑色的、受污染的水流进大河。", "青草": "体貌：青草是绿色的，与句中“黑色”的外观相冲突。", "白雪": "体貌：白雪是白色的，与句中“黑色”的外观相冲突。", "饮用水": "语义：饮用水通常清澈，不会是黑色的，与句意冲突。"}, "sentence_index": 6, "correct_answer": "废水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她哭得满脸都是废水。", "explanation": "这里应该用〈泪水〉。废水是用过、受污染的水，哭出来的眼泪应说泪水。"}, {"text": "运动后，他的脸上全是废水。", "explanation": "这里应该用〈汗水〉。废水指用过、受污染的水，运动后脸上的水应是汗水。"}, {"text": "山坡上流着融化的废水。", "explanation": "这里应该用〈雪水〉。废水是用过、受污染的水，融化的雪水应说雪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把用过的一块废水装进桶里，拿去浇花。", "corrected_sentence": "他把用过的废水装进桶里，拿去浇花。", "error_description": "量词错误：“块”用于块状的固体，废水是液体，且此处泛指，不应加“一块”，应说“用过的废水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些废水我们处理着很多次。", "corrected_sentence": "这些废水我们处理过很多次。", "error_description": "体标错误：“着”表示动作正在进行，不能用于“很多次”这类已发生的经历，应用“过”，说“处理过很多次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
