INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不只是这样。", "primary_collocate": null, "pronunciation": "bù jǐn rú cǐ", "ipa": "pu˥˩ tɕin˨˩˦ ɻu˧˥ tsʰɨ˨˩˦", "syllable_count": 4, "sentences": [{"text": "他迟到了。不仅如此，还忘了带书。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间房子很大。不仅如此，离学校也近。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司工资高，不仅如此，工作时间也短。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨了。不仅如此，风还很大。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌好听。不仅如此，舞也跳得很好。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很窄。不仅如此，路上车还很多。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机坏了。不仅如此，电脑也打不开了。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮我找到了工作，不仅如此，还借给我钱。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热。不仅如此，空气也很干。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师人很好，不仅如此，课也讲得很清楚。", "target_word": "不仅如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不只是前面所说的情况，后面还有补充", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fd9d1-c648-40bc-8ba1-18290f6f76e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：在“迟到”之外再补充忘带书的情况。"}, {"text": "幸亏", "is_correct": false, "explanation": "搭配：“幸亏”后接好的结果，不接“忘了带书”这样的坏事。"}, {"text": "否则", "is_correct": false, "explanation": "语义：“否则”需要前面有条件，这里没有假设关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：迟到与忘带书之间没有因果关系，“因此”不成立。"}], "explanations": {"不仅如此": "不仅如此：在“迟到”之外再补充忘带书的情况。", "幸亏": "搭配：“幸亏”后接好的结果，不接“忘了带书”这样的坏事。", "否则": "语义：“否则”需要前面有条件，这里没有假设关系。", "因此": "语义：迟到与忘带书之间没有因果关系，“因此”不成立。"}, "sentence_index": 0, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很努力，不仅如此，成绩不好。", "explanation": "这里应该用〈不过〉。不仅如此表示在前面基础上再补充，这里前后是转折关系，要用不过。"}, {"text": "他吃完饭，不仅如此，去了学校。", "explanation": "这里应该用〈然后〉。不仅如此表示补充，不表示动作的先后，吃完饭再去学校要用然后。"}, {"text": "我很想去看电影，不仅如此，没有时间。", "explanation": "这里应该用〈然而〉。不仅如此表示递进，这里前后是转折关系，要用然而。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不仅如此", "is_correct": true, "explanation": "不仅如此：在“手机坏了”之外再补充电脑也出了问题。"}, {"text": "相反", "is_correct": false, "explanation": "语义：电脑也打不开是同方向的补充，“相反”与语境矛盾。"}, {"text": "幸好", "is_correct": false, "explanation": "搭配：“幸好”后接好的结果，不接“电脑也打不开了”这样的坏事。"}, {"text": "尤其是", "is_correct": false, "explanation": "搭配：“尤其是”后接名词，不接“电脑也打不开了”这样的完整小句。"}], "explanations": {"不仅如此": "不仅如此：在“手机坏了”之外再补充电脑也出了问题。", "相反": "语义：电脑也打不开是同方向的补充，“相反”与语境矛盾。", "幸好": "搭配：“幸好”后接好的结果，不接“电脑也打不开了”这样的坏事。", "尤其是": "搭配：“尤其是”后接名词，不接“电脑也打不开了”这样的完整小句。"}, "sentence_index": 6, "correct_answer": "不仅如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如果你今天有空，不仅如此，我们就一起去图书馆吧。", "explanation": "这里应该用〈那么〉。不仅如此表示补充，不能用来连接条件和结论，条件之后的结论要用那么。"}, {"text": "这家店今年很亏，不仅如此，去年很赚钱。", "explanation": "这里应该用〈相反〉。不仅如此表示补充递进，今年与去年形成对比，要用相反。"}, {"text": "我很想吃蛋糕，不仅如此，我在减肥。", "explanation": "这里应该用〈但是〉。不仅如此表示递进，这里前后是转折关系，要用但是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很聪明，不仅如此，而是很努力。", "corrected_sentence": "他很聪明，不仅如此，还很努力。", "error_description": "“不仅如此”之后递进补充要用“还”，不能用“而是”；“而是”只用于否定之后的更正，这里前面没有否定。应说“不仅如此，还很努力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家商店东西很便宜，不仅如此，但是送货上门。", "corrected_sentence": "这家商店东西很便宜，不仅如此，还送货上门。", "error_description": "“不仅如此”要与“还”搭配表示递进，这里用“但是”表示转折，与前面的递进语境冲突，应说“还送货上门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
