INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "化学物质是构成各种东西的物质，比如水和盐。", "primary_collocate": null, "pronunciation": "huà xué wù zhì", "ipa": "xwa˥˩ ɕɥe˧˥ u˥˩ ʈʂɻ̩˥˩", "syllable_count": 4, "sentences": [{"text": "水和盐都是化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上的东西都由化学物质组成。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖是我们每天都吃的化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气里也有很多化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "化学课上，我们学习了各种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐和水混在一起，是两种化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里的化学物质是白色的。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，我把两种化学物质放在一起。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的玩具里也有化学物质。", "target_word": "化学物质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种化学物质", "label": "量词"}, {"form": "有害化学物质", "label": "复合"}], "register": "中性", "sense_fingerprint": "组成各种东西的基本物质，如水和盐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb3fd9d1-c648-40bc-8ba1-18290f6f76e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：水和盐不是颜色，句子说的是它们属于哪一类东西。"}, {"text": "化学物质", "is_correct": true, "explanation": "正确。水和盐都是组成东西的小颗粒，即化学物质。"}, {"text": "动物", "is_correct": false, "explanation": "语义：水和盐不是动物，不能归入动物类。"}, {"text": "金属", "is_correct": false, "explanation": "语义：水和盐不是金属，不能归入金属类。"}], "explanations": {"颜色": "语义：水和盐不是颜色，句子说的是它们属于哪一类东西。", "化学物质": "正确。水和盐都是组成东西的小颗粒，即化学物质。", "动物": "语义：水和盐不是动物，不能归入动物类。", "金属": "语义：水和盐不是金属，不能归入金属类。"}, "sentence_index": 0, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，化学物质考得很好。", "explanation": "这里应该用〈化学〉。“化学”是学科名称，可以说考得好；“化学物质”指物质，不能作为科目。"}, {"text": "我的叔叔是一位化学物质。", "explanation": "这里应该用〈化学家〉。“化学物质”指物质，不指人；说人应该用“化学家”。"}, {"text": "桌上放着一根化学物质。", "explanation": "这里应该用〈种〉。“根”用于细长的东西，化学物质不用“根”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是物质，盐和水不能说成“两种歌曲”。"}, {"text": "星星", "is_correct": false, "explanation": "语义：盐和水不是天体，不能说成“两种星星”。"}, {"text": "化学物质", "is_correct": true, "explanation": "正确。盐和水都是化学物质，句中说的正是这一类别。"}, {"text": "植物", "is_correct": false, "explanation": "语义：水和盐不是植物，不能归入植物类。"}], "explanations": {"歌曲": "语义：歌曲不是物质，盐和水不能说成“两种歌曲”。", "星星": "语义：盐和水不是天体，不能说成“两种星星”。", "化学物质": "正确。盐和水都是化学物质，句中说的正是这一类别。", "植物": "语义：水和盐不是植物，不能归入植物类。"}, "sentence_index": 6, "correct_answer": "化学物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两种药水一混合就发生了化学物质。", "explanation": "这里应该用〈化学反应〉。发生的是反应，“化学物质”是物质，不能说“发生化学物质”。"}, {"text": "厨房里停着一辆化学物质。", "explanation": "这里应该用〈种〉。“辆”用于车辆，化学物质不能用“辆”计量。"}, {"text": "工人把一只化学物质倒进了水池。", "explanation": "这里应该用〈种〉。“只”用于动物或成对、成个的东西，化学物质不用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师把一只化学物质放在桌上。", "corrected_sentence": "老师把一种化学物质放在桌上。", "error_description": "量词错误：“化学物质”前应用“种”，“只”用于动物或成对、成个的东西，不能用于物质名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张有毒的化学物质要分开存放。", "corrected_sentence": "这种有毒的化学物质要分开存放。", "error_description": "量词错误：“化学物质”前应用“种”，“张”用于纸、桌子等扁平的东西，不能用于物质名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5daafeec-d4fc-4772-b5e2-49cccbd8a972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强壮", "is_correct": true, "explanation": "正确。“强壮”与“身体很弱”（身体没有力气）是反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“很弱”的身体力气义没有反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”形容清洁程度，与“很弱”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面或气氛，与“很弱”没有反义关系。"}], "correct_answer": "强壮", "explanations": {"强壮": "正确。“强壮”与“身体很弱”（身体没有力气）是反义关系。", "高兴": "“高兴”形容心情，与“很弱”的身体力气义没有反义关系。", "干净": "“干净”形容清洁程度，与“很弱”没有反义关系。", "热闹": "“热闹”形容场面或气氛，与“很弱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "强壮", "is_correct": true, "explanation": "正确。“强壮”与“身体很弱”是反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”与“很弱”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”的反义词是“吵闹”，与“很弱”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”与“很弱”没有反义关系。"}], "correct_answer": "强壮", "explanations": {"强壮": "正确。“强壮”与“身体很弱”是反义关系。", "清楚": "“清楚”与“很弱”没有反义关系。", "安静": "“安静”的反义词是“吵闹”，与“很弱”没有反义关系。", "整齐": "“整齐”与“很弱”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体没有力气，或者做事情的能力很小。", "primary_collocate": null, "pronunciation": "hěn ruò", "ipa": "xən˨˩ ʐwo˥˩", "syllable_count": 2, "sentences": [{"text": "他三天没吃饭，现在身体很弱。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫刚出生，身体很弱，还不会自己站起来。", "target_word": "很弱", "complexity_tier": "T3", "furigana": "hěn ruò", "sentence_source": "generated"}, {"text": "他发烧了一天，身体很弱，连床都下不了。", "target_word": "很弱", "complexity_tier": "T3", "furigana": "hěn ruò", "sentence_source": "generated"}, {"text": "我的体力很弱，跑一千米就累了。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她游泳很弱，只能在浅水里玩。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下棋很弱，朋友们都不爱和他玩。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子小时候身体很弱，常常生病。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的英语很弱，不敢和外国人说话。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会做饭，可是做家务的能力很弱。", "target_word": "很弱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生病以后，她现在身体很弱，走几步就累。", "target_word": "很弱", "complexity_tier": "T3", "furigana": "hěn ruò", "sentence_source": "generated"}], "morphological_forms": [{"form": "更弱", "label": "比较"}, {"form": "最弱", "label": "最高级"}, {"form": "虚弱", "label": "复合"}], "register": "中性", "sense_fingerprint": "很弱：身体没力气，或做事的能力很小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa49fc73-7be4-4cc3-904b-3ea617b1144c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很弱", "is_correct": true, "explanation": "正确。“身体很弱”指身体没有力气，与“三天没吃饭”的状态一致。"}, {"text": "很强", "is_correct": false, "explanation": "语义：“很强”与前文“三天没吃饭”矛盾，三天不进食的人身体不会“很强”。"}, {"text": "很胖", "is_correct": false, "explanation": "体貌：“胖”说的是体形，与“三天没吃饭”的状态矛盾，也不能说明身体的力气。"}, {"text": "很清楚", "is_correct": false, "explanation": "搭配：“清楚”不修饰身体，不能说“身体很清楚”。"}], "explanations": {"很弱": "正确。“身体很弱”指身体没有力气，与“三天没吃饭”的状态一致。", "很强": "语义：“很强”与前文“三天没吃饭”矛盾，三天不进食的人身体不会“很强”。", "很胖": "体貌：“胖”说的是体形，与“三天没吃饭”的状态矛盾，也不能说明身体的力气。", "很清楚": "搭配：“清楚”不修饰身体，不能说“身体很清楚”。"}, "sentence_index": 0, "correct_answer": "很弱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次期末考试，我的数学成绩很弱。", "explanation": "这里应该用〈差〉。“很弱”说人的力气或能力，成绩和质量要说“差”或“不好”。"}, {"text": "他的个子很弱，站在队伍里一点也不显眼。", "explanation": "这里应该用〈矮〉。“很弱”说力气或能力，个子的高矮要说“矮”。"}, {"text": "这个城市的人口很弱。", "explanation": "这里应该用〈少〉。“很弱”说人的力量或能力，人口、人数等数量要说“少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很弱", "is_correct": true, "explanation": "正确。“身体很弱，常常生病”前后连贯，说明身体没有力气、抵抗力差。"}, {"text": "很健康", "is_correct": false, "explanation": "语义：“身体很健康”与后文“常常生病”矛盾。"}, {"text": "很严肃", "is_correct": false, "explanation": "搭配：“严肃”形容态度或神情，不能用来形容身体。"}, {"text": "很亮", "is_correct": false, "explanation": "搭配：“亮”形容光线或颜色，不能用来形容身体。"}], "explanations": {"很弱": "正确。“身体很弱，常常生病”前后连贯，说明身体没有力气、抵抗力差。", "很健康": "语义：“身体很健康”与后文“常常生病”矛盾。", "很严肃": "搭配：“严肃”形容态度或神情，不能用来形容身体。", "很亮": "搭配：“亮”形容光线或颜色，不能用来形容身体。"}, "sentence_index": 6, "correct_answer": "很弱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆自行车的速度很弱，我们一下就超过了它。", "explanation": "这里应该用〈慢〉。“很弱”说力量或能力，速度的快慢要说“慢”。"}, {"text": "这袋大米很弱，我一只手就能拎起来。", "explanation": "这里应该用〈轻〉。“很弱”说力量或能力，物体的分量要说“轻”。"}, {"text": "今天的天气很弱，我们去游泳吧。", "explanation": "这里应该用〈热〉。“很弱”说人的力量或能力，天气的冷热要说“热”或“冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妈妈最近身体很弱得，常常咳嗽。", "corrected_sentence": "我妈妈最近身体很弱，常常咳嗽。", "error_description": "错误：“很弱得”，正确：“很弱，”。“很弱”后不能直接接“得”，应用逗号断开。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很弱得连床都下不了。", "corrected_sentence": "她弱得连床都下不了。", "error_description": "错误：多了“很”，“很弱得”不通。“弱得”后面接程度补语时，“很”不能放在“弱得”前面。正确说法是“弱得连床都下不了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9136fcd-0856-4303-8c90-0ba55b2d4564') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
