INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用了本可以节省的东西，比如水、食物或时间，没有用在有好处的地方。", "primary_collocate": null, "pronunciation": "làng fèi zī yuán", "ipa": "lɑŋ˥˩ feɪ˥˩ tsɹ̩˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "洗手时一直开着水，就是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃不完的饭菜倒掉，也是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没人的房间还开着灯，浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别让电视一直开着，那样浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用一次就扔的东西太多，浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说用完纸的正反面再扔，这样不浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路灯白天还亮着，真是浪费资源。", "target_word": "浪费资源", "complexity_tier": "T3", "furigana": "làng fèi zī yuán", "sentence_source": "generated"}, {"text": "空调开得太冷，既花钱又浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要节约用水，不能浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水龙头坏了，一直滴水，浪费资源。", "target_word": "浪费资源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪費資源", "label": "繁体"}], "register": "中性", "sense_fingerprint": "浪费资源：把水、食物、电等本可节省的东西白白用掉，没有用在有益的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费资源", "is_correct": true, "explanation": "正确：“洗手时一直开着水，就是浪费资源”，是对这种做法的评价。"}, {"text": "节约资源", "is_correct": false, "explanation": "语义：“节约资源”与“一直开着水”的做法相反，不能作为对这种做法的评价。"}, {"text": "珍惜用水", "is_correct": false, "explanation": "语义：“珍惜用水”与“一直开着水”的做法矛盾，不能作为评价。"}, {"text": "合理用水", "is_correct": false, "explanation": "搭配：“合理用水”作评价时与“一直开着水”的情境不搭配，不能用“就是”引出。"}], "explanations": {"浪费资源": "正确：“洗手时一直开着水，就是浪费资源”，是对这种做法的评价。", "节约资源": "语义：“节约资源”与“一直开着水”的做法相反，不能作为对这种做法的评价。", "珍惜用水": "语义：“珍惜用水”与“一直开着水”的做法矛盾，不能作为评价。", "合理用水": "搭配：“合理用水”作评价时与“一直开着水”的情境不搭配，不能用“就是”引出。"}, "sentence_index": 0, "correct_answer": "浪费资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要浪费资源，每个人都应该做到。", "explanation": "这里应该用〈节约用水〉。浪费资源指白白用掉东西，与节约用水的意思相反。"}, {"text": "浪费资源，人人有责。", "explanation": "这里应该用〈保护水资源〉。浪费资源指白白耗用，与保护的意思相反，不能用来倡导人人有责。"}, {"text": "大家要浪费资源，不要剩饭。", "explanation": "这里应该用〈珍惜粮食〉。浪费资源指白白用掉东西，表示爱惜时要用珍惜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费资源", "is_correct": true, "explanation": "正确：“路灯白天还亮着，真是浪费资源”，是对这种情况的批评。"}, {"text": "明智之举", "is_correct": false, "explanation": "语义：“明智之举”是褒义评价，与“白天还亮着”的批评语气相反。"}, {"text": "物尽其用", "is_correct": false, "explanation": "语义：“物尽其用”表示充分利用，与“白天还亮着”的情况相反。"}, {"text": "有效利用", "is_correct": false, "explanation": "搭配：“有效利用”作评价时与“白天还亮着”的批评语境不搭配。"}], "explanations": {"浪费资源": "正确：“路灯白天还亮着，真是浪费资源”，是对这种情况的批评。", "明智之举": "语义：“明智之举”是褒义评价，与“白天还亮着”的批评语气相反。", "物尽其用": "语义：“物尽其用”表示充分利用，与“白天还亮着”的情况相反。", "有效利用": "搭配：“有效利用”作评价时与“白天还亮着”的批评语境不搭配。"}, "sentence_index": 6, "correct_answer": "浪费资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一向浪费资源，吃剩的饭菜都打包带走。", "explanation": "这里应该用〈节俭〉。浪费资源指白白用掉东西，与“吃剩的饭菜都打包带走”的做法相反。"}, {"text": "随手关灯可以浪费资源。", "explanation": "这里应该用〈省电〉。浪费资源指白白耗用，随手关灯正是省电的做法，要用省电。"}, {"text": "这套设备浪费资源，很划算。", "explanation": "这里应该用〈循环使用〉。浪费资源指白白耗用，设备能循环使用就不是浪费，要用循环使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这样把白白浪费资源，太可惜了。", "corrected_sentence": "这样白白浪费资源，太可惜了。", "error_description": "把字误用：“把”后必须接名词性受事，“白白”是副词，不能作宾语。应去掉“把”，说“这样白白浪费资源”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别让水龙头一直滴水，那样被浪费资源。", "corrected_sentence": "别让水龙头一直滴水，那样浪费资源。", "error_description": "被字误用：“浪费资源”是动宾词组，“资源”已作宾语，动词前不能再加“被”。若要用被动，须让“资源”作主语，如“资源被白白浪费”。应去掉“被”，说“那样浪费资源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
