INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事做了几回。", "primary_collocate": null, "pronunciation": "cì shù", "ipa": "tsʰɹ̩˥˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他数了数自己跳绳的次数。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天刷牙的次数不要太少。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月我坐飞机的次数不多。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试的次数多了，他就不紧张了。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登录错误的次数太多，要等一会儿再试。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸问我这周打电话回家的次数。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机用的次数多了，也会坏。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看这部电影的次数已经超过十次。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请写下你每天喝水的次数。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的次数越多，经验就越丰富。", "target_word": "次数", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "次数：一件事做了几回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5792deb8-9cc6-4fa7-84dc-c6523834ed92') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数（cì shù）：一件事做了几回，是本题要听辨的正确词。"}, {"text": "字数", "is_correct": false, "explanation": "字数（zì shù）：字的数目。zì 与 cì 声母不同（z 与 c），声调相同，意思是字数。"}, {"text": "词数", "is_correct": false, "explanation": "词数（cí shù）：词的数目。cí（第二声）与 cì（第四声）声调不同，意思是词数。"}, {"text": "质数", "is_correct": false, "explanation": "质数（zhì shù）：即素数。zhì 与 cì 声母不同（zh 与 c），声调相同，意思是质数。"}, {"text": "齿数", "is_correct": false, "explanation": "齿数（chǐ shù）：齿轮的齿的数目。chǐ（第三声）与 cì（第四声）声母不同（ch 与 c），声调也不同。"}], "explanations": {"次数": "次数（cì shù）：一件事做了几回，是本题要听辨的正确词。", "字数": "字数（zì shù）：字的数目。zì 与 cì 声母不同（z 与 c），声调相同，意思是字数。", "词数": "词数（cí shù）：词的数目。cí（第二声）与 cì（第四声）声调不同，意思是词数。", "质数": "质数（zhì shù）：即素数。zhì 与 cì 声母不同（zh 与 c），声调相同，意思是质数。", "齿数": "齿数（chǐ shù）：齿轮的齿的数目。chǐ（第三声）与 cì（第四声）声母不同（ch 与 c），声调也不同。"}, "sentence_index": null, "correct_answer": "次数"}, "level_3": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数：指跳绳的回数，“数”的对象正是次数，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：跳绳的价格不能用“数”来计数，与“数自己跳绳的……”不搭。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是称出来的，不能用“数”来计数，与“数……的次数”句意不合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：跳绳没有可以被数出来的味道，句意不通。"}], "explanations": {"次数": "次数：指跳绳的回数，“数”的对象正是次数，句意通顺。", "价格": "搭配：跳绳的价格不能用“数”来计数，与“数自己跳绳的……”不搭。", "重量": "语义：重量是称出来的，不能用“数”来计数，与“数……的次数”句意不合。", "味道": "语义：跳绳没有可以被数出来的味道，句意不通。"}, "sentence_index": 0, "correct_answer": "次数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的次数越来越大。", "explanation": "这里应该用〈年龄〉。次数指回数，不能用来指人的岁数。"}, {"text": "这件衣服的次数很贵。", "explanation": "这里应该用〈价格〉。次数指回数，不能用来说东西的贵贱。"}, {"text": "这条路的次数很远。", "explanation": "这里应该用〈距离〉。次数指回数，不能用来形容路的远近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "次数", "is_correct": true, "explanation": "次数：指使用洗衣机的回数，与“用”搭配，“用得多”说的是次数。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“用”的对象是洗衣机之类的东西，不能说“用的学历多了”。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格属于人，洗衣机没有性格，“用的性格多了”句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人或动物的身体重量，洗衣机用的不能是体重。"}], "explanations": {"次数": "次数：指使用洗衣机的回数，与“用”搭配，“用得多”说的是次数。", "学历": "搭配：“用”的对象是洗衣机之类的东西，不能说“用的学历多了”。", "性格": "语义：性格属于人，洗衣机没有性格，“用的性格多了”句意不通。", "体重": "语义：体重指人或动物的身体重量，洗衣机用的不能是体重。"}, "sentence_index": 6, "correct_answer": "次数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这朵花的次数很鲜艳。", "explanation": "这里应该用〈颜色〉。次数指回数，不能用来形容颜色。"}, {"text": "他的次数考了一百分。", "explanation": "这里应该用〈分数〉。次数指回数，不能用来说考试得了多少分。"}, {"text": "这个箱子的次数很重，搬不动。", "explanation": "这里应该用〈重量〉。次数指回数，不能用来说东西的轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每周跑步的次数比以前大了。", "corrected_sentence": "我每周跑步的次数比以前多了。", "error_description": "错在“次数”的补语。次数的增减要用“多”“少”来形容，不能用“大”；“次数大”不成立，应改为“次数多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师建议我减少熬夜得次数。", "corrected_sentence": "老师建议我减少熬夜的次数。", "error_description": "错在“的”误作“得”。“得”用于动词、形容词之后引出补语，不能直接修饰名词“次数”；修饰名词应用“的”，说“熬夜的次数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd6b2804-66fc-4206-983b-a3cd29af52b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
