INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26206, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "需要使用某种工具、物品或场所。", "primary_collocate": null, "pronunciation": "yào yòng", "ipa": "jɑʊ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "修车要用工具。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爬山要用的东西都在包里。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要用手机吗？", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本词典我明天要用，你先别借走。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写作业要用铅笔，不要用钢笔。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃牛排要用刀和叉子。", "target_word": "要用", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "画画儿要用的颜色，我已经买好了。", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做这个实验要用哪些东西？", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今晚我要用厨房，请你别占着。", "target_word": "要用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写中文要用拼音输入法吗？", "target_word": "要用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不要用", "label": "否定"}], "register": "中性", "sense_fingerprint": "需要使用某种工具或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab33c06f-7df9-4a5c-b347-e98431a3920c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26206, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。yào yòng 即“需要使用某种工具或东西”。"}, {"text": "套用", "is_correct": false, "explanation": "tào（第四声）与 yào（第四声）声母不同，意思是套用、照搬。"}, {"text": "调用", "is_correct": false, "explanation": "diào（第四声）与 yào（第四声）声母不同，意思是调配、取用。"}, {"text": "夜用", "is_correct": false, "explanation": "yè（第四声）与 yào（第四声）韵母不同（e 与 ao），意思是夜间使用。"}], "explanations": {"要用": "正确答案。yào yòng 即“需要使用某种工具或东西”。", "套用": "tào（第四声）与 yào（第四声）声母不同，意思是套用、照搬。", "调用": "diào（第四声）与 yào（第四声）声母不同，意思是调配、取用。", "夜用": "yè（第四声）与 yào（第四声）韵母不同（e 与 ao），意思是夜间使用。"}, "sentence_index": null, "correct_answer": "要用"}, "level_3": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。修车需要使用工具，符合句意。"}, {"text": "要吃", "is_correct": false, "explanation": "语义：“吃”指进食，修车时不会吃工具，与句意不符。"}, {"text": "要穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物、鞋子等，不能说“穿工具”。"}, {"text": "要玩", "is_correct": false, "explanation": "语义：“玩”表示娱乐，与修车的工作场景不符。"}], "explanations": {"要用": "正确答案。修车需要使用工具，符合句意。", "要吃": "语义：“吃”指进食，修车时不会吃工具，与句意不符。", "要穿": "搭配：“穿”的宾语是衣物、鞋子等，不能说“穿工具”。", "要玩": "语义：“玩”表示娱乐，与修车的工作场景不符。"}, "sentence_index": 0, "correct_answer": "要用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本词典要用还给图书馆。", "explanation": "这里应该用〈归还〉。“要用”表示需要使用某物，不能用来表示归还物品这一动作。"}, {"text": "这个房间要用我一个人打扫。", "explanation": "这里应该用〈需要〉。“要用”后接的是用来做事的工具或资源，不能把「我」当作被用来打扫的对象。"}, {"text": "这张桌子要用整齐。", "explanation": "这里应该用〈保持〉。“要用”后接的是可以使用的东西，「整齐」是状态，不能被“用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26206, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。yào yòng 即“需要使用某种工具或东西”。"}, {"text": "好用", "is_correct": false, "explanation": "hǎo（第三声）与 yào（第四声）声母与声调都不同，意思是容易使用、顺手。"}, {"text": "少用", "is_correct": false, "explanation": "shǎo（第三声）与 yào（第四声）声母与声调都不同，意思是减少使用。"}, {"text": "要弄", "is_correct": false, "explanation": "yàonòng 中第二音节 nòng 与 yòng 声母不同，意思是摆弄、戏耍。"}], "explanations": {"要用": "正确答案。yào yòng 即“需要使用某种工具或东西”。", "好用": "hǎo（第三声）与 yào（第四声）声母与声调都不同，意思是容易使用、顺手。", "少用": "shǎo（第三声）与 yào（第四声）声母与声调都不同，意思是减少使用。", "要弄": "yàonòng 中第二音节 nòng 与 yòng 声母不同，意思是摆弄、戏耍。"}, "sentence_index": null, "correct_answer": "要用"}, "level_3": {"options": [{"text": "要用", "is_correct": true, "explanation": "正确答案。“要用的颜色”指画画儿时需要用到的颜色，符合句意。"}, {"text": "要喝", "is_correct": false, "explanation": "语义：“喝”指饮用，颜色不能喝，与画画儿的语境不合。"}, {"text": "要睡", "is_correct": false, "explanation": "语义：“睡”与画画儿的行为无关，颜色不能用来睡，句意不通。"}, {"text": "要唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲等，不能说“唱颜色”。"}], "explanations": {"要用": "正确答案。“要用的颜色”指画画儿时需要用到的颜色，符合句意。", "要喝": "语义：“喝”指饮用，颜色不能喝，与画画儿的语境不合。", "要睡": "语义：“睡”与画画儿的行为无关，颜色不能用来睡，句意不通。", "要唱": "搭配：“唱”的宾语是歌曲等，不能说“唱颜色”。"}, "sentence_index": 6, "correct_answer": "要用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他要用我去洗碗。", "explanation": "这里应该用〈让〉。“要用”表示需要使用某物，不能用来指派人去做家务。"}, {"text": "他要用一双鞋去参加比赛。", "explanation": "这里应该用〈穿〉。“要用”表示需要使用某物，「穿」是另一个动作，不能用“用”来表示穿鞋这一行为。"}, {"text": "老板要用他的孩子去开会。", "explanation": "这里应该用〈带〉。“要用”后接的是可以拿来使用的东西，不能把“孩子”当作工具去开会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "修这台机器要用过螺丝刀。", "corrected_sentence": "修这台机器要用螺丝刀。", "error_description": "错误：“要用过”。正确：“要用”。“要”表示需要或打算，与表示经历的“过”不能同用，应去掉“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我明天要用了电脑写作业。", "corrected_sentence": "我明天要用电脑写作业。", "error_description": "错误：“要用了”。正确：“要用”。“明天”指将来，表示将来需要使用时，“用”后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760e7e92-cd9a-4aef-93a8-ca4878930c9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
