INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放好，让它们变得整齐。", "primary_collocate": null, "pronunciation": "zhěng lǐ", "ipa": "ʈʂɤŋ˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "周末我在家整理房间，把书放回书架。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在整理衣柜里的冬衣。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书包整理得很整齐。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡觉前都会整理书桌。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的玩具整理好，再去吃饭。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我们花了两天整理新房子里的箱子。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在车库里整理工具，每样都放回原位。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们把教室里的桌椅整理得整整齐齐。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“下课前，请大家整理自己的书包。”", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服太乱了，我想整理一下，分类放好。", "target_word": "整理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "整理了", "label": "体标"}, {"form": "整理过", "label": "体标"}, {"form": "整理整理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "整理：把房间、书桌、衣物等实物摆放整齐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d983af5-8a29-4125-88b7-ed3ab525497b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "整理", "is_correct": true, "explanation": "整理（zhěng lǐ）：把东西放好，使它们变得整齐。"}, {"text": "真理", "is_correct": false, "explanation": "真理（zhēn lǐ）与整理的韵尾不同（-n 与 -ng），声调也不同，意思是真理。"}, {"text": "城里", "is_correct": false, "explanation": "城里（chéng lǐ）与整理的声母和声调不同（zh/ch，第三声/第二声），意思是城市里面。"}, {"text": "整体", "is_correct": false, "explanation": "整体（zhěng tǐ）与整理的第二个音节不同（tǐ 与 lǐ 声母不同），意思是整个、全体。"}, {"text": "生理", "is_correct": false, "explanation": "生理（shēng lǐ）与整理的声母和声调不同（sh/zh），意思是生命机体的机能。"}], "explanations": {"整理": "整理（zhěng lǐ）：把东西放好，使它们变得整齐。", "真理": "真理（zhēn lǐ）与整理的韵尾不同（-n 与 -ng），声调也不同，意思是真理。", "城里": "城里（chéng lǐ）与整理的声母和声调不同（zh/ch，第三声/第二声），意思是城市里面。", "整体": "整体（zhěng tǐ）与整理的第二个音节不同（tǐ 与 lǐ 声母不同），意思是整个、全体。", "生理": "生理（shēng lǐ）与整理的声母和声调不同（sh/zh），意思是生命机体的机能。"}, "sentence_index": null, "correct_answer": "整理"}, "level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理房间，把书放回书架”，把物品摆放整齐，符合句意。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量房间的尺寸与“把书放回书架”的动作不相干。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”针对供人观看的场所或展品，不用于在家里收拾房间的动作。"}, {"text": "出租", "is_correct": false, "explanation": "语义：出租房间与“把书放回书架”的动作和整理房间的意思都不符。"}], "explanations": {"整理": "正确：“整理房间，把书放回书架”，把物品摆放整齐，符合句意。", "测量": "语义：测量房间的尺寸与“把书放回书架”的动作不相干。", "参观": "搭配：“参观”针对供人观看的场所或展品，不用于在家里收拾房间的动作。", "出租": "语义：出租房间与“把书放回书架”的动作和整理房间的意思都不符。"}, "sentence_index": 0, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把坏了的电视整理了一下。", "explanation": "这里应该用〈修理〉。整理是把物品摆放有序，不能表示修好坏掉的电器，要用“修理”。"}, {"text": "妈妈正在厨房整理饭。", "explanation": "这里应该用〈煮〉。整理用于物品或资料，煮饭要用“煮”。"}, {"text": "医生在整理病人。", "explanation": "这里应该用〈治疗〉。整理不用于人，治疗病人要用“治疗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "整理", "is_correct": true, "explanation": "正确：“整理工具，每样都放回原位”，使物品有序，符合句意。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售工具与“每样都放回原位”的结果相矛盾。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不能用于工具。"}, {"text": "涂抹", "is_correct": false, "explanation": "搭配：“涂抹”的对象是颜料、药膏等，与“工具”和“放回原位”都不搭配。"}], "explanations": {"整理": "正确：“整理工具，每样都放回原位”，使物品有序，符合句意。", "出售": "语义：出售工具与“每样都放回原位”的结果相矛盾。", "烹饪": "搭配：“烹饪”的对象是食物，不能用于工具。", "涂抹": "搭配：“涂抹”的对象是颜料、药膏等，与“工具”和“放回原位”都不搭配。"}, "sentence_index": 6, "correct_answer": "整理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在纸上整理了一只猫。", "explanation": "这里应该用〈画〉。整理不表示绘画，在纸上画猫要用“画”。"}, {"text": "他在比赛中整理了一个进球。", "explanation": "这里应该用〈踢进〉。整理用于摆放物品，不能表示得分；射门进球要说“踢进”。"}, {"text": "他整理了一杯水。", "explanation": "这里应该用〈喝〉。整理用于物品或资料，喝水要用“喝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把厨房的碗筷整理的井井有条。", "corrected_sentence": "妈妈把厨房的碗筷整理得井井有条。", "error_description": "错误：“整理的井井有条”。“整理”后接表示结果或程度的补语时要用助词“得”，不能用“的”。正确形式是“整理得井井有条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐正在整理过她的书架。", "corrected_sentence": "姐姐正在整理她的书架。", "error_description": "错误：“正在整理过”。“正在”表示动作正在进行，“过”表示曾经经历，二者矛盾。正确形式是“正在整理她的书架”，去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱衣", "is_correct": true, "explanation": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。"}, {"text": "洗碗", "is_correct": false, "explanation": "洗碗是家务动作，与穿衣没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字是书写活动，与穿衣没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是运动方式，与穿衣没有反义关系。"}], "correct_answer": "脱衣", "explanations": {"脱衣": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。", "洗碗": "洗碗是家务动作，与穿衣没有反义关系。", "写字": "写字是书写活动，与穿衣没有反义关系。", "游泳": "游泳是运动方式，与穿衣没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱衣", "is_correct": true, "explanation": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。"}, {"text": "上课", "is_correct": false, "explanation": "上课是学习活动，与穿衣没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "画画是绘画活动，与穿衣没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞是娱乐活动，与穿衣没有反义关系。"}], "correct_answer": "脱衣", "explanations": {"脱衣": "脱衣：把穿在身上的衣服脱下，与“穿衣”意义相反。", "上课": "上课是学习活动，与穿衣没有反义关系。", "画画": "画画是绘画活动，与穿衣没有反义关系。", "跳舞": "跳舞是娱乐活动，与穿衣没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把衣服穿到身上。", "primary_collocate": null, "pronunciation": "chuān yī", "ipa": "ʈʂʰwan˥ i˥", "syllable_count": 2, "sentences": [{"text": "弟弟自己穿衣，不要妈妈帮。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮了，他慢慢起床穿衣。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗完澡，快点穿衣，别感冒。", "target_word": "穿衣", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他穿衣的动作很快，三分钟就出门了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学穿衣，常常把左右弄错。", "target_word": "穿衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在冷房间里穿衣，手都冻红了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他闭着眼睛穿衣，还想再睡一会儿。", "target_word": "穿衣", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶眼睛不好，穿衣要慢一点。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "起床后，他很快穿衣，吃了早饭就走了。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教孩子们怎样穿衣，怎样系鞋带。", "target_word": "穿衣", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "穿衣镜", "label": "复合"}, {"form": "穿衣打扮", "label": "复合"}], "register": "中性", "sense_fingerprint": "把衣服穿到身上的日常动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '434c0685-b138-4d57-a528-8792d79dfc37') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上。"}, {"text": "船医", "is_correct": false, "explanation": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。"}, {"text": "传艺", "is_correct": false, "explanation": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。"}, {"text": "春衣", "is_correct": false, "explanation": "chūn 与 chuān 韵母不同（-un 与 -an），意思是春天穿的衣服。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上。", "船医": "chuán（第二声）与 chuān（第一声）声调不同，意思是船上的医生。", "传艺": "chuán 与 chuān 声调不同，yì 与 yī 声调也不同，意思是传授技艺。", "春衣": "chūn 与 chuān 韵母不同（-un 与 -an），意思是春天穿的衣服。"}, "sentence_index": null, "correct_answer": "穿衣"}, "level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，“自己穿衣”符合语境。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”是成年人的事，“弟弟自己结婚，不要妈妈帮”不通。"}, {"text": "天气", "is_correct": false, "explanation": "词性：“天气”是名词，不能放在“自己……”之后作动作，“自己天气”不通。"}, {"text": "书包", "is_correct": false, "explanation": "词性：“书包”是名词，“弟弟自己书包，不要妈妈帮”不成立。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，“自己穿衣”符合语境。", "结婚": "语义：“结婚”是成年人的事，“弟弟自己结婚，不要妈妈帮”不通。", "天气": "词性：“天气”是名词，不能放在“自己……”之后作动作，“自己天气”不通。", "书包": "词性：“书包”是名词，“弟弟自己书包，不要妈妈帮”不成立。"}, "sentence_index": 0, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "游泳前他要先穿衣，再换上泳裤。", "explanation": "这里应该用〈脱衣〉。穿衣是把衣服穿到身上，游泳前要先脱衣，不能说“穿衣”。"}, {"text": "进屋后，他先穿衣，再坐下来。", "explanation": "这里应该用〈脱掉外套〉。穿衣是把衣服穿上，进屋后要先脱掉外套，不能说“穿衣”。"}, {"text": "他先穿衣，再洗了个热水澡。", "explanation": "这里应该用〈脱下衣服〉。穿衣是把衣服穿上，洗澡前要脱下衣服，不能说“穿衣”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿衣", "is_correct": true, "explanation": "穿衣：把衣服穿到身上，“闭着眼睛穿衣”符合语境。"}, {"text": "搬家", "is_correct": false, "explanation": "语义：“搬家”是大规模的搬迁，“闭着眼睛搬家”与早晨想再睡一会儿的情境不符。"}, {"text": "画画", "is_correct": false, "explanation": "语义：“画画”需要纸笔和创作，与“还想再睡一会儿”的早晨情境无关。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”是娱乐活动，不能与“闭着眼睛”加“还想再睡一会儿”组成合理的情境。"}], "explanations": {"穿衣": "穿衣：把衣服穿到身上，“闭着眼睛穿衣”符合语境。", "搬家": "语义：“搬家”是大规模的搬迁，“闭着眼睛搬家”与早晨想再睡一会儿的情境不符。", "画画": "语义：“画画”需要纸笔和创作，与“还想再睡一会儿”的早晨情境无关。", "跳舞": "语义：“跳舞”是娱乐活动，不能与“闭着眼睛”加“还想再睡一会儿”组成合理的情境。"}, "sentence_index": 6, "correct_answer": "穿衣"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先穿衣，再放进柜子里。", "explanation": "这里应该用〈叠〉。穿衣是把衣服穿到身上，应先把衣服叠好再放进柜子，不能说“穿衣”。"}, {"text": "妈妈在河边穿衣，然后晾在树上。", "explanation": "这里应该用〈洗衣服〉。穿衣是把衣服穿到身上，洗衣服才是把衣服弄干净，不能说“穿衣”。"}, {"text": "他在服装厂穿衣，每天能缝一百件衣服。", "explanation": "这里应该用〈缝〉。穿衣是把衣服穿到身上，不指缝制衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天冷了，妈妈给孩子穿衣一件小棉袄。", "corrected_sentence": "天冷了，妈妈给孩子穿一件小棉袄。", "error_description": "错误：「穿衣」是动宾结构，「衣」已是它的宾语，后面不能再直接带宾语「一件小棉袄」。正确说法是「穿一件小棉袄」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天很早就起来穿衣一件衣服。", "corrected_sentence": "他每天很早就起来穿一件衣服。", "error_description": "错误：「穿衣」是动宾结构，「衣」已是它的宾语，后面不能再直接带宾语。正确说法是删去多余的「衣」：「穿一件衣服」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38b62316-fb60-4504-9569-5044521d6b65') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
