INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "棉花是棉株果实中白色柔软的纤维，可以做成衣服和被子。", "primary_collocate": null, "pronunciation": "mián huā", "ipa": "mjɛn˧˥ xwa˥", "syllable_count": 2, "sentences": [{"text": "棉花是白色的，摸起来很软。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个枕头里面装着棉花。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把棉花做成了厚被子。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把摘下来的棉花晒干，再装进被子里。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士用棉花擦干净了我的手。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵棉花又白又大，像一朵云。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，奶奶用棉花做了一件厚衣服。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩喜欢摸软软的棉花。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服里面有棉花，所以很暖和。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一包棉花，想做个小枕头。", "target_word": "棉花", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一团棉花", "label": "量词"}, {"form": "一包棉花", "label": "量词"}], "register": "中性", "sense_fingerprint": "白色柔软的棉花，可做衣服和被子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d983af5-8a29-4125-88b7-ed3ab525497b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棉花", "is_correct": true, "explanation": "正确：“棉花”是白色的，摸起来很软。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头摸起来坚硬，不会很软。"}, {"text": "黑炭", "is_correct": false, "explanation": "体貌：黑炭是黑色的，不是白色的。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁是金属，不是白色柔软的东西。"}], "explanations": {"棉花": "正确：“棉花”是白色的，摸起来很软。", "石头": "体貌：石头摸起来坚硬，不会很软。", "黑炭": "体貌：黑炭是黑色的，不是白色的。", "钢铁": "语义：钢铁是金属，不是白色柔软的东西。"}, "sentence_index": 0, "correct_answer": "棉花"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈抱来一台棉花。", "explanation": "这里应该用〈包〉或〈团〉。“台”用于机器、电器等，棉花不能用“台”来数。"}, {"text": "床上放着一张棉花。", "explanation": "这里应该用〈团〉。“张”用于纸、床、桌子等平面的东西，棉花不能用“张”来数。"}, {"text": "他买了一副棉花。", "explanation": "这里应该用〈包〉。“副”用于成对或成套的东西，如手套、眼镜，棉花不能用“副”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棉花", "is_correct": true, "explanation": "正确：“棉花”又暖和又轻，可以用来做厚衣服。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：做衣服一般用布料或纤维，不说用木头做衣服。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土不能做衣服，也不是保暖的材料。"}, {"text": "砖", "is_correct": false, "explanation": "语义：砖又硬又重，不能用来做厚衣服。"}], "explanations": {"棉花": "正确：“棉花”又暖和又轻，可以用来做厚衣服。", "木头": "搭配：做衣服一般用布料或纤维，不说用木头做衣服。", "泥土": "语义：泥土不能做衣服，也不是保暖的材料。", "砖": "语义：砖又硬又重，不能用来做厚衣服。"}, "sentence_index": 6, "correct_answer": "棉花"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人买了棉花，要裁成床单。", "explanation": "这里应该用〈棉布〉。棉布是布料，可以裁剪；棉花是松散的纤维，不能裁。"}, {"text": "这条裤子破了，要用棉花缝一缝。", "explanation": "这里应该用〈棉线〉。缝补要用线，棉花是松散的纤维，不能用来缝。"}, {"text": "农民把棉花留下来，明年做种子。", "explanation": "这里应该用〈棉籽〉。留作种子的是棉籽，棉花是纤维，不能用来播种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这朵白色地棉花很软。", "corrected_sentence": "这朵白色的棉花很软。", "error_description": "修饰语错误：“白色”修饰名词“棉花”，应用“的”，不能用“地”。正确形式是“白色的棉花”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把棉花弹，做成了被子。", "corrected_sentence": "妈妈把棉花弹松了，做成了被子。", "error_description": "补语缺失：“把”字句中的动词“弹”后需要补语，应为“弹松了”；“把棉花弹”不完整。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
