INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纺织工业是造衣服和布的工厂。", "primary_collocate": null, "pronunciation": "fǎng zhī gōng yè", "ipa": "faŋ˨˩˦ ʈʂɨ˥˥ kʊŋ˥˥ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "纺织工业的车间里机器日夜不停地运转。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "姐姐大学毕业后在纺织工业的车间工作。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "纺织工业每天做出很多新布。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织工业的仓库里堆满了刚织好的布。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "纺织工业的机器需要定期加油和维护。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "妈妈年轻时在纺织工业的车间里做过工。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "我们参观了纺织工业的生产线，了解布的织造过程。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}, {"text": "纺织工业的工人把布一卷一卷放好。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织工业要用很多线来织布。", "target_word": "纺织工业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里的纺织工业吸纳了很多劳动力。", "target_word": "纺织工业", "complexity_tier": "T3", "furigana": "fǎngzhī gōngyè", "sentence_source": "generated"}], "morphological_forms": [{"form": "紡織工業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "纺织工业：做布和衣服的工厂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "银行", "is_correct": false, "explanation": "语义：银行没有生产车间，“机器日夜不停地运转”与之不合。"}, {"text": "纺织工业", "is_correct": true, "explanation": "正确：“纺织工业的车间”指造布、做衣服的工厂，机器日夜运转与之相合。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园没有机器运转的生产车间，句意说不通。"}, {"text": "政府", "is_correct": false, "explanation": "搭配：“车间”属于工厂类机构，不能说“政府的车间”。"}], "explanations": {"银行": "语义：银行没有生产车间，“机器日夜不停地运转”与之不合。", "纺织工业": "正确：“纺织工业的车间”指造布、做衣服的工厂，机器日夜运转与之相合。", "动物园": "语义：动物园没有机器运转的生产车间，句意说不通。", "政府": "搭配：“车间”属于工厂类机构，不能说“政府的车间”。"}, "sentence_index": 0, "correct_answer": "纺织工业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个纺织工业每年种很多小麦。", "explanation": "这里应该用〈农场〉。纺织工业是工厂，不能种植庄稼，种小麦要用农场。"}, {"text": "我每周末去纺织工业买书。", "explanation": "这里应该用〈书店〉。纺织工业是工厂，买书要去书店。"}, {"text": "商店里摆满了各种纺织工业。", "explanation": "这里应该用〈纺织品〉。商店摆放的是产品，不是行业名称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲没有生产线，“参观生产线”与“了解布的织造过程”无关。"}, {"text": "纺织工业", "is_correct": true, "explanation": "正确：“纺织工业的生产线”可以参观，与“了解布的织造过程”相合。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是生产线的对象，“参观动物的生产线”说不通。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“生产线”只与产品制造搭配，不能与“语言”搭配。"}], "explanations": {"歌曲": "语义：歌曲没有生产线，“参观生产线”与“了解布的织造过程”无关。", "纺织工业": "正确：“纺织工业的生产线”可以参观，与“了解布的织造过程”相合。", "动物": "语义：动物不是生产线的对象，“参观动物的生产线”说不通。", "语言": "搭配：“生产线”只与产品制造搭配，不能与“语言”搭配。"}, "sentence_index": 6, "correct_answer": "纺织工业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村子里的纺织工业每周都会演出一场。", "explanation": "这里应该用〈剧院〉。纺织工业是工厂，不会演出节目。"}, {"text": "村子里的孩子们都去纺织工业上学。", "explanation": "这里应该用〈学校〉。纺织工业是工厂，上学要去学校。"}, {"text": "村子里的纺织工业治好了很多病人。", "explanation": "这里应该用〈医院〉。纺织工业不能治病，治病救人的是医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "纺织工业们每天织出很多新布。", "corrected_sentence": "纺织工业每天织出很多新布。", "error_description": "错误：“们”只用于指人或有生命的名词，不能接在“纺织工业”后面表示复数。正确：去掉“们”，说“纺织工业每天织出很多新布”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里把一只纺织工业搬到了城外。", "corrected_sentence": "村里把一个纺织工业搬到了城外。", "error_description": "错误：“只”只用于动物或成对的东西，不能用来计量“纺织工业”。正确：改用“个”，说“村里把一个纺织工业搬到了城外”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
