INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26229, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "消耗水，使水量减少。", "primary_collocate": null, "pronunciation": "hào shuǐ", "ipa": "xɑʊ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "洗澡的时间太长，很耗水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新马桶用水很少，不太耗水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浇花耗水不多，一天一杯就够了。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，洗车比洗衣服更耗水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器很耗水，一小时要用好几桶水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一台很耗水的机器，一小时用掉很多水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种菜很耗水，天天都要浇水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在干旱的地方，耗水的工作要少做。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳池每天都在耗水，因为水会慢慢变少。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刷牙时关上水龙头，可以少耗水。", "target_word": "耗水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "耗水了", "label": "体标"}, {"form": "耗水量", "label": "复合"}, {"form": "高耗水", "label": "复合"}], "register": "书面", "sense_fingerprint": "耗水：用水时把水用掉、使水变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8d983af5-8a29-4125-88b7-ed3ab525497b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26229, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：耗水（hào shuǐ），指用水时把水用掉、使水变少。"}, {"text": "汗水", "is_correct": false, "explanation": "hàn（第四声）与 hào（第四声）韵母不同（-an 与 -ao），意思是汗水。"}, {"text": "冒水", "is_correct": false, "explanation": "mào（第四声）与 hào（第四声）声母不同（m 与 h），意思是水往外冒。"}, {"text": "倒水", "is_correct": false, "explanation": "dào（第四声）与 hào（第四声）声母不同（d 与 h），意思是把水倒出。"}], "explanations": {"耗水": "正确：耗水（hào shuǐ），指用水时把水用掉、使水变少。", "汗水": "hàn（第四声）与 hào（第四声）韵母不同（-an 与 -ao），意思是汗水。", "冒水": "mào（第四声）与 hào（第四声）声母不同（m 与 h），意思是水往外冒。", "倒水": "dào（第四声）与 hào（第四声）声母不同（d 与 h），意思是把水倒出。"}, "sentence_index": null, "correct_answer": "耗水"}, "level_3": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：耗水指用水使水量减少，与“洗澡的时间太长”的后果相符。"}, {"text": "节水", "is_correct": false, "explanation": "语义：洗澡时间太长与节水的含义矛盾，句意相反。"}, {"text": "保温", "is_correct": false, "explanation": "搭配：「保温」多用于物品或容器，不用来形容洗澡的时间。"}, {"text": "漏水", "is_correct": false, "explanation": "搭配：「漏水」说的是设备或管道的状态，不能用来形容洗澡的时间。"}], "explanations": {"耗水": "正确：耗水指用水使水量减少，与“洗澡的时间太长”的后果相符。", "节水": "语义：洗澡时间太长与节水的含义矛盾，句意相反。", "保温": "搭配：「保温」多用于物品或容器，不用来形容洗澡的时间。", "漏水": "搭配：「漏水」说的是设备或管道的状态，不能用来形容洗澡的时间。"}, "sentence_index": 0, "correct_answer": "耗水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈提醒我们要耗水。", "explanation": "这里应该用〈节约〉。耗水表示用水使水量减少，与“提醒我们”的节水意图相反。"}, {"text": "这台电脑每天耗水很多，要注意节约。", "explanation": "这里应该用〈耗电〉。电脑消耗的是电，不耗水。"}, {"text": "水库在雨季耗水，水位会上升。", "explanation": "这里应该用〈蓄水〉。耗水使水量减少，与“水位会上升”的结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26229, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耗水", "is_correct": true, "explanation": "正确：耗水指消耗用水，与“天天都要浇水”的需要相符。"}, {"text": "耐旱", "is_correct": false, "explanation": "语义：耐旱指能忍受缺水，与“天天都要浇水”矛盾。"}, {"text": "怕水", "is_correct": false, "explanation": "语义：怕水与“天天都要浇水”矛盾，菜不会怕水还要天天浇。"}, {"text": "通风", "is_correct": false, "explanation": "搭配：「通风」多用于房间或空间，不说“种菜很通风”。"}], "explanations": {"耗水": "正确：耗水指消耗用水，与“天天都要浇水”的需要相符。", "耐旱": "语义：耐旱指能忍受缺水，与“天天都要浇水”矛盾。", "怕水": "语义：怕水与“天天都要浇水”矛盾，菜不会怕水还要天天浇。", "通风": "搭配：「通风」多用于房间或空间，不说“种菜很通风”。"}, "sentence_index": 6, "correct_answer": "耗水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作很耗水，每天下班都很累。", "explanation": "这里应该用〈耗力〉。耗水指消耗水资源，不能用于工作或精力的消耗。"}, {"text": "下大雨时要及时耗水，免得积水。", "explanation": "这里应该用〈排水〉。耗水是用掉水、使水减少，与“免得积水”的目的不符。"}, {"text": "工厂在河边耗水，再送到车间。", "explanation": "这里应该用〈取水〉。耗水表示水被用掉，不表示从河边把水取来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农场里的灌溉系统了耗水，要尽量少用。", "corrected_sentence": "农场里的灌溉系统很耗水，要尽量少用。", "error_description": "虚词错误：程度副词“很”误写为“了”，“了”不能放在主语与“耗水”之间；正确形式为“很耗水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器每小时耗水五十个，比旧的少很多。", "corrected_sentence": "这台机器每小时耗水五十升，比旧的少很多。", "error_description": "错误形式：“耗水五十个”；正确形式：“耗水五十升”。水以“升”“吨”计量，“个”不能用于水。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e25c990b-e1f4-477c-9a45-a1d8b0daf464') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
