INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "在某处。", "primary_collocate": null, "pronunciation": "wèi yú", "ipa": "weɪ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "邮局位于学校旁边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的楼位于路口。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店位于大桥南边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的教室位于三楼。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市位于地铁站附近。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖位于城市西面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的办公室位于一楼。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市位于长江边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小镇位于山的另一边。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店位于公园对面。", "target_word": "位于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在某个地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "未雨", "is_correct": false, "explanation": "未雨（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是没有下雨。"}, {"text": "维语", "is_correct": false, "explanation": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。"}, {"text": "位移", "is_correct": false, "explanation": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。"}, {"text": "卫浴", "is_correct": false, "explanation": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "未雨": "未雨（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是没有下雨。", "维语": "维语（wéi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是维吾尔语。", "位移": "位移（wèi yí）与位于（wèi yú）只有韵母不同（yí 与 yú），意思是物体位置的改变。", "卫浴": "卫浴（wèi yù）与位于（wèi yú）第二个音节声调不同（yù 第四声，yú 第二声），意思是卫生间和浴室。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“邮局在学校旁边”的意思相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”的主语须是人，邮局不能散步。"}, {"text": "蹲", "is_correct": false, "explanation": "体貌：“蹲”是人或动物的身体姿态，邮局不能蹲。"}, {"text": "驻守", "is_correct": false, "explanation": "搭配：“驻守”的主语多为军队，不说“邮局驻守”。"}], "explanations": {"位于": "位于表示处在某个位置，与“邮局在学校旁边”的意思相符。", "散步": "语义：“散步”的主语须是人，邮局不能散步。", "蹲": "体貌：“蹲”是人或动物的身体姿态，邮局不能蹲。", "驻守": "搭配：“驻守”的主语多为军队，不说“邮局驻守”。"}, "sentence_index": 0, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议位于下午三点。", "explanation": "这里应该用〈在〉。位于只说空间位置，说时间要用“在”。"}, {"text": "妈妈位于窗边。", "explanation": "这里应该用〈站〉。位于只说事物的位置，人站立要用站。"}, {"text": "奶奶位于乡下。", "explanation": "这里应该用〈住〉。位于说事物或机构的位置，人居住要用住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于（wèi yú）表示处在某个地方或位置，是正确答案。"}, {"text": "谓语", "is_correct": false, "explanation": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。"}, {"text": "未愈", "is_correct": false, "explanation": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。"}, {"text": "微雨", "is_correct": false, "explanation": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}], "explanations": {"位于": "位于（wèi yú）表示处在某个地方或位置，是正确答案。", "谓语": "谓语（wèi yǔ）与位于只有第二个音节声调不同（yǔ 第三声，yú 第二声），意思是句子中说明主语的部分。", "未愈": "未愈（wèi yù）与位于第二个音节声调不同（yù 第四声，yú 第二声），意思是伤病还没有好。", "微雨": "微雨（wēi yǔ）两个音节的声调都与位于（wèi yú）不同，意思是小雨。"}, "sentence_index": null, "correct_answer": "位于"}, "level_3": {"options": [{"text": "位于", "is_correct": true, "explanation": "位于表示处在某个位置，与“办公室在一楼”的意思相符。"}, {"text": "生活", "is_correct": false, "explanation": "语义：“生活”要求人作主语，办公室不能生活。"}, {"text": "发生", "is_correct": false, "explanation": "语义：“发生”指事件出现，办公室是处所，不能发生。"}, {"text": "驻扎", "is_correct": false, "explanation": "搭配：“驻扎”多指军队，不说“办公室驻扎”。"}], "explanations": {"位于": "位于表示处在某个位置，与“办公室在一楼”的意思相符。", "生活": "语义：“生活”要求人作主语，办公室不能生活。", "发生": "语义：“发生”指事件出现，办公室是处所，不能发生。", "驻扎": "搭配：“驻扎”多指军队，不说“办公室驻扎”。"}, "sentence_index": 6, "correct_answer": "位于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫位于沙发上。", "explanation": "这里应该用〈躺〉。位于说事物的位置，动物躺卧要用躺。"}, {"text": "这个学校位于很多老师。", "explanation": "这里应该用〈有〉。位于说具体位置，“很多老师”是人员，要用有。"}, {"text": "他位于椅子上。", "explanation": "这里应该用〈坐〉。位于只用于事物或机构的位置，人坐着要用坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家药店位于在医院旁边。", "corrected_sentence": "这家药店位于医院旁边。", "error_description": "错误：“位于”后面又加了“在”，写成“位于在”。“位于”本身已表示处在某处，不能再加“在”，应去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市位于了地铁站对面。", "corrected_sentence": "这家超市位于地铁站对面。", "error_description": "错误：“位于”后面多加了“了”，写成“位于了”。“位于”表示处在某处，是静态动词，不能加“了”，应去掉“了”，正确的是“这家超市位于地铁站对面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
