INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把棉花或毛线做成布。", "primary_collocate": null, "pronunciation": "fǎng zhī", "ipa": "faŋ˨˩ ʈʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "奶奶年轻时在家纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我学纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织要用棉花和毛线。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就喜欢纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人做了一辈子纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纺织很慢，要花很多时间。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的女人都会纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会纺织吗？", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天花两个小时做纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用手工做纺织。", "target_word": "纺织", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "纺织品", "label": "复合"}, {"form": "纺织厂", "label": "复合"}], "register": "通用", "sense_fingerprint": "用棉花或毛线做成布的手工活儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4173360d-5258-4945-b596-63a93b4b335e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26240, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确答案：纺织（fǎng zhī），指把棉花或毛线做成布。"}, {"text": "仿制", "is_correct": false, "explanation": "仿制（fǎng zhì）与纺织只有第二个音节声调不同（zhì 第四声，zhī 第一声），意思是照着样子制造。"}, {"text": "放置", "is_correct": false, "explanation": "放置（fàng zhì）与纺织两个音节的声调都不同，意思是摆放、安置。"}, {"text": "防止", "is_correct": false, "explanation": "防止（fáng zhǐ）与纺织两个音节的声调都不同，意思是提前避免某事发生。"}, {"text": "防治", "is_correct": false, "explanation": "防治（fáng zhì）与纺织两个音节的声调都不同，意思是预防并治理（疾病、灾害）。"}, {"text": "反之", "is_correct": false, "explanation": "反之（fǎn zhī）只把第一个音节的韵尾由 ng 换成 n，声调不变，意思是相反地。"}], "explanations": {"纺织": "正确答案：纺织（fǎng zhī），指把棉花或毛线做成布。", "仿制": "仿制（fǎng zhì）与纺织只有第二个音节声调不同（zhì 第四声，zhī 第一声），意思是照着样子制造。", "放置": "放置（fàng zhì）与纺织两个音节的声调都不同，意思是摆放、安置。", "防止": "防止（fáng zhǐ）与纺织两个音节的声调都不同，意思是提前避免某事发生。", "防治": "防治（fáng zhì）与纺织两个音节的声调都不同，意思是预防并治理（疾病、灾害）。", "反之": "反之（fǎn zhī）只把第一个音节的韵尾由 ng 换成 n，声调不变，意思是相反地。"}, "sentence_index": null, "correct_answer": "纺织"}, "level_3": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确：“在家纺织”指在家里把棉花或毛线做成布，与“奶奶年轻时”的语境相符。"}, {"text": "参军", "is_correct": false, "explanation": "语义：参军要离开家进入部队，与“在家”的语境矛盾。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差是外出办公，与“在家”的语境矛盾。"}, {"text": "登山", "is_correct": false, "explanation": "搭配：“在家登山”不搭配，登山必须到山上去。"}], "explanations": {"纺织": "正确：“在家纺织”指在家里把棉花或毛线做成布，与“奶奶年轻时”的语境相符。", "参军": "语义：参军要离开家进入部队，与“在家”的语境矛盾。", "出差": "语义：出差是外出办公，与“在家”的语境矛盾。", "登山": "搭配：“在家登山”不搭配，登山必须到山上去。"}, "sentence_index": 0, "correct_answer": "纺织"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用柳条纺织了一只篮子。", "explanation": "这里应该用〈编织〉。纺织是把棉花或毛线做成布，用柳条做篮子要说“编织”。"}, {"text": "她每天晚上在家修电脑。", "explanation": "这里应该用〈修〉。纺织只指把棉花或毛线做成布，修电脑要用“修”。"}, {"text": "这床被子是用纺织做的。", "explanation": "这里应该用〈棉絮〉。纺织是做布的活动，不是可以拿来做被子的填充材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纺织", "is_correct": true, "explanation": "正确：“都会纺织”说的是一种手艺，与“村里的女人”的语境相符。"}, {"text": "出国", "is_correct": false, "explanation": "语义：出国不是一种技能，“村里的女人都会出国”不合常理。"}, {"text": "高考", "is_correct": false, "explanation": "搭配：“高考”是一次考试，不能说“都会高考”来表示技能。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”必须带宾语，“都会参加”缺少对象，句子不完整。"}], "explanations": {"纺织": "正确：“都会纺织”说的是一种手艺，与“村里的女人”的语境相符。", "出国": "语义：出国不是一种技能，“村里的女人都会出国”不合常理。", "高考": "搭配：“高考”是一次考试，不能说“都会高考”来表示技能。", "参加": "配价：“参加”必须带宾语，“都会参加”缺少对象，句子不完整。"}, "sentence_index": 6, "correct_answer": "纺织"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们用泥土纺织了一个陶罐。", "explanation": "这里应该用〈烧制〉。纺织只指把棉花或毛线做成布，做陶罐要用“烧制”，不能用纺织。"}, {"text": "他们用石头纺织了一座桥。", "explanation": "这里应该用〈建造〉。纺织只指把棉花或毛线做成布，修桥要用“建造”。"}, {"text": "他们用木头纺织了一张桌子。", "explanation": "这里应该用〈制作〉。纺织只指把棉花或毛线做成布，做桌子要用“制作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把棉花纺织布。", "corrected_sentence": "她把棉花纺织成布。", "error_description": "“把”字句中，“纺织”后要带结果补语“成”，应说“把棉花纺织成布”，不能说“把棉花纺织布”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她纺织的很好。", "corrected_sentence": "她纺织得很好。", "error_description": "“纺织”后接程度补语要用“得”，不能用“的”，应说“她纺织得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d59b5ce-fd48-4a0b-a2ec-fd9cc28187a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
