INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26248, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "水有多少。", "primary_collocate": null, "pronunciation": "shuǐ liàng", "ipa": "ʂueɪ˨˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "洗衣机会自己选择水量。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，水池的水量变多了。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看杯里的水量。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小河的水量不大。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煮汤的时候，水量不要太多。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们测一测瓶子里的水量。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个水库的水量够全城用一年。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水量太少，花很快就枯了。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨水多，湖的水量最大。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，河流的水量慢慢减少。", "target_word": "水量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用水量", "label": "复合词"}, {"form": "降水量", "label": "复合词"}], "register": "中性", "sense_fingerprint": "水的多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad6e0189-8008-40a6-84a5-e78766ecfcdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水量", "is_correct": true, "explanation": "正确。洗衣机可以自动选择的是“水量”这一设定。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：洗衣机不能选择颜色，与“自己选择”的语义不合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：洗衣机没有“身高”可以选择，句意不通。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“选择”后接的应是可调节的设定，“字体”不是洗衣机的设定。"}], "explanations": {"水量": "正确。洗衣机可以自动选择的是“水量”这一设定。", "颜色": "语义：洗衣机不能选择颜色，与“自己选择”的语义不合。", "身高": "语义：洗衣机没有“身高”可以选择，句意不通。", "字体": "搭配：“选择”后接的应是可调节的设定，“字体”不是洗衣机的设定。"}, "sentence_index": 0, "correct_answer": "水量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的水量很高，要注意防洪。", "explanation": "这里应该用〈水位〉。“水量”指水的多少，水面的高低要用“水位”。"}, {"text": "这条小河的一块水量不大。", "explanation": "量词：“块”用于块状东西，“水量”不能用“块”计量。"}, {"text": "这条小河的水量很甜。", "explanation": "语义：这里把〈水量〉当成了味道来用。“水量”指水的多少，不指味道，不能用来描述口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水量", "is_correct": true, "explanation": "正确。水库里能供全城用的是“水量”，与“够……用”搭配。"}, {"text": "存款", "is_correct": false, "explanation": "语义：水库没有存款，与句意不符。"}, {"text": "知识", "is_correct": false, "explanation": "语义：知识不能供全城用，与水库的语义不合。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“够……用”要求的主语是可消耗的资源，“工资”不能与水库搭配。"}], "explanations": {"水量": "正确。水库里能供全城用的是“水量”，与“够……用”搭配。", "存款": "语义：水库没有存款，与句意不符。", "知识": "语义：知识不能供全城用，与水库的语义不合。", "工资": "搭配：“够……用”要求的主语是可消耗的资源，“工资”不能与水库搭配。"}, "sentence_index": 6, "correct_answer": "水量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水量深三米。", "explanation": "这里应该用〈水深〉。“水深”指水面到河底的距离，是长度；“水量”指水的多少，不能按长度来说。"}, {"text": "秋天，河流的两粒水量慢慢减少。", "explanation": "量词：“粒”用于颗粒状东西，“水量”不能用“粒”计量。"}, {"text": "秋天，河流的水量慢慢地变长了。", "explanation": "搭配：“水量”说多少，“变长”说长度，不能用于水量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场雨过后，湖里的个水量明显增多了。", "corrected_sentence": "这场雨过后，湖里的水量明显增多了。", "error_description": "错误：“个”前面缺少指示词或数词，“湖里的个水量”不成立。正确：去掉“个”，说“湖里的水量明显增多了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (26248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月河里的一只水量增加了。", "corrected_sentence": "这个月河里的水量增加了。", "error_description": "错误：“只”只用于动物或成对的东西，不能用来计量“水量”。正确：去掉“一只”，说“这个月河里的水量增加了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c9fe144-04d3-4520-97fc-b7f63d002582') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
